export const quizBank = [{"id":"backtracking/n-queens#0","route":"/backtracking/n-queens","section":"backtracking","subject":"dsa","title":"N-Queens – Backtracking Visualizer","question":"What does backtracking do in N-Queens when a queen can't be placed?","options":["Restarts the entire algorithm from scratch","Places a queen anyway and marks conflicts","Removes the most recently placed queen and tries the next column","Swaps two queens to resolve the conflict"],"correct":2,"explanation":"Backtracking removes the last placed queen (board[row] = -1) and tries the next column. If no column works in that row, it backtracks further to the previous row."},{"id":"backtracking/n-queens#1","route":"/backtracking/n-queens","section":"backtracking","subject":"dsa","title":"N-Queens – Backtracking Visualizer","question":"How many solutions does the 8-Queens problem have?","options":["8 solutions","24 solutions","64 solutions","92 solutions"],"correct":3,"explanation":"The 8-Queens problem has exactly 92 distinct solutions. The 4×4 board has 2, 5×5 has 10, 6×6 has 4, 7×7 has 40."},{"id":"backtracking/n-queens#2","route":"/backtracking/n-queens","section":"backtracking","subject":"dsa","title":"N-Queens – Backtracking Visualizer","question":"Why do we only check columns and diagonals — not rows — for queen attacks?","options":["Queens cannot attack in rows","We place exactly one queen per row by design — row conflicts are impossible","Row checking would make the algorithm too slow","Diagonals cover row attacks implicitly"],"correct":1,"explanation":"The algorithm places queens row by row — one per row. Since only one queen ever occupies each row, row conflicts are structurally impossible. We only need to check columns and diagonals."},{"id":"backtracking/rat-in-a-maze#0","route":"/backtracking/rat-in-a-maze","section":"backtracking","subject":"dsa","title":"Rat in a Maze – Backtracking Visualizer","question":"In what order does the standard Rat in a Maze algorithm try moves?","options":["Left, Right, Up, Down","Random order each step","Down, Right, Up, Left (or similar fixed order)","It tries the direction closest to the goal first"],"correct":2,"explanation":"The standard recursive implementation uses a fixed direction order — commonly Down and Right first. This is a depth-first search: it fully explores one direction before trying alternatives, which is why you see the rat move in straight lines before backtracking."},{"id":"backtracking/rat-in-a-maze#1","route":"/backtracking/rat-in-a-maze","section":"backtracking","subject":"dsa","title":"Rat in a Maze – Backtracking Visualizer","question":"What is the base case that signals a solution is found?","options":["When the rat has visited all cells","When the rat reaches cell (n-1, n-1)","When no backtracking steps remain","When all walls have been checked"],"correct":1,"explanation":"The recursion terminates with success when r == n-1 && c == n-1. At that point the current path from (0,0) to (n-1,n-1) is a valid solution."},{"id":"backtracking/rat-in-a-maze#2","route":"/backtracking/rat-in-a-maze","section":"backtracking","subject":"dsa","title":"Rat in a Maze – Backtracking Visualizer","question":"What distinguishes Rat in a Maze from BFS shortest-path finding?","options":["Backtracking finds all solutions; BFS finds only one","BFS explores level by level and guarantees the shortest path; backtracking uses DFS and finds a path but not necessarily the shortest","Backtracking is faster for large mazes","They are identical algorithms with different names"],"correct":1,"explanation":"BFS explores cells level by level and guarantees the shortest path. Backtracking uses depth-first search — it finds a valid path quickly but may not be the shortest. Backtracking shines when you need all solutions or when the constraint space is complex."},{"id":"backtracking/word-search#0","route":"/backtracking/word-search","section":"backtracking","subject":"dsa","title":"Word Search – Backtracking Visualizer","question":"What does backtracking do when a grid cell doesn't match the next character of the target word?","options":["Marks the cell permanently as visited and skips it","Stops the entire search and returns not found","Returns immediately without modifying any state","Tries all four directions before giving up"],"correct":2,"explanation":"When a cell doesn't match, the algorithm returns immediately without changing any state — no path extension, no marking. The outer loop moves on to the next direction or starting cell."},{"id":"backtracking/word-search#1","route":"/backtracking/word-search","section":"backtracking","subject":"dsa","title":"Word Search – Backtracking Visualizer","question":"Why must cells in the current path be marked as visited?","options":["To speed up the search","To prevent using the same cell twice in one path","To mark cells that have been fully explored","Required by the grid data structure"],"correct":1,"explanation":"A word can't reuse the same cell. Marking cells on the current path prevents cycles — without this, the search could loop back and match the same cell multiple times."},{"id":"backtracking/word-search#2","route":"/backtracking/word-search","section":"backtracking","subject":"dsa","title":"Word Search – Backtracking Visualizer","question":"What is the time complexity of Word Search on an m×n grid for a word of length L?","options":["O(m×n×L)","O(m×n×4^L)","O(m×n×log L)","O(4^(m×n))"],"correct":1,"explanation":"From each starting cell (m×n options), DFS explores up to 4 directions at each of L steps, giving O(m×n×4^L). In practice, mismatches prune most branches early."},{"id":"basics/linked-list-circular#0","route":"/basics/linked-list-circular","section":"basics","subject":"dsa","title":"Circular Linked List Visualizer","question":"In a circular linked list, how do you detect that a traversal has visited all nodes?","options":["Check for NULL — the last node's next is NULL","Stop when next == head — you've looped around","Count nodes and stop at size","The traversal never needs to stop"],"correct":1,"explanation":"Circular lists have no NULL — the last node's next points back to head. Traversal ends when you detect next == head (or the current node == head on the second visit)."},{"id":"basics/linked-list-circular#1","route":"/basics/linked-list-circular","section":"basics","subject":"dsa","title":"Circular Linked List Visualizer","question":"What data structure models a circular singly linked list well in practice?","options":["A hash table for fast lookup","A round-robin CPU scheduler or circular buffer","A binary heap for priority","A stack for LIFO access"],"correct":1,"explanation":"Round-robin schedulers cycle through processes indefinitely — the circular structure means after the last process, you naturally return to the first, no special case needed."},{"id":"basics/linked-list-circular#2","route":"/basics/linked-list-circular","section":"basics","subject":"dsa","title":"Circular Linked List Visualizer","question":"How many pointer updates are needed when inserting a node at the tail of a circular singly linked list?","options":["1 — just set old tail.next = new node","2 — old tail.next = new, new.next = head","3 — update head, tail, and new node","4 — both directions like doubly"],"correct":1,"explanation":"New tail insertion: old_tail.next = new_node, new_node.next = head. Two pointer updates maintain the circular invariant."},{"id":"basics/linked-list-circular-doubly#0","route":"/basics/linked-list-circular-doubly","section":"basics","subject":"dsa","title":"Circular Doubly Linked List Visualizer","question":"In a circular doubly linked list, what do head.prev and tail.next point to?","options":["Both point to NULL","head.prev = NULL, tail.next = NULL","head.prev = tail, tail.next = head","head.prev = head, tail.next = tail"],"correct":2,"explanation":"In a circular doubly linked list, the ring is closed in both directions: head.prev = tail and tail.next = head. There are no NULL pointers in the list itself."},{"id":"basics/linked-list-circular-doubly#1","route":"/basics/linked-list-circular-doubly","section":"basics","subject":"dsa","title":"Circular Doubly Linked List Visualizer","question":"Which real-world data structure uses a circular doubly linked list internally?","options":["Python dict (hash map)","LRU cache and Linux kernel's list_head","Java ArrayList","Binary search tree"],"correct":1,"explanation":"LRU caches use a circular doubly linked list for O(1) move-to-front. Linux kernel's list_head macro is also a circular doubly linked list used throughout the kernel."},{"id":"basics/linked-list-circular-doubly#2","route":"/basics/linked-list-circular-doubly","section":"basics","subject":"dsa","title":"Circular Doubly Linked List Visualizer","question":"What is the time complexity of inserting a node adjacent to any node for which you already have a pointer?","options":["O(n) — traverse to find the position","O(log n) — binary skip","O(1) — update 4 pointers locally","O(n²) — update all nodes"],"correct":2,"explanation":"With a direct pointer to a node, inserting before or after it updates exactly 4 pointers (new.prev, new.next, neighbor.next, neighbor.prev) — O(1) regardless of list size."},{"id":"basics/linked-list-doubly#0","route":"/basics/linked-list-doubly","section":"basics","subject":"dsa","title":"Doubly Linked List Visualizer","question":"What is the time complexity of deleting a node when you already have a direct pointer to it in a doubly linked list?","options":["O(n) — must traverse to find predecessor","O(1) — update prev.next and next.prev directly","O(log n) — skip-list traversal","O(n²) — nested pointer scan"],"correct":1,"explanation":"With a pointer to the node, both prev and next are directly accessible. Set prev.next = node.next and node.next.prev = node.prev — no traversal needed, O(1)."},{"id":"basics/linked-list-doubly#1","route":"/basics/linked-list-doubly","section":"basics","subject":"dsa","title":"Doubly Linked List Visualizer","question":"How many pointer assignments are needed when inserting a node between two existing nodes?","options":["1","2","4","6"],"correct":2,"explanation":"Inserting X between A and B: X.prev = A, X.next = B, A.next = X, B.prev = X — exactly 4 pointer assignments regardless of list size."},{"id":"basics/linked-list-doubly#2","route":"/basics/linked-list-doubly","section":"basics","subject":"dsa","title":"Doubly Linked List Visualizer","question":"Which operation is O(1) in a doubly linked list but O(n) in a singly linked list (with head pointer only)?","options":["Search by value","Insert at head","Delete the tail node","Forward traversal"],"correct":2,"explanation":"Singly LL needs to traverse to find the second-to-last node for tail deletion (O(n)). Doubly LL: tail.prev gives the predecessor directly — O(1)."},{"id":"basics/lists-array#0","route":"/basics/lists-array","section":"basics","subject":"dsa","title":"Array List Visualizer – Insert, Delete & Access Animation","question":"What happens when you insert into a full dynamic array?","options":["It throws an exception immediately","It doubles its capacity and copies all elements","It deletes the oldest element to make room","It silently drops the new element"],"correct":1,"explanation":"Dynamic arrays double their capacity (amortized O(1) append) — resizing is expensive but infrequent. This is how Python lists and Java ArrayLists work."},{"id":"basics/lists-array#1","route":"/basics/lists-array","section":"basics","subject":"dsa","title":"Array List Visualizer – Insert, Delete & Access Animation","question":"Why is random access (arr[i]) O(1) in an array but O(n) in a linked list?","options":["Arrays use binary search","Array elements are at fixed memory offsets, so address = base + i × size","Arrays cache the last accessed index","Linked lists use hash maps internally"],"correct":1,"explanation":"Array elements are contiguous in memory. The address of index i = base_address + i × element_size — a direct O(1) calculation."},{"id":"basics/lists-array#2","route":"/basics/lists-array","section":"basics","subject":"dsa","title":"Array List Visualizer – Insert, Delete & Access Animation","question":"What is the amortized time complexity of appending to a dynamic array?","options":["O(n) always — copies take linear time","O(n²) — quadratic due to repeated copying","O(1) amortized — doubling makes resizes rare","O(log n) — balanced resizing strategy"],"correct":2,"explanation":"While a single resize is O(n), it happens at size 1, 2, 4, 8... The total work per n appends is O(n), making each append O(1) amortized."},{"id":"basics/lists-linked-list#0","route":"/basics/lists-linked-list","section":"basics","subject":"dsa","title":"Linked List Visualizer – Insert, Delete & Traverse Animation","question":"What is the time complexity of accessing an element at index k in a linked list?","options":["O(1) — direct address calculation","O(log k) — binary search","O(k) — must traverse from head","O(n²) — nested traversal"],"correct":2,"explanation":"Linked lists have no direct indexing. You must start at the head and follow k next pointers — O(k) which is O(n) worst case."},{"id":"basics/lists-linked-list#1","route":"/basics/lists-linked-list","section":"basics","subject":"dsa","title":"Linked List Visualizer – Insert, Delete & Traverse Animation","question":"Why is inserting at the head of a linked list O(1)?","options":["It uses a cache for quick access","No traversal needed — just create a node and update head","The head is stored in a hash map","Linked lists pre-allocate head space"],"correct":1,"explanation":"Head insertion: create node, set node.next = head, set head = node. No traversal. This is O(1) regardless of list size."},{"id":"basics/lists-linked-list#2","route":"/basics/lists-linked-list","section":"basics","subject":"dsa","title":"Linked List Visualizer – Insert, Delete & Traverse Animation","question":"Which scenario gives the linked list a clear advantage over an array?","options":["Frequent random access by index","Frequent insertions and deletions at arbitrary positions","Sorting large datasets quickly","Storing data with predictable size"],"correct":1,"explanation":"Linked lists excel at insert/delete at known positions — update 2 pointers, O(1). Arrays need to shift O(n) elements."},{"id":"basics/queues-array#0","route":"/basics/queues-array","section":"basics","subject":"dsa","title":"Queue (Array) Visualizer – Enqueue & Dequeue Animation","question":"What does FIFO stand for?","options":["First In First Out","Fast Input Forwarding Order","Fixed Index For Output","First Index From Overflow"],"correct":0,"explanation":"FIFO = First In, First Out. Like a real queue — the first person to join is the first to leave."},{"id":"basics/queues-array#1","route":"/basics/queues-array","section":"basics","subject":"dsa","title":"Queue (Array) Visualizer – Enqueue & Dequeue Animation","question":"In a queue, where are elements added and removed?","options":["Both added and removed at front","Added at rear, removed at front","Added at front, removed at rear","Added and removed at rear"],"correct":1,"explanation":"Enqueue adds to the REAR. Dequeue removes from the FRONT. This is what makes it FIFO."},{"id":"basics/queues-array#2","route":"/basics/queues-array","section":"basics","subject":"dsa","title":"Queue (Array) Visualizer – Enqueue & Dequeue Animation","question":"Why is a circular array preferred for implementing a queue?","options":["It uses less memory overall","It avoids shifting elements, giving O(1) dequeue","It allows random access","It prevents stack overflow"],"correct":1,"explanation":"A circular array wraps around — the front pointer moves forward instead of shifting all elements, making dequeue O(1)."},{"id":"basics/queues-linked-list#0","route":"/basics/queues-linked-list","section":"basics","subject":"dsa","title":"Queue (Linked List) Visualizer – Node-Based Queue Animation","question":"A linked list queue uses two pointers — what are they called?","options":["Head and Tail","Front and Rear","Top and Bottom","Start and End"],"correct":1,"explanation":"Front points to the dequeue end; Rear points to the enqueue end. Both pointers are NULL when the queue is empty."},{"id":"basics/queues-linked-list#1","route":"/basics/queues-linked-list","section":"basics","subject":"dsa","title":"Queue (Linked List) Visualizer – Node-Based Queue Animation","question":"What is the time complexity of Dequeue in a linked list queue?","options":["O(n) — must traverse the list","O(log n) — binary search","O(1) — just move the front pointer","O(n²) — double traversal"],"correct":2,"explanation":"Dequeue is O(1): just read front.value, move front to front.next. No shifting required — a major advantage over array queues."},{"id":"basics/queues-linked-list#2","route":"/basics/queues-linked-list","section":"basics","subject":"dsa","title":"Queue (Linked List) Visualizer – Node-Based Queue Animation","question":"When does a linked list queue become empty?","options":["When front equals rear","When both front and rear are NULL","When size reaches zero and we reset front/rear","B and C are both correct"],"correct":3,"explanation":"After dequeueing the last node, front becomes NULL. We also set rear to NULL to fully reset. Both conditions indicate an empty queue."},{"id":"basics/stack-array#0","route":"/basics/stack-array","section":"basics","subject":"dsa","title":"Stack (Array) Visualizer – Push, Pop & Peek Animation","question":"What does LIFO stand for?","options":["Linked Input FIFO Ordering","Last In First Out","Linear Input Forward Output","Last Index From Overlap"],"correct":1,"explanation":"LIFO = Last In, First Out. Like a stack of plates — you add and remove from the top."},{"id":"basics/stack-array#1","route":"/basics/stack-array","section":"basics","subject":"dsa","title":"Stack (Array) Visualizer – Push, Pop & Peek Animation","question":"What is the time complexity of Push in an array-based stack?","options":["O(n)","O(log n)","O(n²)","O(1)"],"correct":3,"explanation":"Push is O(1) — we just increment the top pointer and assign the value. No shifting needed."},{"id":"basics/stack-array#2","route":"/basics/stack-array","section":"basics","subject":"dsa","title":"Stack (Array) Visualizer – Push, Pop & Peek Animation","question":"What error occurs when pushing to a full array stack?","options":["Stack Underflow","Null Pointer Exception","Stack Overflow","Index Out of Bounds"],"correct":2,"explanation":"Stack Overflow happens when you push to a full stack. Stack Underflow is the reverse — popping from empty."},{"id":"basics/stack-linked-list#0","route":"/basics/stack-linked-list","section":"basics","subject":"dsa","title":"Stack (Linked List) Visualizer – Node-Based Stack Animation","question":"In a linked list stack, where is the TOP of the stack?","options":["The last node in the list","The head node","A separate pointer variable","The middle of the list"],"correct":1,"explanation":"The HEAD node is the TOP of the stack. Push creates a new head; Pop removes the head — always O(1)."},{"id":"basics/stack-linked-list#1","route":"/basics/stack-linked-list","section":"basics","subject":"dsa","title":"Stack (Linked List) Visualizer – Node-Based Stack Animation","question":"What key advantage does a linked list stack have over an array stack?","options":["Better cache performance","Fixed maximum size","Dynamic size — no overflow limit","Faster peek operation"],"correct":2,"explanation":"Linked list stacks have no fixed size limit (only system memory). Array stacks need a pre-defined max capacity."},{"id":"basics/stack-linked-list#2","route":"/basics/stack-linked-list","section":"basics","subject":"dsa","title":"Stack (Linked List) Visualizer – Node-Based Stack Animation","question":"What is the extra memory cost per element in a linked list stack?","options":["Zero — same as array","One pointer (next reference)","Two pointers (prev and next)","An entire memory page"],"correct":1,"explanation":"Each node stores its value PLUS a next pointer — extra overhead vs. arrays which only store values."},{"id":"bit-manipulation/count-set-bits#0","route":"/bit-manipulation/count-set-bits","section":"bit-manipulation","subject":"dsa","title":"Count Set Bits (Brian Kernighan) – Bit Manipulation Visualizer","question":"Why does n & (n−1) always clear the lowest set bit of n?","options":["Because subtracting 1 shifts every bit right by one position","Because n−1 flips all bits from the lowest set bit downward, so AND-ing with n zeroes out that bit and those below it","Because AND always sets bits to 0","Because n and n−1 share no bits in common"],"correct":1,"explanation":"Subtracting 1 from n flips the lowest set bit to 0 and turns all lower 0-bits to 1. When you AND this with the original n, the lowest set bit becomes 0 and all the lower bits (now 1 in n−1) were already 0 in n — so they stay 0. Every higher bit is unchanged."},{"id":"bit-manipulation/count-set-bits#1","route":"/bit-manipulation/count-set-bits","section":"bit-manipulation","subject":"dsa","title":"Count Set Bits (Brian Kernighan) – Bit Manipulation Visualizer","question":"How many iterations does Brian Kernighan's algorithm take for n = 12 (binary 1100)?","options":["4 (one per bit position)","2 (one per set bit)","3","12"],"correct":1,"explanation":"12 in binary is 1100, which has exactly 2 set bits. Brian Kernighan's algorithm iterates once per set bit, not once per total bit width. For n=12: first iteration gives 12 & 11 = 8 (1000), second gives 8 & 7 = 0. Done in 2 steps."},{"id":"bit-manipulation/count-set-bits#2","route":"/bit-manipulation/count-set-bits","section":"bit-manipulation","subject":"dsa","title":"Count Set Bits (Brian Kernighan) – Bit Manipulation Visualizer","question":"What is the worst-case time complexity of Brian Kernighan's algorithm for a 32-bit integer?","options":["O(1)","O(32) = O(1) constant","O(n) where n is the integer value","O(log n)"],"correct":1,"explanation":"A 32-bit integer can have at most 32 set bits. The algorithm runs in at most 32 iterations regardless of the value of n — it's bounded by the word size, not the magnitude of n. This is conventionally written O(1) or O(log n) where log n is the number of bits."},{"id":"bit-manipulation/power-of-two#0","route":"/bit-manipulation/power-of-two","section":"bit-manipulation","subject":"dsa","title":"Power of Two – Bit Manipulation Visualizer","question":"Why does n & (n−1) == 0 imply n is a power of two?","options":["Powers of two always have an even binary representation","Powers of two have exactly one set bit; subtracting 1 flips all lower bits, so AND-ing gives 0","Dividing by 2 repeatedly always gives 1 for powers of two","n & (n−1) equals 0 for all even numbers"],"correct":1,"explanation":"A power of two has exactly one 1-bit (e.g., 8 = 1000). Subtracting 1 flips that bit to 0 and turns all lower bits to 1 (7 = 0111). The AND of these two values is 0000. Any non-power-of-two has at least two set bits, so n−1 still shares at least one set bit with n and the AND is non-zero."},{"id":"bit-manipulation/power-of-two#1","route":"/bit-manipulation/power-of-two","section":"bit-manipulation","subject":"dsa","title":"Power of Two – Bit Manipulation Visualizer","question":"What is the time complexity of the n & (n−1) == 0 check?","options":["O(n)","O(log n)","O(1)","O(n²)"],"correct":2,"explanation":"The check is a single bitwise AND followed by a comparison — both are O(1) hardware operations regardless of the value of n. There are no loops or recursion."},{"id":"bit-manipulation/power-of-two#2","route":"/bit-manipulation/power-of-two","section":"bit-manipulation","subject":"dsa","title":"Power of Two – Bit Manipulation Visualizer","question":"Why must we add the condition n > 0 before checking n & (n−1) == 0?","options":["Because 0 would cause an overflow","Because 0 & (0−1) = 0 & 4294967295 = 0, which would incorrectly report 0 as a power of two","Because negative numbers are always powers of two","Because the formula only works for odd numbers"],"correct":1,"explanation":"0 − 1 wraps to 0xFFFFFFFF (all 1s) in 32-bit unsigned arithmetic. 0 AND 0xFFFFFFFF = 0, which passes the test — but 0 is not a power of two. Adding n > 0 as a guard eliminates this false positive."},{"id":"bit-manipulation/single-number#0","route":"/bit-manipulation/single-number","section":"bit-manipulation","subject":"dsa","title":"Single Number (XOR) – Bit Manipulation Visualizer","question":"Why does XOR-ing all elements find the single non-repeated number?","options":["XOR counts the frequency of each bit position","XOR is commutative and associative, and a ^ a = 0, so all pairs cancel out leaving only the unique element","XOR adds all numbers and divides by 2","XOR flips all bits so duplicates become zero"],"correct":1,"explanation":"a ^ a = 0 means any value XOR'd with itself produces 0. Since XOR is commutative and associative, all duplicate pairs cancel to 0 regardless of order, leaving only the element with no pair."},{"id":"bit-manipulation/single-number#1","route":"/bit-manipulation/single-number","section":"bit-manipulation","subject":"dsa","title":"Single Number (XOR) – Bit Manipulation Visualizer","question":"What is the time and space complexity of the XOR approach?","options":["O(n) time, O(n) space","O(n log n) time, O(1) space","O(n) time, O(1) space","O(1) time, O(1) space"],"correct":2,"explanation":"We make a single linear pass through the array (O(n) time) and use only one accumulator variable (O(1) space). No hash map or sorting is needed."},{"id":"bit-manipulation/single-number#2","route":"/bit-manipulation/single-number","section":"bit-manipulation","subject":"dsa","title":"Single Number (XOR) – Bit Manipulation Visualizer","question":"If the array is [3, 5, 3, 7, 5], what does XOR-ing all elements return?","options":["3","5","7","0"],"correct":2,"explanation":"3 ^ 3 = 0 and 5 ^ 5 = 0. The accumulator becomes 0 ^ 7 = 7. The unique number is 7."},{"id":"computer-networks/arp-and-switching#0","route":"/computer-networks/arp-and-switching","section":"computer-networks","subject":"cs-core","title":"ARP and Switching – MAC Learning, Flooding and Forwarding","question":"What destination MAC address does an ARP request use, and what about the reply?","options":["Both are broadcast to ff:ff:ff:ff:ff:ff","The request is broadcast to ff:ff:ff:ff:ff:ff; the reply is unicast back to the asker's MAC","The request goes to the default gateway's MAC; the reply is broadcast","Both are unicast to the switch"],"correct":1,"explanation":"The asker does not know the target's MAC — that is the question — so the request must reach everyone on the LAN. The target learns the asker's MAC from the request itself, so its reply can go straight back as a unicast frame."},{"id":"computer-networks/arp-and-switching#1","route":"/computer-networks/arp-and-switching","section":"computer-networks","subject":"cs-core","title":"ARP and Switching – MAC Learning, Flooding and Forwarding","question":"A switch receives a frame whose destination MAC is not in its MAC table. What does it do?","options":["Drops it","Sends an ARP request for that MAC","Floods it out every port except the one it arrived on","Sends it back to the sender"],"correct":2,"explanation":"An unknown destination is flooded — every other port gets a copy, and only the owner accepts it. ARP maps IP to MAC; a switch never uses ARP to find ports. It learns the destination's port only when that host sends a frame of its own."},{"id":"computer-networks/arp-and-switching#2","route":"/computer-networks/arp-and-switching","section":"computer-networks","subject":"cs-core","title":"ARP and Switching – MAC Learning, Flooding and Forwarding","question":"Two hosts talk, go quiet for ten minutes, then talk again without any ARP traffic. Why might the switch flood their first frame?","options":["The ARP cache expired","The switch's MAC table entries aged out (after 300 s by default) while the hosts' ARP caches still held each other's MAC","Switches flood the first frame of every conversation","The hosts changed MAC addresses"],"correct":1,"explanation":"The two caches age independently. A host with a live ARP entry sends a unicast frame without broadcasting, so nothing has re-taught the switch where the destination is. It floods until that host sends something. Mismatched ARP and MAC-table timers are a classic cause of unicast flooding."},{"id":"computer-networks/distance-vector-routing#0","route":"/computer-networks/distance-vector-routing","section":"computer-networks","subject":"cs-core","title":"Distance Vector Routing – Bellman-Ford, Count-to-Infinity, Poison Reverse","question":"Routers A–B–C–D sit in a line with cost-1 links, and C–D fails. Without poison reverse, why does it take many rounds for B and C to give up on D?","options":["Their timers have to expire first","C believes B's old advertisement (D at distance 2), not knowing that route went through C itself; they then raise each other's estimate a little each round","Bellman-Ford needs V − 1 rounds no matter what","D keeps advertising itself"],"correct":1,"explanation":"A distance vector carries no path, so C cannot tell that B's distance 2 was via C. Each round they each add a link cost to the other's last claim — 3, 4, 5, … — until they reach the protocol's infinity (16 in RIP). That is count-to-infinity."},{"id":"computer-networks/distance-vector-routing#1","route":"/computer-networks/distance-vector-routing","section":"computer-networks","subject":"cs-core","title":"Distance Vector Routing – Bellman-Ford, Count-to-Infinity, Poison Reverse","question":"What does poison reverse do?","options":["It removes a failed link from every routing table immediately","If X routes to a destination through neighbour Y, X tells Y that destination is unreachable","It doubles the cost of any link that failed recently","It floods the failure to every router"],"correct":1,"explanation":"Y should never route back through X for a destination X reaches through Y, so X advertises ∞ to Y for it. That kills two-router loops instantly. Loops through three or more routers can still count to infinity — the triangle preset shows one."},{"id":"computer-networks/distance-vector-routing#2","route":"/computer-networks/distance-vector-routing","section":"computer-networks","subject":"cs-core","title":"Distance Vector Routing – Bellman-Ford, Count-to-Infinity, Poison Reverse","question":"A router's neighbours advertise distances to Z of: N1 = 4 (link cost 2), N2 = 1 (link cost 6), N3 = 3 (link cost 3). What is its distance to Z?","options":["1","6","7","4"],"correct":1,"explanation":"Bellman-Ford takes the minimum of link cost + advertised distance: N1 gives 2 + 4 = 6, N2 gives 6 + 1 = 7, N3 gives 3 + 3 = 6. The minimum is 6 — the neighbour advertising the smallest distance is not necessarily the best next hop."},{"id":"computer-networks/dns-resolution#0","route":"/computer-networks/dns-resolution","section":"computer-networks","subject":"cs-core","title":"DNS Resolution Visualizer – Root, TLD, Authoritative and Caching","question":"Who walks the hierarchy from the root to the authoritative server during a normal lookup?","options":["The browser","The stub resolver in the operating system","The recursive resolver, on the stub's behalf","The root server forwards the query down the tree"],"correct":2,"explanation":"The stub sends one recursive query and waits. The recursive resolver does the iterative work: it asks the root, follows the referral to the TLD, follows that to the authoritative server, and caches everything along the way. Root and TLD servers only ever refer — they never forward a query themselves."},{"id":"computer-networks/dns-resolution#1","route":"/computer-networks/dns-resolution","section":"computer-networks","subject":"cs-core","title":"DNS Resolution Visualizer – Root, TLD, Authoritative and Caching","question":"A resolver cached www.example.com A 203.0.113.10 with TTL 300 at t = 0. Another client asks for it at t = 200. What happens?","options":["The resolver re-queries the authoritative server, because a new client asked","It answers from cache and passes on a TTL of 100","It answers from cache and passes on a TTL of 300","It must re-query because 200 seconds is more than half the TTL"],"correct":1,"explanation":"The record is still valid for 300 − 200 = 100 seconds, so it is served from cache — and the TTL is counted down, so downstream caches can keep it only until the original expiry. Resolvers do not reset TTLs for new clients."},{"id":"computer-networks/dns-resolution#2","route":"/computer-networks/dns-resolution","section":"computer-networks","subject":"cs-core","title":"DNS Resolution Visualizer – Root, TLD, Authoritative and Caching","question":"Why do root servers handle only a small share of the world's DNS lookups?","options":["Most domains are registered without the root","Resolvers cache the TLD referrals for up to two days, so they rarely need to ask the root again","Browsers query TLD servers directly","Root servers drop most queries on purpose"],"correct":1,"explanation":"A resolver asks the root only when it holds no valid referral for the TLD. Those referrals carry long TTLs (two days for .com), so after the first lookup a busy resolver goes straight to the TLD or the authoritative server. Anycast spreads the remaining load across hundreds of root-server instances."},{"id":"computer-networks/http1-vs-http2-vs-http3#0","route":"/computer-networks/http1-vs-http2-vs-http3","section":"computer-networks","subject":"cs-core","title":"HTTP/1.1 vs HTTP/2 vs HTTP/3 – Head-of-Line Blocking Visualized","question":"On a single HTTP/1.1 connection, the first response is slow to generate. What happens to the other resources?","options":["They are sent while the server works on the first","They wait: one connection carries one request–response at a time, so everything queues behind the slow response","The browser cancels the slow request","TCP reorders the responses"],"correct":1,"explanation":"That is head-of-line blocking at the application layer. Pipelining was meant to help but still required responses in order, and browsers turned it off; instead they opened up to six parallel connections per host."},{"id":"computer-networks/http1-vs-http2-vs-http3#1","route":"/computer-networks/http1-vs-http2-vs-http3","section":"computer-networks","subject":"cs-core","title":"HTTP/1.1 vs HTTP/2 vs HTTP/3 – Head-of-Line Blocking Visualized","question":"An HTTP/2 connection carries four streams. One TCP segment belonging to stream 2 is lost. What happens to streams 1, 3 and 4?","options":["Nothing — HTTP/2 streams are independent","They stall too: TCP hands bytes to HTTP/2 strictly in order, so data after the gap waits until the retransmission arrives","Only stream 3 is affected, because it is next","The connection is closed and reopened"],"correct":1,"explanation":"HTTP/2 multiplexes streams, but they all ride one TCP byte stream. TCP does not know about streams; it will not deliver anything after a missing byte. One loss therefore stalls every stream — head-of-line blocking moved down into the transport."},{"id":"computer-networks/http1-vs-http2-vs-http3#2","route":"/computer-networks/http1-vs-http2-vs-http3","section":"computer-networks","subject":"cs-core","title":"HTTP/1.1 vs HTTP/2 vs HTTP/3 – Head-of-Line Blocking Visualized","question":"How does HTTP/3 avoid that?","options":["It uses a bigger TCP window","It runs over QUIC on UDP, which tracks ordering per stream, so a loss only delays the stream it belonged to","It retransmits every packet twice","It opens one TCP connection per stream"],"correct":1,"explanation":"QUIC builds reliability and ordering itself on top of UDP, per stream. A lost packet carrying stream 2 delays only stream 2; the others keep being delivered. QUIC also folds the TLS handshake into its own, saving a round trip on connection setup."},{"id":"computer-networks/link-state-routing#0","route":"/computer-networks/link-state-routing","section":"computer-networks","subject":"cs-core","title":"Link State Routing – LSA Flooding and Dijkstra Forwarding Tables","question":"What does a link-state router know that a distance-vector router never does?","options":["Its neighbours' distances to every destination","The complete topology: every router, every link and its cost","Only the next hop for each destination","The physical location of each router"],"correct":1,"explanation":"Flooding gives every router every LSA, so each one holds the whole map and computes its own shortest paths. A distance-vector router only ever learns its neighbours' claimed distances, which is why stale claims can make it count to infinity."},{"id":"computer-networks/link-state-routing#1","route":"/computer-networks/link-state-routing","section":"computer-networks","subject":"cs-core","title":"Link State Routing – LSA Flooding and Dijkstra Forwarding Tables","question":"Why does each LSA carry a sequence number?","options":["To encrypt the advertisement","So a router can tell a newer LSA from one it already holds — keeping the newest, dropping duplicates, and letting the flood stop","To count how many hops it has travelled","To order the links inside the LSA"],"correct":1,"explanation":"A router accepts and re-floods an LSA only if its sequence number is higher than the copy it already has from that origin. Duplicates are dropped, which ends the flood, and a link failure is announced with a higher number so it replaces the old description everywhere."},{"id":"computer-networks/link-state-routing#2","route":"/computer-networks/link-state-routing","section":"computer-networks","subject":"cs-core","title":"Link State Routing – LSA Flooding and Dijkstra Forwarding Tables","question":"Links: A–B cost 1, B–C cost 1, A–C cost 5. In A's forwarding table, what is the entry for C?","options":["Next hop C, cost 5","Next hop B, cost 2","Next hop B, cost 1","Next hop C, cost 2"],"correct":1,"explanation":"Dijkstra from A finalises B at 1, then reaches C through B at 1 + 1 = 2, beating the direct link at 5. The forwarding table keeps only the first hop of that path — B — and the total cost 2."},{"id":"computer-networks/osi-and-tcp-ip-layers#0","route":"/computer-networks/osi-and-tcp-ip-layers","section":"computer-networks","subject":"cs-core","title":"OSI and TCP/IP Layers – Encapsulation Visualized","question":"A switch receives a frame. Which header field does it use to decide where the frame goes?","options":["The destination IP address","The destination MAC address in the Ethernet header","The TCP destination port","The TTL"],"correct":1,"explanation":"A switch is a link-layer device. It looks the destination MAC up in its MAC table and forwards out one port (or floods if unknown). It never opens the IP packet — reading IP and rewriting the Ethernet header is what a router does."},{"id":"computer-networks/osi-and-tcp-ip-layers#1","route":"/computer-networks/osi-and-tcp-ip-layers","section":"computer-networks","subject":"cs-core","title":"OSI and TCP/IP Layers – Encapsulation Visualized","question":"A TCP segment carries 47 bytes of data with no options. How big is the Ethernet frame that carries it?","options":["67 bytes","87 bytes","101 bytes","105 bytes"],"correct":3,"explanation":"47 B of data + 20 B TCP header = 67 B segment; + 20 B IP header = 87 B packet; + 14 B Ethernet header + 4 B FCS trailer = 105 B frame. The 8-byte preamble and 12-byte gap are on the wire too, but they are not part of the frame."},{"id":"computer-networks/osi-and-tcp-ip-layers#2","route":"/computer-networks/osi-and-tcp-ip-layers","section":"computer-networks","subject":"cs-core","title":"OSI and TCP/IP Layers – Encapsulation Visualized","question":"On the receiving host, how does the IP layer know whether to hand its payload to TCP or to UDP?","options":["By the destination port number","By the EtherType field","By the protocol field in the IP header (6 = TCP, 17 = UDP)","It tries TCP first and falls back to UDP"],"correct":2,"explanation":"Each header names the layer above it. EtherType tells Ethernet that IP is inside; the IP protocol field tells IP that TCP (6) or UDP (17) is inside; ports then pick the socket. Ports belong to the transport header, which IP never parses."},{"id":"computer-networks/sliding-window-protocols#0","route":"/computer-networks/sliding-window-protocols","section":"computer-networks","subject":"cs-core","title":"Sliding Window Protocols – Stop-and-Wait, Go-Back-N, Selective Repeat","question":"Go-Back-N with window 4 has packets 2, 3, 4 and 5 outstanding. Packet 2 is lost; 3, 4 and 5 arrive. What happens when packet 2's timer expires?","options":["Only packet 2 is resent","Packets 2, 3, 4 and 5 are all resent","Packets 3, 4 and 5 are resent","Nothing — the receiver already has 3, 4 and 5"],"correct":1,"explanation":"A Go-Back-N receiver keeps no buffer: it discarded 3, 4 and 5 because 2 was missing, and kept re-sending ACK 1. So the sender goes back to 2 and resends everything outstanding. Selective Repeat would resend only packet 2."},{"id":"computer-networks/sliding-window-protocols#1","route":"/computer-networks/sliding-window-protocols","section":"computer-networks","subject":"cs-core","title":"Sliding Window Protocols – Stop-and-Wait, Go-Back-N, Selective Repeat","question":"With sequence numbers taken modulo m, how large can a Selective Repeat window be?","options":["m − 1","m / 2","m","2m"],"correct":1,"explanation":"If the window exceeded half the sequence space, a retransmitted old packet could carry the same number as a new packet the receiver is now waiting for, and be accepted as new data. Go-Back-N only needs a window of at most m − 1."},{"id":"computer-networks/sliding-window-protocols#2","route":"/computer-networks/sliding-window-protocols","section":"computer-networks","subject":"cs-core","title":"Sliding Window Protocols – Stop-and-Wait, Go-Back-N, Selective Repeat","question":"A link has a 30 ms round trip, packets take 1 ms to transmit, and the protocol is Stop-and-Wait. Roughly what fraction of the time is the link busy?","options":["About 3%","About 50%","About 97%","100%"],"correct":0,"explanation":"Stop-and-Wait sends one packet (1 ms) and then idles until the ACK returns, so utilisation is 1 / (1 + 30) ≈ 3%. Pipelining — keeping a window of W packets in flight — multiplies that by up to W, which is the whole reason sliding windows exist."},{"id":"computer-networks/subnetting-and-cidr#0","route":"/computer-networks/subnetting-and-cidr","section":"computer-networks","subject":"cs-core","title":"Subnetting and CIDR Calculator – Bits, Masks and Host Ranges","question":"How many usable host addresses does a /26 subnet have?","options":["26","62","64","30"],"correct":1,"explanation":"A /26 leaves 32 − 26 = 6 host bits: 2^6 = 64 addresses. The all-zeros address is the network and the all-ones address is the broadcast, so 62 are usable."},{"id":"computer-networks/subnetting-and-cidr#1","route":"/computer-networks/subnetting-and-cidr","section":"computer-networks","subject":"cs-core","title":"Subnetting and CIDR Calculator – Bits, Masks and Host Ranges","question":"What is the network address of 10.20.30.40/20?","options":["10.20.0.0","10.20.16.0","10.20.30.0","10.20.32.0"],"correct":1,"explanation":"A /20 mask is 255.255.240.0. Only the third octet is cut: 30 is 0001 1110, AND 1111 0000 gives 0001 0000 = 16. So the network is 10.20.16.0, a block running from 10.20.16.0 to 10.20.31.255."},{"id":"computer-networks/subnetting-and-cidr#2","route":"/computer-networks/subnetting-and-cidr","section":"computer-networks","subject":"cs-core","title":"Subnetting and CIDR Calculator – Bits, Masks and Host Ranges","question":"Are 172.16.5.14/29 and 172.16.5.17/29 on the same subnet?","options":["Yes — they differ only in the last octet","Yes — /29 subnets hold up to 8 addresses and they are 3 apart","No — /29 blocks are .8–.15 and .16–.23, so they fall in different blocks","It depends on the default gateway"],"correct":2,"explanation":"A /29 makes blocks of 8 that start at multiples of 8. 14 AND 248 = 8 and 17 AND 248 = 16 — different network addresses. Being numerically close says nothing; what matters is which block each falls in."},{"id":"computer-networks/tcp-congestion-control#0","route":"/computer-networks/tcp-congestion-control","section":"computer-networks","subject":"cs-core","title":"TCP Congestion Control – Slow Start, AIMD, Tahoe vs Reno","question":"A TCP Reno sender has cwnd = 20 segments when three duplicate ACKs arrive. What are ssthresh and cwnd afterwards (ignoring the temporary +3 inflation)?","options":["ssthresh 20, cwnd 1","ssthresh 10, cwnd 1","ssthresh 10, cwnd 10","ssthresh 19, cwnd 19"],"correct":2,"explanation":"Reno halves on a triple duplicate ACK: ssthresh = 20 / 2 = 10, and fast recovery lets cwnd continue from ssthresh in congestion avoidance. Tahoe — or any sender after a timeout — would drop cwnd to 1."},{"id":"computer-networks/tcp-congestion-control#1","route":"/computer-networks/tcp-congestion-control","section":"computer-networks","subject":"cs-core","title":"TCP Congestion Control – Slow Start, AIMD, Tahoe vs Reno","question":"Why does Reno react more gently to three duplicate ACKs than to a timeout?","options":["Duplicate ACKs are cheaper to process","Duplicate ACKs prove later segments are still getting through, so the path is only mildly congested; a timeout means nothing is getting through","Timeouts only happen on wireless links","Three duplicate ACKs mean the segment was not actually lost"],"correct":1,"explanation":"Each duplicate ACK is triggered by a segment that did arrive, after the lost one. Three of them mean data is still flowing, so halving is enough. A timeout means the sender heard nothing for a full RTO — the conservative response is to start again from 1."},{"id":"computer-networks/tcp-congestion-control#2","route":"/computer-networks/tcp-congestion-control","section":"computer-networks","subject":"cs-core","title":"TCP Congestion Control – Slow Start, AIMD, Tahoe vs Reno","question":"In slow start, how does cwnd grow?","options":["By one segment per round trip","It doubles every round trip, because every ACK adds one segment","It is set to the receiver's advertised window immediately","It grows by one segment per lost packet"],"correct":1,"explanation":"Every ACK increases cwnd by one segment. A window of cwnd segments produces cwnd ACKs per round trip, so cwnd doubles each RTT — exponential growth, despite the name. Once cwnd reaches ssthresh, congestion avoidance adds just one segment per RTT."},{"id":"computer-networks/tcp-handshake#0","route":"/computer-networks/tcp-handshake","section":"computer-networks","subject":"cs-core","title":"TCP Handshake Visualizer – SYN, SYN-ACK, ACK and TIME_WAIT","question":"A client sends SYN with seq=4200. What acknowledgement number does the server put in its SYN-ACK?","options":["4200","4201","4220","None — a SYN-ACK only carries the server's own sequence number"],"correct":1,"explanation":"The SYN carries no data but occupies one sequence number, so the next number the server expects from the client is 4201. The acknowledgement number always names the next sequence number expected, not the last one received."},{"id":"computer-networks/tcp-handshake#1","route":"/computer-networks/tcp-handshake","section":"computer-networks","subject":"cs-core","title":"TCP Handshake Visualizer – SYN, SYN-ACK, ACK and TIME_WAIT","question":"Which endpoint ends up in TIME_WAIT?","options":["Always the server","Always the client","Whichever side closed first (sent the first FIN)","Whichever side received the first FIN"],"correct":2,"explanation":"The active closer — the side that sends the first FIN — goes FIN_WAIT_1 → FIN_WAIT_2 → TIME_WAIT. The passive closer goes CLOSE_WAIT → LAST_ACK → CLOSED and never waits. Busy servers that close connections themselves therefore accumulate TIME_WAIT sockets."},{"id":"computer-networks/tcp-handshake#2","route":"/computer-networks/tcp-handshake","section":"computer-networks","subject":"cs-core","title":"TCP Handshake Visualizer – SYN, SYN-ACK, ACK and TIME_WAIT","question":"Why does TIME_WAIT last 2 × MSL instead of closing immediately after the final ACK?","options":["To give the application time to read the last bytes","So a lost final ACK can be re-sent when the peer retransmits its FIN, and so stray old segments expire before the same four-tuple is reused","Because the FIN must be acknowledged twice","To keep the congestion window warm for the next connection"],"correct":1,"explanation":"The final ACK is never itself acknowledged, so if it is lost the peer retransmits its FIN; a side still in TIME_WAIT can answer with another ACK instead of a RST. Waiting two maximum segment lifetimes also guarantees any duplicate of this connection still in the network has died before a new connection with the same addresses and ports could receive it."},{"id":"database-systems/join-algorithms#0","route":"/database-systems/join-algorithms","section":"database-systems","subject":"cs-core","title":"Join Algorithms Visualizer – Nested Loop, Hash Join, Sort-Merge","question":"Two tables of 10,000 rows each are joined on an equality condition, with no indexes and plenty of memory. Which join is usually fastest?","options":["Nested-loop join","Hash join","Sort-merge join","They are always equal"],"correct":1,"explanation":"Hash join reads each table once — build on one, probe with the other — for O(n + m) work. Nested loop needs 100 million comparisons; sort-merge pays O(n log n) to sort first."},{"id":"database-systems/join-algorithms#1","route":"/database-systems/join-algorithms","section":"database-systems","subject":"cs-core","title":"Join Algorithms Visualizer – Nested Loop, Hash Join, Sort-Merge","question":"When does sort-merge join beat hash join?","options":["When the inputs already arrive sorted on the join key, for example from an index","When the tables are tiny","When the join condition is a hash","Never"],"correct":0,"explanation":"If both inputs are already sorted, the merge is a single linear pass with no hash table to build — and the output is sorted too, which a later ORDER BY or GROUP BY can use."},{"id":"database-systems/join-algorithms#2","route":"/database-systems/join-algorithms","section":"database-systems","subject":"cs-core","title":"Join Algorithms Visualizer – Nested Loop, Hash Join, Sort-Merge","question":"Why does hash join still compare keys after hashing them?","options":["To count the rows","Different keys can land in the same bucket (collisions)","Hash functions are random","It does not — hashing is enough"],"correct":1,"explanation":"A bucket narrows the candidates, but keys that collide share a bucket. Each candidate must still be checked for equality before it is output."},{"id":"database-systems/lsm-trees#0","route":"/database-systems/lsm-trees","section":"database-systems","subject":"cs-core","title":"LSM Tree Visualizer – Memtables, SSTables, Compaction, Bloom Filters","question":"Why are writes cheap in an LSM tree?","options":["They skip durability","They go to an in-memory memtable and reach disk only in large sequential flushes","They overwrite the old value in place","They are compressed"],"correct":1,"explanation":"A write is a memtable insert plus a sequential log append. Disk sees only big sorted batches (flushes and compactions) instead of one random page write per update as in a B-tree."},{"id":"database-systems/lsm-trees#1","route":"/database-systems/lsm-trees","section":"database-systems","subject":"cs-core","title":"LSM Tree Visualizer – Memtables, SSTables, Compaction, Bloom Filters","question":"A Bloom filter says \"maybe present\" for a key. What do you know?","options":["The key is definitely in the table","The key might be in the table — you must search to be sure","The key is definitely not in the table","The table is corrupt"],"correct":1,"explanation":"Bloom filters have false positives but no false negatives. \"No\" lets the read skip the table; \"maybe\" still needs a search, which may come back empty."},{"id":"database-systems/lsm-trees#2","route":"/database-systems/lsm-trees","section":"database-systems","subject":"cs-core","title":"LSM Tree Visualizer – Memtables, SSTables, Compaction, Bloom Filters","question":"How is a key deleted in an LSM tree?","options":["Its entry is removed from every SSTable immediately","A tombstone is written; compaction eventually drops the older versions and the tombstone itself","The memtable is cleared","Deletes are not supported"],"correct":1,"explanation":"SSTables are immutable, so a delete is just another write — a marker that shadows older versions. Space is reclaimed only when compaction merges the tombstone down to the bottom level."},{"id":"database-systems/mvcc#0","route":"/database-systems/mvcc","section":"database-systems","subject":"cs-core","title":"MVCC Visualizer – Multi-Version Concurrency Control","question":"Under MVCC, T1 has an uncommitted update on row A. What happens when T2 reads A?","options":["T2 waits for T1 to commit","T2 reads T1’s uncommitted value","T2 reads the older committed version immediately","T2 aborts"],"correct":2,"explanation":"The update created a new version instead of overwriting the old one. T2’s snapshot cannot see T1’s version, so it reads the previous committed one — without taking a lock or waiting."},{"id":"database-systems/mvcc#1","route":"/database-systems/mvcc","section":"database-systems","subject":"cs-core","title":"MVCC Visualizer – Multi-Version Concurrency Control","question":"When can VACUUM remove an old row version?","options":["As soon as a newer version exists","When the transaction that replaced it has committed and no active snapshot can still see the old version","Only when the table is dropped","When the version is more than one hour old"],"correct":1,"explanation":"A long-running transaction with an old snapshot pins every version it might read. This is why one forgotten open transaction can make a PostgreSQL table bloat."},{"id":"database-systems/mvcc#2","route":"/database-systems/mvcc","section":"database-systems","subject":"cs-core","title":"MVCC Visualizer – Multi-Version Concurrency Control","question":"Under snapshot isolation, T1 and T2 both update row A and T1 commits first. What happens to T2?","options":["Its update overwrites T1’s silently","It aborts with a serialization error","It waits forever","It merges both updates"],"correct":1,"explanation":"First committer wins: T2 would overwrite a change its snapshot never saw, so it is aborted and must retry. Read Committed instead re-reads the newest version and proceeds — which is how lost updates sneak in."},{"id":"database-systems/normalization#0","route":"/database-systems/normalization","section":"database-systems","subject":"cs-core","title":"Database Normalization Visualizer – 1NF, 2NF, 3NF and BCNF","question":"A table has key {StudentID, CourseID} and the dependency StudentID → Name. Which normal form does it break?","options":["1NF","2NF","BCNF only","None"],"correct":1,"explanation":"Name depends on only part of the key — a partial dependency. Each student’s name is repeated once per course they take, which is exactly the redundancy 2NF removes."},{"id":"database-systems/normalization#1","route":"/database-systems/normalization","section":"database-systems","subject":"cs-core","title":"Database Normalization Visualizer – 1NF, 2NF, 3NF and BCNF","question":"Why is a table in 3NF not always in BCNF?","options":["3NF allows multi-valued cells","3NF allows X → A when A is part of a candidate key, even if X is not a superkey","BCNF only applies to tables with one key","They are always the same"],"correct":1,"explanation":"Instructor → CourseID, where CourseID is prime, is allowed in 3NF. BCNF rejects it because Instructor is not a superkey — and decomposing it loses the dependency {StudentID, CourseID} → Instructor."},{"id":"database-systems/normalization#2","route":"/database-systems/normalization","section":"database-systems","subject":"cs-core","title":"Database Normalization Visualizer – 1NF, 2NF, 3NF and BCNF","question":"What makes splitting R into R1 and R2 lossless?","options":["R1 and R2 have the same number of rows","The shared columns form a key of R1 or of R2","Every column appears in exactly one table","The tables are in BCNF"],"correct":1,"explanation":"If the common attributes determine all of R1 (or R2), each row of the other table matches at most one row on the join, so no spurious rows appear. Splitting on X → Y with X kept in both does exactly that."},{"id":"database-systems/relational-algebra#0","route":"/database-systems/relational-algebra","section":"database-systems","subject":"cs-core","title":"Relational Algebra Visualizer – Selection, Projection, Join, Union","question":"Employee has 6 tuples in 3 departments. How many tuples does π_did(Employee) contain?","options":["6","3","1","It depends on the salaries"],"correct":1,"explanation":"Relational algebra works on sets: the six projected tuples collapse to one per distinct did. SQL keeps duplicates unless you write SELECT DISTINCT — that is the bag versus set difference."},{"id":"database-systems/relational-algebra#1","route":"/database-systems/relational-algebra","section":"database-systems","subject":"cs-core","title":"Relational Algebra Visualizer – Selection, Projection, Join, Union","question":"Why does π_eid(Employee) − π_mgr(Dept) need a rename first?","options":["Difference only works on numbers","Both sides must have the same schema, and eid and mgr are different attribute names","To remove duplicates","It does not need one"],"correct":1,"explanation":"Union, difference and intersection need union-compatible inputs: the same attributes. ρ renames mgr to eid so the two relations line up."},{"id":"database-systems/relational-algebra#2","route":"/database-systems/relational-algebra","section":"database-systems","subject":"cs-core","title":"Relational Algebra Visualizer – Selection, Projection, Join, Union","question":"Which operator can make a relation larger than either of its inputs?","options":["σ selection","π projection","⋈ join","− difference"],"correct":2,"explanation":"A join pairs tuples, so its output can be as large as the product of the inputs. Selection, projection and difference can only keep or drop what they are given."},{"id":"database-systems/serializability#0","route":"/database-systems/serializability","section":"database-systems","subject":"cs-core","title":"Conflict Serializability Visualizer – Precedence Graphs","question":"Which pair of operations does NOT conflict?","options":["R1(X) then W2(X)","W1(X) then R2(X)","R1(X) then R2(X)","W1(X) then W2(X)"],"correct":2,"explanation":"Two reads of the same item give the same values whichever runs first, so they can be swapped freely. Every pair involving at least one write on the same item, from different transactions, conflicts."},{"id":"database-systems/serializability#1","route":"/database-systems/serializability","section":"database-systems","subject":"cs-core","title":"Conflict Serializability Visualizer – Precedence Graphs","question":"The precedence graph of a schedule contains T1 → T2 and T2 → T1. What follows?","options":["The schedule is equivalent to T1 then T2","The schedule is not conflict-serializable","The schedule must deadlock","Nothing — two-transaction cycles are harmless"],"correct":1,"explanation":"T1 must precede T2 because of one conflict and follow it because of another. No serial order satisfies both, so the schedule is not conflict-serializable."},{"id":"database-systems/serializability#2","route":"/database-systems/serializability","section":"database-systems","subject":"cs-core","title":"Conflict Serializability Visualizer – Precedence Graphs","question":"How do you find the equivalent serial order of a conflict-serializable schedule?","options":["Order transactions by their first operation","Order transactions by their commit time — always","Topologically sort the precedence graph","Any order works"],"correct":2,"explanation":"Any topological order of the acyclic precedence graph puts every transaction before the ones its conflicts point to, which is exactly what an equivalent serial schedule needs."},{"id":"database-systems/sql-query-order#0","route":"/database-systems/sql-query-order","section":"database-systems","subject":"cs-core","title":"SQL Logical Query Order Visualizer – FROM to LIMIT","question":"Why does WHERE COUNT(*) > 2 fail, while HAVING COUNT(*) > 2 works?","options":["COUNT is not allowed in WHERE for performance reasons","WHERE runs before GROUP BY, so there are no groups to count yet","HAVING is just an alias for WHERE","WHERE only accepts constants"],"correct":1,"explanation":"WHERE filters individual rows before they are grouped. HAVING runs after GROUP BY, when each group exists and its aggregates can be computed."},{"id":"database-systems/sql-query-order#1","route":"/database-systems/sql-query-order","section":"database-systems","subject":"cs-core","title":"SQL Logical Query Order Visualizer – FROM to LIMIT","question":"Which clauses can use an alias defined in SELECT?","options":["WHERE and GROUP BY","ORDER BY (it runs after SELECT)","FROM","All of them"],"correct":1,"explanation":"Aliases are created when SELECT runs. Only ORDER BY (and, in some databases, LIMIT expressions) comes later. Some systems such as MySQL and PostgreSQL also accept aliases in GROUP BY as an extension."},{"id":"database-systems/sql-query-order#2","route":"/database-systems/sql-query-order","section":"database-systems","subject":"cs-core","title":"SQL Logical Query Order Visualizer – FROM to LIMIT","question":"In what logical order are these evaluated: SELECT, WHERE, ORDER BY, FROM?","options":["SELECT, FROM, WHERE, ORDER BY","FROM, WHERE, SELECT, ORDER BY","FROM, SELECT, WHERE, ORDER BY","WHERE, FROM, ORDER BY, SELECT"],"correct":1,"explanation":"FROM builds the rows, WHERE filters them, SELECT computes the output columns, and ORDER BY sorts the result. The optimizer may physically reorder work, but it must produce this logical result."},{"id":"database-systems/transaction-isolation-levels#0","route":"/database-systems/transaction-isolation-levels","section":"database-systems","subject":"cs-core","title":"Transaction Isolation Levels Visualizer – Dirty Reads to Serializable","question":"Which anomaly can still happen at Read Committed?","options":["Dirty reads","Non-repeatable reads","Dirty writes","None — Read Committed is fully isolated"],"correct":1,"explanation":"Read Committed only guarantees that each read sees committed data. Another transaction can commit a change between two reads of the same row, so the second read returns a different value."},{"id":"database-systems/transaction-isolation-levels#1","route":"/database-systems/transaction-isolation-levels","section":"database-systems","subject":"cs-core","title":"Transaction Isolation Levels Visualizer – Dirty Reads to Serializable","question":"With lock-based Repeatable Read, why can a phantom still appear?","options":["Shared locks are dropped after each read","Row locks cover only rows that already exist, so a newly inserted matching row is not locked","Repeatable Read allows dirty reads","COUNT(*) is answered from a cached value"],"correct":1,"explanation":"Repeatable Read locks every row it has read, but an INSERT creates a row nobody could have locked. Serializable closes the gap with predicate (or index-range) locks that cover the WHERE clause itself."},{"id":"database-systems/transaction-isolation-levels#2","route":"/database-systems/transaction-isolation-levels","section":"database-systems","subject":"cs-core","title":"Transaction Isolation Levels Visualizer – Dirty Reads to Serializable","question":"Two transactions each read a balance and write back \"value read + delta\" at Read Committed. What can go wrong?","options":["A deadlock is guaranteed","One update is silently lost","The second write is always rejected","Nothing — both deltas always apply"],"correct":1,"explanation":"Both read the same starting value, so the second write overwrites the first with a total that ignores it. Fix it with an atomic UPDATE ... SET balance = balance + 50, SELECT ... FOR UPDATE, or a stronger isolation level."},{"id":"database-systems/two-phase-locking#0","route":"/database-systems/two-phase-locking","section":"database-systems","subject":"cs-core","title":"Two-Phase Locking (2PL) Visualizer – Locks, Deadlocks, Strict 2PL","question":"What does the \"two phases\" of two-phase locking refer to?","options":["Locking reads first, then writes","A growing phase that only acquires locks, then a shrinking phase that only releases them","Preparing and then committing on two servers","Shared locks first, then exclusive locks"],"correct":1,"explanation":"Once a transaction releases any lock it may never acquire another. The moment of its last acquisition is its lock point, and ordering transactions by lock point gives an equivalent serial schedule."},{"id":"database-systems/two-phase-locking#1","route":"/database-systems/two-phase-locking","section":"database-systems","subject":"cs-core","title":"Two-Phase Locking (2PL) Visualizer – Locks, Deadlocks, Strict 2PL","question":"Why does basic 2PL allow cascading aborts?","options":["Because shared locks are compatible","Because a transaction can release an exclusive lock before it commits, letting others read an uncommitted write","Because deadlocks are never detected","Because locks are taken in the wrong order"],"correct":1,"explanation":"Releasing an exclusive lock early exposes an uncommitted value. If the writer then aborts, everyone who read it must abort as well. Strict 2PL holds exclusive locks until commit, which makes schedules cascadeless."},{"id":"database-systems/two-phase-locking#2","route":"/database-systems/two-phase-locking","section":"database-systems","subject":"cs-core","title":"Two-Phase Locking (2PL) Visualizer – Locks, Deadlocks, Strict 2PL","question":"T1 holds X(A) and waits for B; T2 holds X(B) and requests A. What happens?","options":["T2 is granted A","T2 waits and both eventually proceed","A deadlock: one transaction must be aborted","T1 is granted B immediately"],"correct":2,"explanation":"T2 waits for T1 and T1 waits for T2 — a cycle in the waits-for graph. 2PL does not prevent deadlocks; the database detects the cycle (or times out) and aborts a victim."},{"id":"database-systems/write-ahead-logging#0","route":"/database-systems/write-ahead-logging","section":"database-systems","subject":"cs-core","title":"Write-Ahead Logging Visualizer – Crash Recovery with Redo and Undo","question":"What exactly does the write-ahead rule require?","options":["Data pages are written before the log","A page may reach disk only after the log records describing its changes are on disk","Every update is written to disk immediately","The log is written once per checkpoint"],"correct":1,"explanation":"If a page could reach disk first and the system crashed, the disk would hold a change with no record of how to undo it. Forcing the log up to the page’s pageLSN before the write rules that out."},{"id":"database-systems/write-ahead-logging#1","route":"/database-systems/write-ahead-logging","section":"database-systems","subject":"cs-core","title":"Write-Ahead Logging Visualizer – Crash Recovery with Redo and Undo","question":"Why does recovery redo the updates of losers too, only to undo them afterwards?","options":["It is a bug in ARIES","Repeating history restores memory exactly as it was at the crash, so undo can roll losers back with simple logged steps","Losers might have committed after all","Redo is cheaper than checking"],"correct":1,"explanation":"Repeating history makes redo trivial (no need to know who won) and gives undo a known starting state. Each undo then writes a compensation log record, so recovery itself survives a crash."},{"id":"database-systems/write-ahead-logging#2","route":"/database-systems/write-ahead-logging","section":"database-systems","subject":"cs-core","title":"Write-Ahead Logging Visualizer – Crash Recovery with Redo and Undo","question":"A transaction commits under a steal / no-force policy. What has to be on disk when COMMIT returns?","options":["All of its data pages","Its log records up to and including COMMIT","Nothing","The whole buffer pool"],"correct":1,"explanation":"No-force means data pages can stay in memory; the forced log is enough to redo them after a crash. That turns a commit into one sequential log write instead of many random page writes."},{"id":"divide-and-conquer/binary-search#0","route":"/divide-and-conquer/binary-search","section":"divide-and-conquer","subject":"dsa","title":"Binary Search — Decision Tree","question":"What is the time complexity of binary search?","options":["O(n)","O(n²)","O(log n)","O(n log n)"],"correct":2,"explanation":"Binary search halves the search space at each step. Starting from n, after k steps the space is n/2^k. When n/2^k = 1, k = log₂(n)."},{"id":"divide-and-conquer/binary-search#1","route":"/divide-and-conquer/binary-search","section":"divide-and-conquer","subject":"dsa","title":"Binary Search — Decision Tree","question":"What precondition must the array satisfy for binary search to work?","options":["It must have an even number of elements","It must be sorted","Elements must be unique","It must be stored in a hash table"],"correct":1,"explanation":"Binary search relies on the sorted order to decide which half to eliminate. On an unsorted array it can miss the target entirely."},{"id":"divide-and-conquer/binary-search#2","route":"/divide-and-conquer/binary-search","section":"divide-and-conquer","subject":"dsa","title":"Binary Search — Decision Tree","question":"In the worst case, how many comparisons does binary search make on an array of 16 elements?","options":["4","5","8","16"],"correct":1,"explanation":"log₂(16) = 4 splits, but you need one final comparison to confirm found or not-found — so 5 comparisons in the worst case."},{"id":"divide-and-conquer/closest-pair-of-points#0","route":"/divide-and-conquer/closest-pair-of-points","section":"divide-and-conquer","subject":"dsa","title":"Closest Pair of Points","question":"What is the time complexity of the D&C closest pair algorithm?","options":["O(n²)","O(n log² n)","O(n log n)","O(n)"],"correct":2,"explanation":"With careful strip handling (at most 8 comparisons per point due to the δ-packing argument), the strip check is O(n) per level, giving O(n log n) overall."},{"id":"divide-and-conquer/closest-pair-of-points#1","route":"/divide-and-conquer/closest-pair-of-points","section":"divide-and-conquer","subject":"dsa","title":"Closest Pair of Points","question":"Why do we only need to check at most 7 other points for each point in the strip?","options":["The strip is always width 7","Each δ×2δ rectangle can hold at most 8 points (δ packing argument)","We sort by y and stop after 7 steps","Hashing limits collisions to 7"],"correct":1,"explanation":"In each δ×2δ block of the strip, any two points are at least δ apart (otherwise we'd have a closer pair), which limits the block to ≤8 points — bounding comparisons."},{"id":"divide-and-conquer/closest-pair-of-points#2","route":"/divide-and-conquer/closest-pair-of-points","section":"divide-and-conquer","subject":"dsa","title":"Closest Pair of Points","question":"What must be true about points in the strip for them to be candidates for the closest cross-half pair?","options":["Their distance to each other must be < δ","Their x-coordinate must be within δ of the dividing line","They must be in sorted order","They must have distinct y-coordinates"],"correct":1,"explanation":"Only points within δ of the midline x-coordinate can possibly form a pair closer than δ. Points farther away have x-distance ≥ δ already."},{"id":"divide-and-conquer/merge-sort#0","route":"/divide-and-conquer/merge-sort","section":"divide-and-conquer","subject":"dsa","title":"Merge Sort — Recursion Tree","question":"What is the time complexity of merge sort?","options":["O(n²)","O(n log n)","O(log n)","O(n)"],"correct":1,"explanation":"Merge sort splits the array O(log n) times and does O(n) work at each level, giving O(n log n) total."},{"id":"divide-and-conquer/merge-sort#1","route":"/divide-and-conquer/merge-sort","section":"divide-and-conquer","subject":"dsa","title":"Merge Sort — Recursion Tree","question":"Why does merge sort need O(n) extra space?","options":["For the recursion call stack","To store the sorted output before copying back","To hold temporary arrays during merging","Both B and C — the merge step requires an auxiliary buffer"],"correct":3,"explanation":"The merge step cannot be done in-place efficiently; it needs an auxiliary buffer of size O(n) to hold elements being merged."},{"id":"divide-and-conquer/merge-sort#2","route":"/divide-and-conquer/merge-sort","section":"divide-and-conquer","subject":"dsa","title":"Merge Sort — Recursion Tree","question":"How many levels does the recursion tree have for an array of size n?","options":["n","n/2","log₂(n)","n²"],"correct":2,"explanation":"Each level halves the subarray size, so after log₂(n) splits every subarray has exactly 1 element — giving log₂(n) + 1 levels."},{"id":"divide-and-conquer/strassens-matrix-multiplication#0","route":"/divide-and-conquer/strassens-matrix-multiplication","section":"divide-and-conquer","subject":"dsa","title":"Strassen's Matrix Multiplication","question":"How many scalar multiplications does Strassen's algorithm use to multiply two 2×2 matrices?","options":["4","6","7","8"],"correct":2,"explanation":"Strassen uses exactly 7 multiplications (M₁–M₇) instead of the naive 8, at the cost of more additions/subtractions."},{"id":"divide-and-conquer/strassens-matrix-multiplication#1","route":"/divide-and-conquer/strassens-matrix-multiplication","section":"divide-and-conquer","subject":"dsa","title":"Strassen's Matrix Multiplication","question":"What is the time complexity of Strassen's algorithm for n×n matrices?","options":["O(n²)","O(n^2.807)","O(n³)","O(n log n)"],"correct":1,"explanation":"By the Master Theorem with a=7, b=2: T(n) = 7T(n/2) + O(n²) → O(n^log₂7) ≈ O(n^2.807)."},{"id":"divide-and-conquer/strassens-matrix-multiplication#2","route":"/divide-and-conquer/strassens-matrix-multiplication","section":"divide-and-conquer","subject":"dsa","title":"Strassen's Matrix Multiplication","question":"Why isn't Strassen's algorithm always preferred over naive O(n³) multiplication in practice?","options":["It only works on square matrices","Numerical instability and high constant factors make naive faster for small n","It requires O(n³) extra space","It cannot be parallelized"],"correct":1,"explanation":"Strassen has larger constant factors and accumulates floating-point errors. For small matrices (n < ~100) the naive algorithm is faster; Strassen is preferred for very large n."},{"id":"dynamic-programming/0-1-knapsack#0","route":"/dynamic-programming/0-1-knapsack","section":"dynamic-programming","subject":"dsa","title":"0-1 Knapsack – Dynamic Programming Visualizer","question":"What constraint makes this the '0/1' knapsack (not 'unbounded')?","options":["Item values are 0 or 1","Each item can be taken at most once","Weight must be an integer","Items are sorted by value"],"correct":1,"explanation":"In 0/1 Knapsack each item is either included (1) or excluded (0) — at most once. Unbounded Knapsack allows multiple copies of the same item."},{"id":"dynamic-programming/0-1-knapsack#1","route":"/dynamic-programming/0-1-knapsack","section":"dynamic-programming","subject":"dsa","title":"0-1 Knapsack – Dynamic Programming Visualizer","question":"When item weight ≤ capacity w, how is dp[i][w] computed?","options":["dp[i-1][w]","values[i] + dp[i-1][w]","max(values[i] + dp[i-1][w-weight[i]], dp[i-1][w])","dp[i-1][w-weight[i]] + 1"],"correct":2,"explanation":"We take the maximum of: (a) including item i — its value plus the best solution for the remaining capacity, or (b) excluding item i — the best solution without it."},{"id":"dynamic-programming/0-1-knapsack#2","route":"/dynamic-programming/0-1-knapsack","section":"dynamic-programming","subject":"dsa","title":"0-1 Knapsack – Dynamic Programming Visualizer","question":"How can knapsack space complexity be reduced from O(n×W) to O(W)?","options":["Use binary search","Process a single row, filling weights right-to-left","Use a hash map instead of a 2D array","Sort items by weight first"],"correct":1,"explanation":"Using a single 1D dp array and filling it right-to-left ensures each item is counted at most once — the correct 0/1 behaviour with O(W) space."},{"id":"dynamic-programming/edit-distance#0","route":"/dynamic-programming/edit-distance","section":"dynamic-programming","subject":"dsa","title":"Edit Distance (Levenshtein) – DP Visualizer","question":"When two characters match in the Edit Distance table, what is dp[i][j]?","options":["dp[i-1][j-1]","dp[i-1][j-1] + 1","min(dp[i-1][j], dp[i][j-1])","0"],"correct":0,"explanation":"When characters match, no edit is needed — we carry forward dp[i-1][j-1], the cost for the prefixes without those characters."},{"id":"dynamic-programming/edit-distance#1","route":"/dynamic-programming/edit-distance","section":"dynamic-programming","subject":"dsa","title":"Edit Distance (Levenshtein) – DP Visualizer","question":"Which three operations does Levenshtein distance use?","options":["Insert, Delete, Swap","Insert, Delete, Substitute","Copy, Move, Replace","Add, Remove, Transpose"],"correct":1,"explanation":"Levenshtein distance uses Insert (add a character), Delete (remove a character), and Substitute (replace one character with another)."},{"id":"dynamic-programming/edit-distance#2","route":"/dynamic-programming/edit-distance","section":"dynamic-programming","subject":"dsa","title":"Edit Distance (Levenshtein) – DP Visualizer","question":"What is the edit distance between 'KITTEN' and 'SITTING'?","options":["2","3","4","5"],"correct":1,"explanation":"KITTEN → SITTEN (sub K→S) → SITTIN (sub E→I) → SITTING (insert G) = 3 operations."},{"id":"dynamic-programming/fibonacci-numbers#0","route":"/dynamic-programming/fibonacci-numbers","section":"dynamic-programming","subject":"dsa","title":"Fibonacci Numbers – Dynamic Programming Visualizer","question":"What is the time complexity of naive recursive Fibonacci (no memoization)?","options":["O(n)","O(n log n)","O(2ⁿ)","O(n²)"],"correct":2,"explanation":"Without memoization every call to fib(n) spawns two more calls — fib(n-1) and fib(n-2). The resulting recursion tree has ~2ⁿ nodes, giving O(2ⁿ) time."},{"id":"dynamic-programming/fibonacci-numbers#1","route":"/dynamic-programming/fibonacci-numbers","section":"dynamic-programming","subject":"dsa","title":"Fibonacci Numbers – Dynamic Programming Visualizer","question":"What is the time complexity WITH memoization?","options":["O(2ⁿ)","O(n log n)","O(n)","O(log n)"],"correct":2,"explanation":"With memoization each unique value fib(0)…fib(n) is computed exactly once and cached. Every subsequent lookup is O(1), giving O(n) total."},{"id":"dynamic-programming/fibonacci-numbers#2","route":"/dynamic-programming/fibonacci-numbers","section":"dynamic-programming","subject":"dsa","title":"Fibonacci Numbers – Dynamic Programming Visualizer","question":"Which DP paradigm does memoization belong to?","options":["Bottom-up tabulation","Top-down memoization","Greedy approach","Divide and conquer"],"correct":1,"explanation":"Memoization is top-down DP — we start at the original problem, recurse toward base cases, and cache results along the way."},{"id":"dynamic-programming/house-robber#0","route":"/dynamic-programming/house-robber","section":"dynamic-programming","subject":"dsa","title":"House Robber – Dynamic Programming Visualizer","question":"What is the key constraint in the House Robber problem?","options":["Can only rob every third house","Cannot rob two adjacent houses","Must rob at least one house","Can only rob houses worth more than 5"],"correct":1,"explanation":"The robber cannot rob two directly adjacent houses — the alarm would trigger. This forces a skip-at-least-one between any two robbed houses."},{"id":"dynamic-programming/house-robber#1","route":"/dynamic-programming/house-robber","section":"dynamic-programming","subject":"dsa","title":"House Robber – Dynamic Programming Visualizer","question":"What is the recurrence relation for House Robber?","options":["dp[i] = dp[i-1] + dp[i-2]","dp[i] = max(nums[i] + dp[i-2], dp[i-1])","dp[i] = nums[i] + dp[i-1]","dp[i] = max(dp[i-1], dp[i-2])"],"correct":1,"explanation":"At each house you either rob it (value + best solution 2 houses back) or skip it (best solution from 1 house back). dp[i] = max(nums[i] + dp[i-2], dp[i-1])."},{"id":"dynamic-programming/house-robber#2","route":"/dynamic-programming/house-robber","section":"dynamic-programming","subject":"dsa","title":"House Robber – Dynamic Programming Visualizer","question":"What is the space-optimized complexity?","options":["O(n) time, O(n) space","O(n) time, O(1) space","O(n²) time, O(1) space","O(n log n) time, O(1) space"],"correct":1,"explanation":"The recurrence only needs dp[i-1] and dp[i-2], so two variables (prev2 and prev1) suffice — reducing space from O(n) to O(1) while keeping O(n) time."},{"id":"dynamic-programming/longest-common-subsequence#0","route":"/dynamic-programming/longest-common-subsequence","section":"dynamic-programming","subject":"dsa","title":"Longest Common Subsequence – LCS DP Visualizer","question":"When two characters match in the LCS DP table, what is dp[i][j]?","options":["max(dp[i-1][j], dp[i][j-1])","dp[i-1][j-1] + 1","dp[i][j-1] + 1","dp[i-1][j] + dp[i][j-1]"],"correct":1,"explanation":"When str1[i-1] == str2[j-1] we can extend the LCS found for the prefixes without those characters: dp[i][j] = dp[i-1][j-1] + 1."},{"id":"dynamic-programming/longest-common-subsequence#1","route":"/dynamic-programming/longest-common-subsequence","section":"dynamic-programming","subject":"dsa","title":"Longest Common Subsequence – LCS DP Visualizer","question":"What does 'subsequence' mean (compared to 'substring')?","options":["Consecutive characters only","Characters maintain relative order but need not be consecutive","Any rearrangement of characters","Characters at the same positions"],"correct":1,"explanation":"A subsequence preserves the original order of characters but allows gaps — unlike a substring which requires consecutiveness."},{"id":"dynamic-programming/longest-common-subsequence#2","route":"/dynamic-programming/longest-common-subsequence","section":"dynamic-programming","subject":"dsa","title":"Longest Common Subsequence – LCS DP Visualizer","question":"Which real-world tool relies heavily on LCS?","options":["Hash tables","Git diff / version control","Binary search","Graph shortest path"],"correct":1,"explanation":"Git's diff algorithm uses LCS to identify which lines were added, removed, or unchanged between two file versions."},{"id":"dynamic-programming/longest-increasing-subsequence#0","route":"/dynamic-programming/longest-increasing-subsequence","section":"dynamic-programming","subject":"dsa","title":"Longest Increasing Subsequence – DP Visualizer","question":"What is the initial value of dp[i] in the LIS algorithm?","options":["0","1","arr[i]","∞"],"correct":1,"explanation":"Every element is a valid LIS of length 1 by itself (just that element), so dp[i] starts at 1."},{"id":"dynamic-programming/longest-increasing-subsequence#1","route":"/dynamic-programming/longest-increasing-subsequence","section":"dynamic-programming","subject":"dsa","title":"Longest Increasing Subsequence – DP Visualizer","question":"When do we update dp[i] using dp[j] (where j < i)?","options":["Always","When arr[j] > arr[i]","When arr[j] < arr[i] and dp[j]+1 > dp[i]","When arr[j] == arr[i]"],"correct":2,"explanation":"We extend the LIS ending at j by appending arr[i] only when arr[j] < arr[i] (strictly increasing) and doing so gives a longer subsequence than what we have."},{"id":"dynamic-programming/longest-increasing-subsequence#2","route":"/dynamic-programming/longest-increasing-subsequence","section":"dynamic-programming","subject":"dsa","title":"Longest Increasing Subsequence – DP Visualizer","question":"What is the time complexity of the O(n²) LIS DP approach?","options":["O(n)","O(n log n)","O(n²)","O(2ⁿ)"],"correct":2,"explanation":"The nested loop (for each i, compare with all j < i) runs in O(n²). An O(n log n) solution exists using patience sorting with binary search."},{"id":"dynamic-programming/making-change#0","route":"/dynamic-programming/making-change","section":"dynamic-programming","subject":"dsa","title":"Making Change – Coin Change DP Visualizer","question":"What DP approach does the Coin Change problem use?","options":["Top-down memoization","Bottom-up tabulation","Greedy algorithm","Backtracking"],"correct":1,"explanation":"Coin Change uses bottom-up tabulation: we fill a DP table iteratively from amount 0 up to the target, building on previously solved subproblems."},{"id":"dynamic-programming/making-change#1","route":"/dynamic-programming/making-change","section":"dynamic-programming","subject":"dsa","title":"Making Change – Coin Change DP Visualizer","question":"What does dp[0] = 0 represent in coin change?","options":["Zero coins with denomination 0","Zero coins are needed to make amount 0","The first coin denomination","An impossible amount"],"correct":1,"explanation":"dp[0] = 0 is the base case: you need zero coins to make amount 0. Every other dp[i] builds on this foundation."},{"id":"dynamic-programming/making-change#2","route":"/dynamic-programming/making-change","section":"dynamic-programming","subject":"dsa","title":"Making Change – Coin Change DP Visualizer","question":"What knapsack pattern does coin change follow?","options":["0/1 Knapsack (each item once)","Fractional Knapsack","Unbounded Knapsack (items reusable)","Bounded Knapsack"],"correct":2,"explanation":"Coin change is Unbounded Knapsack — coins can be reused any number of times. This is why we iterate forward (not backward) in the amount loop."},{"id":"dynamic-programming/matrix-chain-multiplication#0","route":"/dynamic-programming/matrix-chain-multiplication","section":"dynamic-programming","subject":"dsa","title":"Matrix Chain Multiplication – DP Visualizer","question":"Why does MCM fill the DP table diagonally?","options":["It's faster than row-by-row","Subproblems of length l depend only on subproblems of length < l","To avoid cache misses","Diagonal cells are independent of each other"],"correct":1,"explanation":"m[i][j] for a chain of length l = j-i+1 depends on m[i][k] and m[k+1][j], which are shorter chains. So we must fill shorter chains before longer ones — diagonally."},{"id":"dynamic-programming/matrix-chain-multiplication#1","route":"/dynamic-programming/matrix-chain-multiplication","section":"dynamic-programming","subject":"dsa","title":"Matrix Chain Multiplication – DP Visualizer","question":"For matrix Ai (p[i-1] × p[i]) times Aj (p[j-1] × p[j]) split at k, what is the multiplication cost?","options":["p[i-1] × p[j]","p[i-1] × p[k] × p[j]","p[i] × p[k] × p[j]","p[i-1] × p[k-1] × p[j]"],"correct":1,"explanation":"Multiplying (Ai..Ak) which is p[i-1]×p[k] by (Ak+1..Aj) which is p[k]×p[j] costs p[i-1]×p[k]×p[j] scalar multiplications."},{"id":"dynamic-programming/matrix-chain-multiplication#2","route":"/dynamic-programming/matrix-chain-multiplication","section":"dynamic-programming","subject":"dsa","title":"Matrix Chain Multiplication – DP Visualizer","question":"What is the time complexity of the MCM DP algorithm?","options":["O(n)","O(n²)","O(n³)","O(2ⁿ)"],"correct":2,"explanation":"Three nested loops: chain lengths (n), starting points (n), and split points (n) — giving O(n³). Much better than the Catalan-number-exponential naive approach."},{"id":"dynamic-programming/maximum-subarray#0","route":"/dynamic-programming/maximum-subarray","section":"dynamic-programming","subject":"dsa","title":"Maximum Subarray (Kadane's Algorithm) Visualizer","question":"What decision does Kadane's algorithm make at each element?","options":["Whether to sort the element into place","Whether to extend the current subarray or restart from this element","Whether to skip the element entirely","Whether to swap it with the running maximum"],"correct":1,"explanation":"At index i the running sum becomes max(nums[i], currentSum + nums[i]). If the sum carried in is negative it can only hurt, so the algorithm drops it and restarts the subarray at i."},{"id":"dynamic-programming/maximum-subarray#1","route":"/dynamic-programming/maximum-subarray","section":"dynamic-programming","subject":"dsa","title":"Maximum Subarray (Kadane's Algorithm) Visualizer","question":"Why must maxSum start at nums[0] rather than 0?","options":["To save one loop iteration","Because 0 is not a valid array index","So an all-negative array returns its largest element instead of 0","Because the array is always sorted"],"correct":2,"explanation":"Starting maxSum at 0 would return 0 for an all-negative array, implying an empty subarray. Seeding it with nums[0] guarantees the answer is a real, non-empty subarray."},{"id":"dynamic-programming/maximum-subarray#2","route":"/dynamic-programming/maximum-subarray","section":"dynamic-programming","subject":"dsa","title":"Maximum Subarray (Kadane's Algorithm) Visualizer","question":"What are Kadane's time and space complexities?","options":["O(n²) time, O(1) space","O(n log n) time, O(n) space","O(n) time, O(n) space","O(n) time, O(1) space"],"correct":3,"explanation":"One pass over the array gives O(n) time, and only two numbers need to be carried — the running sum and the best sum — so space is O(1)."},{"id":"graph-algorithms/breadth-first-search#0","route":"/graph-algorithms/breadth-first-search","section":"graph-algorithms","subject":"dsa","title":"Breadth-First Search Visualizer – Level-by-Level Graph Traversal","question":"What data structure does BFS use to track nodes to visit?","options":["Stack (LIFO)","Queue (FIFO)","Priority Queue","Deque"],"correct":1,"explanation":"BFS uses a Queue (First-In, First-Out). This ensures nodes are explored level by level — all nodes at distance 1 before distance 2, and so on."},{"id":"graph-algorithms/breadth-first-search#1","route":"/graph-algorithms/breadth-first-search","section":"graph-algorithms","subject":"dsa","title":"Breadth-First Search Visualizer – Level-by-Level Graph Traversal","question":"What is BFS's time complexity for a graph with V vertices and E edges?","options":["O(V²)","O(V log V)","O(V + E)","O(E log V)"],"correct":2,"explanation":"BFS visits every vertex once and explores every edge once, giving O(V + E). For dense graphs this approaches O(V²), for sparse graphs it's closer to O(V)."},{"id":"graph-algorithms/breadth-first-search#2","route":"/graph-algorithms/breadth-first-search","section":"graph-algorithms","subject":"dsa","title":"Breadth-First Search Visualizer – Level-by-Level Graph Traversal","question":"BFS guarantees the shortest path between two nodes in which type of graph?","options":["Weighted directed graphs","Unweighted graphs only","Any graph with positive weights","Graphs without cycles"],"correct":1,"explanation":"BFS guarantees the shortest path (minimum edges) only in unweighted graphs. For weighted graphs, Dijkstra's or Bellman-Ford must be used."},{"id":"graph-algorithms/connected-components#0","route":"/graph-algorithms/connected-components","section":"graph-algorithms","subject":"dsa","title":"Connected Components Visualizer","question":"What is a connected component in an undirected graph?","options":["The node with the most edges","A maximal set of nodes that are all reachable from one another","The shortest path between two nodes","Any pair of nodes joined by an edge"],"correct":1,"explanation":"A connected component is a maximal group of nodes where every node can reach every other node in the group. 'Maximal' means you can't add another node without breaking that property."},{"id":"graph-algorithms/connected-components#1","route":"/graph-algorithms/connected-components","section":"graph-algorithms","subject":"dsa","title":"Connected Components Visualizer","question":"How do you find all connected components?","options":["Sort the nodes by degree","Run one BFS from node 0","Scan every node; each unvisited one seeds a new BFS/DFS that claims its whole component","Compute the shortest path between all pairs"],"correct":2,"explanation":"Iterate over all nodes. When you hit an unvisited node, it belongs to a brand-new component — run BFS or DFS from it to mark every reachable node, then continue scanning. The count of such seeds is the number of components."},{"id":"graph-algorithms/connected-components#2","route":"/graph-algorithms/connected-components","section":"graph-algorithms","subject":"dsa","title":"Connected Components Visualizer","question":"What is the time complexity of finding connected components?","options":["O(V²)","O(V + E)","O(E log V)","O(V!)"],"correct":1,"explanation":"Each node and each edge is visited exactly once across all the BFS/DFS runs combined, giving O(V + E) — the same as a single traversal, just restarted for each new component."},{"id":"graph-algorithms/depth-first-search#0","route":"/graph-algorithms/depth-first-search","section":"graph-algorithms","subject":"dsa","title":"Depth-First Search Visualizer – Recursive Graph Traversal","question":"What data structure underlies DFS (iteratively)?","options":["Queue (FIFO)","Stack (LIFO)","Priority Queue","Circular Buffer"],"correct":1,"explanation":"DFS uses a Stack (Last-In, First-Out). The recursive implementation uses the call stack implicitly. The iterative version uses an explicit stack."},{"id":"graph-algorithms/depth-first-search#1","route":"/graph-algorithms/depth-first-search","section":"graph-algorithms","subject":"dsa","title":"Depth-First Search Visualizer – Recursive Graph Traversal","question":"Which application is DFS best suited for?","options":["Finding shortest path in unweighted graphs","Topological sorting of a DAG","Finding all nodes within distance k","Computing minimum spanning tree"],"correct":1,"explanation":"DFS is the foundation for topological sorting, cycle detection, and finding strongly connected components. Its depth-first nature makes it ideal for these structural problems."},{"id":"graph-algorithms/depth-first-search#2","route":"/graph-algorithms/depth-first-search","section":"graph-algorithms","subject":"dsa","title":"Depth-First Search Visualizer – Recursive Graph Traversal","question":"What is DFS's time complexity?","options":["O(V²)","O(V log V)","O(V + E)","O(E log V)"],"correct":2,"explanation":"DFS visits every vertex once and traverses every edge once, giving O(V + E) — same as BFS."},{"id":"graph-algorithms/dijkstras-shortest-path#0","route":"/graph-algorithms/dijkstras-shortest-path","section":"graph-algorithms","subject":"dsa","title":"Dijkstra's Shortest Path Visualizer – Weighted Graph Animation","question":"What data structure makes Dijkstra's efficient?","options":["Regular Queue","Stack","Min-Priority Queue (Min-Heap)","Hash Map"],"correct":2,"explanation":"A min-priority queue (min-heap) lets Dijkstra's always process the unvisited node with the smallest known distance in O(log V) time."},{"id":"graph-algorithms/dijkstras-shortest-path#1","route":"/graph-algorithms/dijkstras-shortest-path","section":"graph-algorithms","subject":"dsa","title":"Dijkstra's Shortest Path Visualizer – Weighted Graph Animation","question":"Can Dijkstra's algorithm handle negative edge weights?","options":["Yes, always","No — it may give wrong results","Only if there are no negative cycles","Yes, with a special flag"],"correct":1,"explanation":"Dijkstra's greedy assumption breaks with negative edges. Once a node is settled it's never revisited, so a later negative edge could yield a shorter path. Use Bellman-Ford instead."},{"id":"graph-algorithms/dijkstras-shortest-path#2","route":"/graph-algorithms/dijkstras-shortest-path","section":"graph-algorithms","subject":"dsa","title":"Dijkstra's Shortest Path Visualizer – Weighted Graph Animation","question":"What does Dijkstra's guarantee at termination?","options":["A minimum spanning tree","Shortest path from source to all reachable nodes","Topological order","Detection of negative cycles"],"correct":1,"explanation":"When finished, the distance table holds the shortest path length from the source to every reachable node. Follow predecessor pointers to reconstruct the actual path."},{"id":"graph-algorithms/floyd-warshall#0","route":"/graph-algorithms/floyd-warshall","section":"graph-algorithms","subject":"dsa","title":"Floyd-Warshall Visualizer – All-Pairs Shortest Path","question":"What does Floyd-Warshall compute?","options":["Shortest path from one source to all nodes","Shortest paths between every pair of nodes","A minimum spanning tree","A topological ordering"],"correct":1,"explanation":"Floyd-Warshall is an all-pairs shortest path algorithm: after it runs, dist[i][j] holds the shortest distance from i to j for every pair — a full V×V table."},{"id":"graph-algorithms/floyd-warshall#1","route":"/graph-algorithms/floyd-warshall","section":"graph-algorithms","subject":"dsa","title":"Floyd-Warshall Visualizer – All-Pairs Shortest Path","question":"What does the outer loop variable k represent?","options":["The source node","The current shortest distance","An intermediate node that paths are now allowed to pass through","The number of edges used"],"correct":2,"explanation":"After iteration k, dist[i][j] is the shortest path using only nodes {0..k} as intermediates. Adding one more allowed intermediate each round is the dynamic-programming insight: dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j])."},{"id":"graph-algorithms/floyd-warshall#2","route":"/graph-algorithms/floyd-warshall","section":"graph-algorithms","subject":"dsa","title":"Floyd-Warshall Visualizer – All-Pairs Shortest Path","question":"What is Floyd-Warshall's time and space complexity?","options":["O(V + E) time, O(V) space","O(E log V) time, O(V) space","O(V³) time, O(V²) space","O(2^V) time, O(V²) space"],"correct":2,"explanation":"Three nested loops over V nodes give O(V³) time; the distance matrix takes O(V²) space. It handles negative edges (but not negative cycles) — a plus over Dijkstra's."},{"id":"graph-algorithms/kruskal-minimum-spanning-tree#0","route":"/graph-algorithms/kruskal-minimum-spanning-tree","section":"graph-algorithms","subject":"dsa","title":"Kruskal's Minimum Spanning Tree Visualizer","question":"How does Kruskal's algorithm decide which edges to keep?","options":["It grows a tree outward from a start node","It sorts all edges by weight and adds each one unless it would form a cycle","It adds the most expensive edges first","It picks edges at random until all nodes connect"],"correct":1,"explanation":"Kruskal's is greedy on globally-sorted edges: process edges cheapest-first, adding an edge only if its endpoints are in different components (adding it can't create a cycle). Stop once V−1 edges are chosen."},{"id":"graph-algorithms/kruskal-minimum-spanning-tree#1","route":"/graph-algorithms/kruskal-minimum-spanning-tree","section":"graph-algorithms","subject":"dsa","title":"Kruskal's Minimum Spanning Tree Visualizer","question":"What data structure tells Kruskal's whether an edge would create a cycle?","options":["A min-heap","A queue","Union-Find (disjoint set union)","A hash map of visited edges"],"correct":2,"explanation":"Union-Find tracks which nodes are already connected. find(u) == find(v) means u and v are in the same component, so the edge would close a cycle — skip it. Otherwise union(u, v) merges the two components."},{"id":"graph-algorithms/kruskal-minimum-spanning-tree#2","route":"/graph-algorithms/kruskal-minimum-spanning-tree","section":"graph-algorithms","subject":"dsa","title":"Kruskal's Minimum Spanning Tree Visualizer","question":"How does Kruskal's differ from Prim's?","options":["Kruskal's finds shortest paths, Prim's finds the MST","Kruskal's sorts all edges globally and merges separate forests with union-find; Prim's grows one connected tree from a start node","They always pick edges in the same order","Prim's cannot handle weighted graphs"],"correct":1,"explanation":"Both build an MST. Kruskal's considers edges globally by weight, merging a forest of trees until one remains. Prim's expands a single tree from a start node via the cheapest edge on its cut. Kruskal's shines on sparse edge lists; Prim's on dense graphs."},{"id":"graph-algorithms/prims-minimum-spanning-tree#0","route":"/graph-algorithms/prims-minimum-spanning-tree","section":"graph-algorithms","subject":"dsa","title":"Prim's Minimum Spanning Tree Visualizer","question":"What does Prim's algorithm build?","options":["The shortest path between two nodes","A minimum spanning tree — the cheapest set of edges connecting all nodes","A topological ordering","All connected components"],"correct":1,"explanation":"Prim's produces a Minimum Spanning Tree (MST): a subset of edges that connects every node with the least possible total weight and no cycles. Note this is not the same as shortest paths."},{"id":"graph-algorithms/prims-minimum-spanning-tree#1","route":"/graph-algorithms/prims-minimum-spanning-tree","section":"graph-algorithms","subject":"dsa","title":"Prim's Minimum Spanning Tree Visualizer","question":"At each step, which edge does Prim's add?","options":["The globally smallest unused edge","The cheapest edge crossing from the tree to a node not yet in the tree","A random edge from the frontier","The edge with the most endpoints in the tree"],"correct":1,"explanation":"Prim's grows one tree. It always adds the minimum-weight edge on the 'cut' — the boundary between in-tree nodes and the rest — bringing exactly one new node into the tree each step."},{"id":"graph-algorithms/prims-minimum-spanning-tree#2","route":"/graph-algorithms/prims-minimum-spanning-tree","section":"graph-algorithms","subject":"dsa","title":"Prim's Minimum Spanning Tree Visualizer","question":"How does Prim's differ from Kruskal's?","options":["They produce different trees","Prim's grows one tree from a start node; Kruskal's adds globally-cheapest edges anywhere, merging forests with union-find","Prim's only works on directed graphs","Kruskal's cannot handle weights"],"correct":1,"explanation":"Both find an MST. Prim's expands a single connected tree outward from a start node via the cut. Kruskal's sorts all edges and adds the cheapest that doesn't form a cycle, merging separate trees using union-find."},{"id":"graph-algorithms/topological-sort-dfs#0","route":"/graph-algorithms/topological-sort-dfs","section":"graph-algorithms","subject":"dsa","title":"Topological Sort (DFS) Visualizer","question":"In DFS-based topological sort, when is a node recorded?","options":["As soon as DFS first visits it (pre-order)","When it finishes — after all nodes reachable from it are done (post-order)","When its in-degree reaches zero","In the order nodes were created"],"correct":1,"explanation":"A node is pushed onto the finish stack only when DFS returns from it — i.e. after every descendant has finished. That's post-order. It guarantees the node's dependents were recorded first."},{"id":"graph-algorithms/topological-sort-dfs#1","route":"/graph-algorithms/topological-sort-dfs","section":"graph-algorithms","subject":"dsa","title":"Topological Sort (DFS) Visualizer","question":"Why do we reverse the finish order to get the topological order?","options":["To sort the nodes numerically","Because a node finishes AFTER everything reachable from it, so reversing puts it BEFORE them","Reversing is optional — the finish order is already topological","To detect cycles"],"correct":1,"explanation":"If u → v, then v finishes before u (u is still on the stack while v completes). So the finish order has dependents before dependencies; reversing it makes every edge point from earlier to later."},{"id":"graph-algorithms/topological-sort-dfs#2","route":"/graph-algorithms/topological-sort-dfs","section":"graph-algorithms","subject":"dsa","title":"Topological Sort (DFS) Visualizer","question":"How does the DFS approach compare to Kahn's algorithm?","options":["DFS is O(V²), Kahn's is O(V + E)","Both are O(V + E); DFS uses recursion + a finish stack, Kahn's uses in-degrees + a queue","DFS only works on trees","Kahn's cannot detect cycles but DFS can't either"],"correct":1,"explanation":"Both run in O(V + E) and produce a valid (not necessarily identical) topological order. DFS records nodes on completion and reverses; Kahn's repeatedly removes in-degree-zero nodes. Both can detect cycles."},{"id":"graph-algorithms/topological-sort-indegree#0","route":"/graph-algorithms/topological-sort-indegree","section":"graph-algorithms","subject":"dsa","title":"Topological Sort (Kahn's Algorithm) Visualizer","question":"What does a topological sort produce, and when does it exist?","options":["A shortest path; for any graph","A linear ordering where every edge goes from earlier to later; only for a DAG (no cycles)","A minimum spanning tree; for weighted graphs","The connected components; for undirected graphs"],"correct":1,"explanation":"A topological order lists the nodes so that every directed edge u→v has u before v. It exists only for a Directed Acyclic Graph — a cycle would require a node to come before itself."},{"id":"graph-algorithms/topological-sort-indegree#1","route":"/graph-algorithms/topological-sort-indegree","section":"graph-algorithms","subject":"dsa","title":"Topological Sort (Kahn's Algorithm) Visualizer","question":"What does Kahn's algorithm repeatedly do?","options":["Remove the node with the highest out-degree","Remove any node whose in-degree is currently zero, then decrement its neighbours' in-degrees","Pick the smallest-weight edge","Run DFS and reverse the finish order"],"correct":1,"explanation":"Kahn's keeps a queue of in-degree-zero nodes (nothing left pointing at them). It removes one, appends it to the order, and decrements each neighbour's in-degree — enqueueing any that hit zero."},{"id":"graph-algorithms/topological-sort-indegree#2","route":"/graph-algorithms/topological-sort-indegree","section":"graph-algorithms","subject":"dsa","title":"Topological Sort (Kahn's Algorithm) Visualizer","question":"During Kahn's algorithm, how do you detect that the graph has a cycle?","options":["The queue grows without bound","A node's in-degree goes negative","The output order contains fewer than all the nodes when the queue empties","Two nodes share the same in-degree"],"correct":2,"explanation":"If a cycle exists, its nodes never reach in-degree zero, so the queue empties before all nodes are output. Comparing the count of sorted nodes to the total detects the cycle."},{"id":"heap-like-data-structures/binomial-queues#0","route":"/heap-like-data-structures/binomial-queues","section":"heap-like-data-structures","subject":"dsa","title":"Binomial Queue Visualizer – Binomial Heap Animation","question":"Merging two binomial queues is analogous to which mathematical operation?","options":["Decimal addition","Binary number addition","Matrix multiplication","Polynomial division"],"correct":1,"explanation":"Binomial queue merging mirrors binary addition: each rank is a 'bit position', at most one tree per rank exists, and two trees of the same rank merge to form a tree of the next rank — exactly like carrying in binary addition."},{"id":"heap-like-data-structures/binomial-queues#1","route":"/heap-like-data-structures/binomial-queues","section":"heap-like-data-structures","subject":"dsa","title":"Binomial Queue Visualizer – Binomial Heap Animation","question":"A binomial tree B_k contains exactly how many nodes?","options":["k nodes","k² nodes","2^k nodes","k × log k nodes"],"correct":2,"explanation":"Binomial tree B_k has exactly 2^k nodes. B_0 is a single node; B_k is formed by making one B_(k-1) the leftmost child of another, doubling the size each time."},{"id":"heap-like-data-structures/binomial-queues#2","route":"/heap-like-data-structures/binomial-queues","section":"heap-like-data-structures","subject":"dsa","title":"Binomial Queue Visualizer – Binomial Heap Animation","question":"What is the amortized time complexity of inserting a single element into a binomial queue?","options":["O(1)","O(log n)","O(n)","O(n log n)"],"correct":0,"explanation":"Insert is O(1) amortized (O(log n) worst case). Like incrementing a binary counter, most inserts only touch a small number of trees; the average over many operations is O(1)."},{"id":"heap-like-data-structures/fibonacci-heaps#0","route":"/heap-like-data-structures/fibonacci-heaps","section":"heap-like-data-structures","subject":"dsa","title":"Fibonacci Heap Visualizer – Amortized O(1) Insert Animation","question":"What is the amortized time complexity of inserting into a Fibonacci heap?","options":["O(log n)","O(n)","O(1)","O(√n)"],"correct":2,"explanation":"Insert is O(1) amortized — the new node is simply added to the root list as a singleton tree. No consolidation happens until extract-min. The lazy approach makes insert extremely fast."},{"id":"heap-like-data-structures/fibonacci-heaps#1","route":"/heap-like-data-structures/fibonacci-heaps","section":"heap-like-data-structures","subject":"dsa","title":"Fibonacci Heap Visualizer – Amortized O(1) Insert Animation","question":"When does consolidation (linking trees of equal degree) happen in a Fibonacci heap?","options":["After every insert","After every decrease-key","Only during extract-min","Periodically in the background"],"correct":2,"explanation":"Consolidation is deferred until extract-min. This lazy strategy is why insert and decrease-key are O(1) — all expensive work is batched into the extract-min call, which runs in O(log n) amortized."},{"id":"heap-like-data-structures/fibonacci-heaps#2","route":"/heap-like-data-structures/fibonacci-heaps","section":"heap-like-data-structures","subject":"dsa","title":"Fibonacci Heap Visualizer – Amortized O(1) Insert Animation","question":"Compared to a binary heap, what operation gives the Fibonacci heap a decisive advantage in Dijkstra's algorithm?","options":["Insert O(1) vs O(log n)","Extract-min O(log n) vs O(log n)","Decrease-key O(1) vs O(log n)","Build heap O(n) vs O(n)"],"correct":2,"explanation":"Decrease-key is O(1) amortized in a Fibonacci heap vs O(log n) in a binary heap. Since Dijkstra's calls decrease-key E times and extract-min V times, the total becomes O(E + V log V) instead of O((E + V) log V)."},{"id":"heap-like-data-structures/heaps#0","route":"/heap-like-data-structures/heaps","section":"heap-like-data-structures","subject":"dsa","title":"Binary Heap Visualizer – Min/Max Heap Animation","question":"For a node at index i (0-indexed) in a binary heap array, what index holds its left child?","options":["2i","2i + 1","2i + 2","(i − 1) / 2"],"correct":1,"explanation":"Left child is at 2i+1, right child is at 2i+2, and the parent is at ⌊(i−1)/2⌋. These formulas let you navigate a complete binary tree stored in an array."},{"id":"heap-like-data-structures/heaps#1","route":"/heap-like-data-structures/heaps","section":"heap-like-data-structures","subject":"dsa","title":"Binary Heap Visualizer – Min/Max Heap Animation","question":"What is the time complexity of building a heap from n unsorted elements using bottom-up heapify (Floyd's algorithm)?","options":["O(n log n)","O(log n)","O(n)","O(n²)"],"correct":2,"explanation":"Bottom-up heapify runs in O(n) time. Although heapify-down is O(log n), most nodes are near the bottom where the subtrees are small — the total work sums to O(n)."},{"id":"heap-like-data-structures/heaps#2","route":"/heap-like-data-structures/heaps","section":"heap-like-data-structures","subject":"dsa","title":"Binary Heap Visualizer – Min/Max Heap Animation","question":"In a max-heap, which property holds for every node?","options":["Left child ≥ right child at every node","Parent ≥ both children","All leaves are at the same depth","Parent ≤ both children"],"correct":1,"explanation":"The max-heap property requires every parent to be ≥ both its children. This guarantees the maximum element sits at the root and is accessible in O(1)."},{"id":"heap-like-data-structures/leftist-heaps#0","route":"/heap-like-data-structures/leftist-heaps","section":"heap-like-data-structures","subject":"dsa","title":"Leftist Heap Visualizer – Left-Biased Merge Animation","question":"What does 'npl' (null path length) mean for a node in a leftist heap?","options":["The height of the tallest subtree","The shortest path from the node to a null descendant","The number of children the node has","The depth of the node from the root"],"correct":1,"explanation":"npl(node) is the length of the shortest path from that node to a null child. Leaf nodes have npl=0. The leftist property requires npl(left) ≥ npl(right) at every node, keeping the right spine short."},{"id":"heap-like-data-structures/leftist-heaps#1","route":"/heap-like-data-structures/leftist-heaps","section":"heap-like-data-structures","subject":"dsa","title":"Leftist Heap Visualizer – Left-Biased Merge Animation","question":"The leftist property guarantees that which path is always at most O(log n) long?","options":["The leftmost path from root to leaf","The path to the deepest node","The right spine (rightmost path)","The path between any two nodes"],"correct":2,"explanation":"The right spine — the path from root always going right — has length at most O(log n). Merge, insert, and extract-min all operate only on this spine, giving O(log n) complexity."},{"id":"heap-like-data-structures/leftist-heaps#2","route":"/heap-like-data-structures/leftist-heaps","section":"heap-like-data-structures","subject":"dsa","title":"Leftist Heap Visualizer – Left-Biased Merge Animation","question":"In a leftist heap, insert(x) is implemented as:","options":["Add x to an array and heapify-up","Merge the heap with a singleton node containing x","Scan the right spine to find the insertion point","Build a new heap from scratch including x"],"correct":1,"explanation":"Insert is simply merge(heap, singleton(x)). The merge operation handles all positioning and npl maintenance. This elegance is why merge-based heaps like leftist and skew heaps only need one primitive operation."},{"id":"heap-like-data-structures/skew-heaps#0","route":"/heap-like-data-structures/skew-heaps","section":"heap-like-data-structures","subject":"dsa","title":"Skew Heap Visualizer – Self-Adjusting Heap Animation","question":"What makes skew heaps 'self-adjusting' and different from leftist heaps?","options":["Skew heaps maintain null path length at every node","Skew heaps unconditionally swap left and right children during every merge step","Skew heaps use a separate balance counter per node","Skew heaps only allow insertion, not extraction"],"correct":1,"explanation":"In skew heaps, after recursively merging the right subtree, the children are always unconditionally swapped — no condition checked, no npl stored. This simple rule provides amortized O(log n) performance without any bookkeeping."},{"id":"heap-like-data-structures/skew-heaps#1","route":"/heap-like-data-structures/skew-heaps","section":"heap-like-data-structures","subject":"dsa","title":"Skew Heap Visualizer – Self-Adjusting Heap Animation","question":"What is the amortized time complexity of merging two skew heaps of sizes m and n?","options":["O(1)","O(m + n)","O(log(m + n))","O(m × n)"],"correct":2,"explanation":"Merge runs in O(log(m+n)) amortized time. Individual operations can be O(n) worst case, but the unconditional swap self-balances the heap over a sequence of operations, giving the O(log n) amortized guarantee."},{"id":"heap-like-data-structures/skew-heaps#2","route":"/heap-like-data-structures/skew-heaps","section":"heap-like-data-structures","subject":"dsa","title":"Skew Heap Visualizer – Self-Adjusting Heap Animation","question":"Skew heap differs from leftist heap in that skew heap:","options":["Stores npl but conditionally skips the swap","Requires no extra metadata per node and always swaps children","Uses a rank field instead of npl","Only works as a max-heap, not min-heap"],"correct":1,"explanation":"Skew heap stores no extra per-node metadata (no npl, no rank) and always swaps children after every merge step. Leftist heap stores npl and only swaps when npl(left) < npl(right). Skew is simpler to implement."},{"id":"indexing/b-plus-trees#0","route":"/indexing/b-plus-trees","section":"indexing","subject":"dsa","title":"B+ Tree Visualizer – Linked Leaves and Range Scans","question":"In a B+ tree, where do the actual records live?","options":["Spread across internal nodes and leaves alike","Only in the leaves; internal nodes hold separators","Only in the root, with leaves holding pointers","In a separate overflow area beside the tree"],"correct":1,"explanation":"Internal nodes are pure routing — they hold separator keys only. Every record sits in a leaf. That is what lets internal nodes pack in more separators per block, keeping the tree shallower than an equivalent B-tree."},{"id":"indexing/b-plus-trees#1","route":"/indexing/b-plus-trees","section":"indexing","subject":"dsa","title":"B+ Tree Visualizer – Linked Leaves and Range Scans","question":"When a B+ tree leaf splits, what happens to the median key?","options":["It moves up to the parent and leaves the leaves","It is copied up, and the original stays in the right leaf","It is duplicated into both leaves","It is written to the overflow area"],"correct":1,"explanation":"A leaf split copies the key up as a separator while keeping it in the right leaf. It has to stay — if it moved, that record would vanish from the leaf level, and the leaf level is the only place records exist. Internal splits still move the median."},{"id":"indexing/b-plus-trees#2","route":"/indexing/b-plus-trees","section":"indexing","subject":"dsa","title":"B+ Tree Visualizer – Linked Leaves and Range Scans","question":"Why is \"SELECT … WHERE id BETWEEN 100 AND 200\" fast on a B+ tree?","options":["The separators let it skip straight to key 200","Range queries are cached separately from point queries","Find the first leaf, then follow the leaf links sideways — no climbing back up","The tree re-sorts itself around the queried range"],"correct":2,"explanation":"One descent locates the start of the range, then the linked leaves are read in order like an array. A plain B-tree would have to walk back up and down the tree between consecutive records, which is why B+ trees dominate database indexes."},{"id":"indexing/b-trees#0","route":"/indexing/b-trees","section":"indexing","subject":"dsa","title":"B-Tree Visualizer – Node Splits and Promotion","question":"When a B-tree node overflows, where does the median key go?","options":["It stays in the left half","It is promoted into the parent node","It is pushed down into a new leaf","It is discarded and reinserted later"],"correct":1,"explanation":"The median moves up into the parent, and the remaining keys become two siblings on either side of it. This is why a B-tree grows at the root rather than at the leaves — and why every leaf stays at exactly the same depth."},{"id":"indexing/b-trees#1","route":"/indexing/b-trees","section":"indexing","subject":"dsa","title":"B-Tree Visualizer – Node Splits and Promotion","question":"Why are B-tree nodes made wide rather than binary?","options":["Wide nodes use less memory per key","A wider node sorts its keys faster","One disk or cache block costs the same whether you read 1 key or 200, so fanout buys depth for free","Binary trees cannot be kept balanced"],"correct":2,"explanation":"Reading a block is the unit of cost. Packing hundreds of keys into one block means a tree of a few levels can index millions of records — three block reads instead of twenty pointer-chases down a binary tree."},{"id":"indexing/b-trees#2","route":"/indexing/b-trees","section":"indexing","subject":"dsa","title":"B-Tree Visualizer – Node Splits and Promotion","question":"What guarantees every leaf of a B-tree sits at the same depth?","options":["Rebalancing rotations after each insert","The tree only ever grows by splitting the root upward","Keys are inserted in sorted order","A periodic rebuild of the whole tree"],"correct":1,"explanation":"Splits push a key up, never down. Depth changes only when the root itself splits, which lengthens every root-to-leaf path at once — so the tree is perfectly height-balanced by construction."},{"id":"indexing/closed-hash-tables#0","route":"/indexing/closed-hash-tables","section":"indexing","subject":"dsa","title":"Closed Hash Tables (Open Addressing) Visualizer","question":"Why can a closed hash table never hold more keys than it has slots?","options":["Because the hash function only produces m distinct values","Because every key must occupy a slot of the table itself","Because the load factor is capped by the probe sequence","It can — it resizes automatically when full"],"correct":1,"explanation":"Closed hashing (open addressing) stores every key inside the table array. With n keys and m slots, α = n/m can never exceed 1, and performance collapses well before that — most implementations resize around α = 0.7."},{"id":"indexing/closed-hash-tables#1","route":"/indexing/closed-hash-tables","section":"indexing","subject":"dsa","title":"Closed Hash Tables (Open Addressing) Visualizer","question":"What is primary clustering, and which probe strategy suffers from it?","options":["Keys bunching into long runs of filled slots — linear probing","Two keys sharing a home slot — double hashing","Tombstones accumulating after deletes — quadratic probing","Buckets overflowing into a shared area — all three equally"],"correct":0,"explanation":"Linear probing walks one slot at a time, so any run of filled slots grows at both ends and merges with its neighbours. Every key landing anywhere in the run must traverse all of it. Quadratic probing and double hashing scatter their probes and avoid this."},{"id":"indexing/closed-hash-tables#2","route":"/indexing/closed-hash-tables","section":"indexing","subject":"dsa","title":"Closed Hash Tables (Open Addressing) Visualizer","question":"Why does deleting a key need a tombstone rather than just clearing the slot?","options":["To preserve the original insertion order","To let the table know when to resize","Because an empty slot would end probe sequences early, hiding later keys","Because the hash function cannot be run in reverse"],"correct":2,"explanation":"A lookup stops at the first truly empty slot. If a delete left a hole mid-sequence, any key that probed past that slot on insert would become unreachable. A tombstone says \"keep going\" while still being reusable by a later insert."},{"id":"indexing/closed-hash-tables-with-buckets#0","route":"/indexing/closed-hash-tables-with-buckets","section":"indexing","subject":"dsa","title":"Closed Hash Tables with Buckets Visualizer","question":"Why does giving each slot a bucket of several entries help, when the total capacity is unchanged?","options":["It lowers the load factor by definition","A bucket is one cache line, so most collisions cost no extra memory fetch","It makes the hash function more uniform","It removes the need for tombstones"],"correct":1,"explanation":"Capacity is the same, but locality is not. A bucket sized to a cache line means the first collision is resolved from memory already loaded — no second fetch. Probing to another slot, by contrast, is very likely a cache miss."},{"id":"indexing/closed-hash-tables-with-buckets#1","route":"/indexing/closed-hash-tables-with-buckets","section":"indexing","subject":"dsa","title":"Closed Hash Tables with Buckets Visualizer","question":"What happens when a key hashes to a bucket that is already full?","options":["The table immediately resizes","The key is rejected","It probes on to the next bucket, and only spills to overflow if all are full","The bucket grows dynamically to fit it"],"correct":2,"explanation":"A full bucket falls back to ordinary probing — try the next bucket. Only when no bucket has room does the key go to the overflow area, which is a linear scan and the slowest path in the structure."},{"id":"indexing/closed-hash-tables-with-buckets#2","route":"/indexing/closed-hash-tables-with-buckets","section":"indexing","subject":"dsa","title":"Closed Hash Tables with Buckets Visualizer","question":"What is the main cost of making buckets larger?","options":["Lookups scan more entries within a bucket","The hash function becomes slower to compute","Deletes stop working without tombstones","The load factor can exceed 1"],"correct":0,"explanation":"Every lookup scans the whole bucket before moving on, so a large bucket trades fewer memory fetches for more comparisons. The sweet spot is a bucket that fits one cache line — big enough to absorb collisions, small enough that the scan is trivial."},{"id":"indexing/open-hash-tables#0","route":"/indexing/open-hash-tables","section":"indexing","subject":"dsa","title":"Open Hash Tables (Separate Chaining) Visualizer","question":"In an \"open hash table\", where do colliding keys actually live?","options":["In the next free slot of the table itself","In a chain hanging off the slot, outside the table array","They are rejected until the table is resized","In a second table with a different hash function"],"correct":1,"explanation":"Open hashing (separate chaining) stores each slot's keys in a list outside the table array, so the table never runs out of space for a collision. The confusingly named \"closed hashing\" is the one that keeps every key inside the table."},{"id":"indexing/open-hash-tables#1","route":"/indexing/open-hash-tables","section":"indexing","subject":"dsa","title":"Open Hash Tables (Separate Chaining) Visualizer","question":"The load factor α is n/m. What does it tell you here?","options":["The fraction of slots that are occupied, capped at 1","The average chain length, which can exceed 1","The number of resize operations performed","The probability that the hash function is uniform"],"correct":1,"explanation":"With chaining, n keys spread over m slots gives an average chain length of exactly α. Unlike open addressing, α can go above 1 — the table keeps working, lookups just get slower in proportion."},{"id":"indexing/open-hash-tables#2","route":"/indexing/open-hash-tables","section":"indexing","subject":"dsa","title":"Open Hash Tables (Separate Chaining) Visualizer","question":"What makes a lookup degrade to O(n)?","options":["A load factor above 0.75","Deleting more keys than you insert","Every key hashing to the same slot","Using a table size that is a power of two"],"correct":2,"explanation":"If the hash function sends every key to one slot, the table becomes a single linked list and lookup is a linear scan. This is why hash quality matters as much as table size."},{"id":"indexing/radix-tree#0","route":"/indexing/radix-tree","section":"indexing","subject":"dsa","title":"Radix Tree Visualizer – Compressing a Trie","question":"What exactly does a radix tree compress compared with a plain trie?","options":["Duplicate keys sharing the same value","Chains of nodes that each have exactly one child and end no word","Leaves that store the same suffix","The alphabet, by hashing each character"],"correct":1,"explanation":"A node with one child and no word ending at it carries no decision — it only passes through. Merging such a chain into a single edge labelled with the whole substring removes the nodes without changing which keys the structure holds."},{"id":"indexing/radix-tree#1","route":"/indexing/radix-tree","section":"indexing","subject":"dsa","title":"Radix Tree Visualizer – Compressing a Trie","question":"On which kind of key set does compression help most?","options":["Dense sets where every prefix is used","Sparse sets of long keys with few shared prefixes","Sets of single-character keys","Sets where all keys are identical"],"correct":1,"explanation":"Long keys that diverge early leave long single-child tails, and each tail collapses to one edge. A dense set where every prefix branches has almost nothing to compress — there the radix tree is just a trie with extra bookkeeping."},{"id":"indexing/radix-tree#2","route":"/indexing/radix-tree","section":"indexing","subject":"dsa","title":"Radix Tree Visualizer – Compressing a Trie","question":"How does lookup cost change after compression?","options":["It becomes O(log n) instead of O(m)","Still O(m) in characters compared, but far fewer nodes are visited","It becomes O(1)","It gets worse, because edge labels must be compared"],"correct":1,"explanation":"You still compare every character of the key, so the bound stays O(m). What changes is pointer-chasing: one edge can cover many characters, so far fewer nodes — and therefore far fewer cache misses — are touched."},{"id":"indexing/red-black-trees#0","route":"/indexing/red-black-trees","section":"indexing","subject":"dsa","title":"Red-Black Tree Visualizer – Recolouring and Rotations","question":"A newly inserted node is always coloured red. Why not black?","options":["Red nodes are cheaper to allocate","A black node would add 1 to the black-height of one path only, breaking the invariant immediately","Because the root must stay red","So that it can be found faster"],"correct":1,"explanation":"Every root-to-leaf path must contain the same number of black nodes. Inserting black would add one to exactly one path, violating that at once. Inserting red risks only a red-red pair, which recolouring or a rotation can repair locally."},{"id":"indexing/red-black-trees#1","route":"/indexing/red-black-trees","section":"indexing","subject":"dsa","title":"Red-Black Tree Visualizer – Recolouring and Rotations","question":"After a red-red violation, what decides between recolouring and rotating?","options":["The depth of the new node","Whether the tree is left- or right-leaning","The colour of the uncle — red means recolour, black means rotate","The total number of nodes"],"correct":2,"explanation":"A red uncle means the parent and uncle can both go black and the grandparent red, pushing the problem up two levels at no structural cost. A black uncle leaves no such slack, so the shape itself must change with a rotation."},{"id":"indexing/red-black-trees#2","route":"/indexing/red-black-trees","section":"indexing","subject":"dsa","title":"Red-Black Tree Visualizer – Recolouring and Rotations","question":"How does a red-black tree compare with an AVL tree?","options":["Red-black is always shallower","AVL is more strictly balanced, so it searches faster but rebalances more on writes","They produce identical trees for the same input","AVL cannot support deletion"],"correct":1,"explanation":"AVL keeps heights within 1, bounding depth near 1.44·log n; red-black allows up to 2·log n. AVL therefore wins on lookup-heavy loads, red-black on write-heavy ones — which is why language library maps usually pick red-black."},{"id":"indexing/splay-trees#0","route":"/indexing/splay-trees","section":"indexing","subject":"dsa","title":"Splay Tree Visualizer – Zig, Zig-Zig and Zig-Zag","question":"What does a splay tree do after every single access?","options":["Rebalances the whole tree to minimum height","Rotates the accessed node all the way to the root","Recolours the path from root to the node","Nothing — it only restructures on insert"],"correct":1,"explanation":"Every access — search, insert, even a failed lookup — splays the node it touched to the root. There is no balance factor and no colour; the access pattern itself is the only thing shaping the tree."},{"id":"indexing/splay-trees#1","route":"/indexing/splay-trees","section":"indexing","subject":"dsa","title":"Splay Tree Visualizer – Zig, Zig-Zig and Zig-Zag","question":"Why does zig-zig rotate the grandparent first, rather than just doing two zigs?","options":["It is faster to compute","Rotating the parent first would leave the path just as deep, so the amortised bound fails","It keeps the tree perfectly balanced","It avoids needing a parent pointer"],"correct":1,"explanation":"Two naive bottom-up single rotations leave the long path largely intact. Rotating the grandparent first roughly halves the depth of every node along that path, which is exactly what the potential-function argument needs for the O(log n) amortised bound."},{"id":"indexing/splay-trees#2","route":"/indexing/splay-trees","section":"indexing","subject":"dsa","title":"Splay Tree Visualizer – Zig, Zig-Zig and Zig-Zag","question":"A splay tree can be O(n) deep. Why is that acceptable?","options":["Because it never actually happens in practice","Because the bound is amortised — an expensive access flattens the path, so it cannot repeat","Because lookups skip the deep parts","Because the tree periodically rebuilds itself"],"correct":1,"explanation":"A single access really can cost O(n), but splaying that long path halves everyone's depth on the way out. Paying that cost makes the next accesses cheap, so any sequence of m operations costs O(m log n) overall."},{"id":"indexing/ternary-search-tree#0","route":"/indexing/ternary-search-tree","section":"indexing","subject":"dsa","title":"Ternary Search Tree Visualizer – Three-Way Branching","question":"What do the three children of a ternary search tree node mean?","options":["Three different alphabets","Lower, equal and higher — equal also advances to the next character of the key","Left subtree, right subtree and an overflow area","Three hash buckets"],"correct":1,"explanation":"The low and high children compare the same character position, exactly like a BST. Only the equal child consumes a character and moves on to the next position in the key. That one distinction is the whole structure."},{"id":"indexing/ternary-search-tree#1","route":"/indexing/ternary-search-tree","section":"indexing","subject":"dsa","title":"Ternary Search Tree Visualizer – Three-Way Branching","question":"How does a TST compare with a trie on memory?","options":["A TST uses more, because of the extra pointer","Identical, since both store one character per node","A TST uses far less — a trie node reserves a slot for every letter of the alphabet","It depends only on the number of words"],"correct":2,"explanation":"A classic trie node holds an array of R pointers (26, or 256 for bytes), most of them null. A TST node holds exactly three. For sparse key sets that is a large saving, at the cost of a few extra comparisons per character."},{"id":"indexing/ternary-search-tree#2","route":"/indexing/ternary-search-tree","section":"indexing","subject":"dsa","title":"Ternary Search Tree Visualizer – Three-Way Branching","question":"What is the search cost of a TST?","options":["O(1) like a hash table","O(m) exactly, same as a trie","O(log n + m) — a BST-like descent at each of the m character positions","O(n) in all cases"],"correct":2,"explanation":"At each character position you do a small BST search among the characters that actually appear there, then follow the equal child. That is roughly log n comparisons per position across m positions — slower than a trie's direct index, far cheaper in memory."},{"id":"operating-systems/bankers-algorithm#0","route":"/operating-systems/bankers-algorithm","section":"operating-systems","subject":"cs-core","title":"Banker's Algorithm Visualizer – Safety Check and Resource Requests","question":"The system is in an unsafe state. What does that tell you?","options":["The processes are deadlocked right now","Deadlock is possible: no order is guaranteed to let everyone finish","At least one process has exceeded its maximum claim","Available is zero for every resource type"],"correct":1,"explanation":"Unsafe is not the same as deadlocked. It means the OS can no longer guarantee an order in which every process finishes if each one asks for its full maximum. Processes may still release early and everything may work out — the Banker's algorithm simply refuses to take that gamble."},{"id":"operating-systems/bankers-algorithm#1","route":"/operating-systems/bankers-algorithm","section":"operating-systems","subject":"cs-core","title":"Banker's Algorithm Visualizer – Safety Check and Resource Requests","question":"How is the Need matrix computed?","options":["Max + Allocation","Available − Allocation","Max − Allocation","Total − Max"],"correct":2,"explanation":"Need[i][j] = Max[i][j] − Allocation[i][j]: how many more instances of resource j process i may still ask for before it is done. That is why every process must declare its Max up front."},{"id":"operating-systems/bankers-algorithm#2","route":"/operating-systems/bankers-algorithm","section":"operating-systems","subject":"cs-core","title":"Banker's Algorithm Visualizer – Safety Check and Resource Requests","question":"P1 requests resources. Request ≤ Need and Request ≤ Available both hold. What happens next?","options":["The request is granted immediately","The OS pretends to grant it and runs the safety check; it is granted only if the resulting state is safe","P1 must wait until another process finishes","The OS kills a process to free resources"],"correct":1,"explanation":"Passing both checks only means the request is possible. The algorithm tentatively allocates, runs the safety algorithm on the new state, and rolls back (making P1 wait) if that state would be unsafe."},{"id":"operating-systems/cpu-scheduling#0","route":"/operating-systems/cpu-scheduling","section":"operating-systems","subject":"cs-core","title":"CPU Scheduling Visualizer – FCFS, SJF, SRTF and Priority","question":"All processes arrive at time 0. Which non-preemptive policy gives the lowest possible average waiting time?","options":["FCFS","SJF","Priority","They all give the same average"],"correct":1,"explanation":"Running the shortest job first moves a short wait in front of every long one, and an exchange argument shows no other order can do better. That is why SJF is provably optimal for average waiting time — the catch is that real burst lengths are not known in advance."},{"id":"operating-systems/cpu-scheduling#1","route":"/operating-systems/cpu-scheduling","section":"operating-systems","subject":"cs-core","title":"CPU Scheduling Visualizer – FCFS, SJF, SRTF and Priority","question":"A 20 ms job arrives just before three 1 ms jobs. Under FCFS the short jobs wait behind it. What is this called?","options":["Starvation","The convoy effect","Priority inversion","Thrashing"],"correct":1,"explanation":"The convoy effect: one long CPU burst at the head of a FCFS queue holds up everything behind it, the way a slow truck holds up a line of cars. Average waiting time balloons even though the CPU is never idle."},{"id":"operating-systems/cpu-scheduling#2","route":"/operating-systems/cpu-scheduling","section":"operating-systems","subject":"cs-core","title":"CPU Scheduling Visualizer – FCFS, SJF, SRTF and Priority","question":"Under SJF or Priority scheduling, a long or low-priority job may wait forever if short or urgent jobs keep arriving. What is the standard fix?","options":["Make the time quantum smaller","Switch to FCFS whenever the queue is long","Aging — raise a process's priority the longer it waits","Run the longest job first"],"correct":2,"explanation":"Aging gradually increases the priority of a waiting process, so it eventually becomes the most urgent and runs. It bounds the wait without giving up the policy's preference for short or urgent work."},{"id":"operating-systems/deadlock-detection#0","route":"/operating-systems/deadlock-detection","section":"operating-systems","subject":"cs-core","title":"Deadlock Detection Visualizer – Resource-Allocation and Wait-For Graphs","question":"Every resource has exactly one instance. The wait-for graph has a cycle. What can you conclude?","options":["Deadlock is possible but not certain","The processes on the cycle are deadlocked","Every process in the system is deadlocked","Nothing — cycles only matter with multiple instances"],"correct":1,"explanation":"With single-instance resources a cycle is both necessary and sufficient: each process on it waits for the next, and none can ever release. With multiple instances a cycle is necessary but not sufficient, and detection needs a Banker-style algorithm instead."},{"id":"operating-systems/deadlock-detection#1","route":"/operating-systems/deadlock-detection","section":"operating-systems","subject":"cs-core","title":"Deadlock Detection Visualizer – Resource-Allocation and Wait-For Graphs","question":"During depth-first search, which edge proves the graph has a cycle?","options":["An edge to a node that has not been visited yet","An edge to a node that is already finished","An edge to a node still on the recursion stack","Any edge out of the start node"],"correct":2,"explanation":"A node on the stack (gray) is an ancestor of the current node, so an edge back to it closes a loop. An edge to a finished (black) node only reaches a part of the graph already shown to be cycle-free from there."},{"id":"operating-systems/deadlock-detection#2","route":"/operating-systems/deadlock-detection","section":"operating-systems","subject":"cs-core","title":"Deadlock Detection Visualizer – Resource-Allocation and Wait-For Graphs","question":"Requiring every thread to acquire locks in one global order prevents deadlock by breaking which Coffman condition?","options":["Mutual exclusion","Hold and wait","No preemption","Circular wait"],"correct":3,"explanation":"If every edge of the wait-for graph points from a lower-ranked lock holder to a higher-ranked one, the graph can never loop back. Mutual exclusion, hold-and-wait and no preemption can all still be present."},{"id":"operating-systems/dining-philosophers#0","route":"/operating-systems/dining-philosophers","section":"operating-systems","subject":"cs-core","title":"Dining Philosophers Visualizer – Deadlock and Resource Ordering","question":"Every philosopher picks up their left fork at the same moment. Why can nobody ever eat?","options":["There are not enough forks for anyone","Each holds one fork and waits for the next philosopher's, all the way round — a circular wait","The forks are starving each other","Philosophers must eat in numerical order"],"correct":1,"explanation":"All four Coffman conditions hold: forks are exclusive, everyone holds one while waiting for another, nobody gives one up, and the waits form a cycle P1 → P2 → … → P5 → P1. Break any one and the deadlock disappears."},{"id":"operating-systems/dining-philosophers#1","route":"/operating-systems/dining-philosophers","section":"operating-systems","subject":"cs-core","title":"Dining Philosophers Visualizer – Deadlock and Resource Ordering","question":"Numbering the forks and always picking up the lower-numbered one first breaks which condition?","options":["Mutual exclusion","Hold and wait","No preemption","Circular wait"],"correct":3,"explanation":"Every wait now points from a lower fork to a higher one, so a cycle would need a fork to be both lower and higher than another. In practice it is the last philosopher who flips: they reach for fork 1 first and wait holding nothing, which leaves the cycle open."},{"id":"operating-systems/dining-philosophers#2","route":"/operating-systems/dining-philosophers","section":"operating-systems","subject":"cs-core","title":"Dining Philosophers Visualizer – Deadlock and Resource Ordering","question":"Another classic fix lets at most four philosophers sit at the table at once. Why can that never deadlock?","options":["Four philosophers need fewer than four forks","With four philosophers and five forks, at least one of them can always get both forks","The fifth philosopher eats for everyone","It makes the forks preemptible"],"correct":1,"explanation":"Pigeonhole: four people holding at most one fork each leaves a fifth fork free, and it sits next to someone who already holds one. That philosopher can eat, finish, and release both forks, so the system always makes progress."},{"id":"operating-systems/disk-scheduling#0","route":"/operating-systems/disk-scheduling","section":"operating-systems","subject":"cs-core","title":"Disk Scheduling Visualizer – FCFS, SSTF, SCAN, C-SCAN, LOOK and C-LOOK","question":"Which algorithm can leave a request at the far edge of the disk waiting indefinitely?","options":["FCFS","SSTF","SCAN","C-LOOK"],"correct":1,"explanation":"SSTF always takes the closest request. If new requests keep arriving near the head, a distant one is never the closest and can starve. The sweeping algorithms guarantee the head reaches every cylinder on each pass."},{"id":"operating-systems/disk-scheduling#1","route":"/operating-systems/disk-scheduling","section":"operating-systems","subject":"cs-core","title":"Disk Scheduling Visualizer – FCFS, SSTF, SCAN, C-SCAN, LOOK and C-LOOK","question":"What is the difference between SCAN and LOOK?","options":["LOOK services requests in arrival order","LOOK reverses at the last pending request instead of travelling to the end of the disk","LOOK only moves in one direction","There is no difference; they are two names for the elevator algorithm"],"correct":1,"explanation":"SCAN always runs to cylinder 0 or the last cylinder before turning around, even when nothing is waiting out there. LOOK \"looks\" ahead and turns around as soon as no request remains in its direction, saving that wasted travel."},{"id":"operating-systems/disk-scheduling#2","route":"/operating-systems/disk-scheduling","section":"operating-systems","subject":"cs-core","title":"Disk Scheduling Visualizer – FCFS, SSTF, SCAN, C-SCAN, LOOK and C-LOOK","question":"Why would an OS prefer C-SCAN over SCAN?","options":["It always has a smaller total seek distance","It gives more uniform waiting times by treating the cylinders as a circular list","It does not need to know the head position","It services requests in the order they arrive"],"correct":1,"explanation":"Right after SCAN reverses, the cylinders it just passed are served again soon while the far end waits longest. C-SCAN always sweeps the same way and jumps back, so every cylinder waits about one full sweep — often at the cost of extra head movement."},{"id":"operating-systems/memory-allocation#0","route":"/operating-systems/memory-allocation","section":"operating-systems","subject":"cs-core","title":"Memory Allocation Visualizer – First, Best, Worst and Next Fit","question":"A 30 KB request fails even though 45 KB of memory is free. What is this called?","options":["Internal fragmentation","External fragmentation","Thrashing","A memory leak"],"correct":1,"explanation":"External fragmentation: the free memory exists, but it is split into holes that are each smaller than the request. Internal fragmentation is the opposite problem — space wasted inside an allocated block that is bigger than asked for."},{"id":"operating-systems/memory-allocation#1","route":"/operating-systems/memory-allocation","section":"operating-systems","subject":"cs-core","title":"Memory Allocation Visualizer – First, Best, Worst and Next Fit","question":"What does best fit tend to leave behind?","options":["One very large hole at the end of memory","Many tiny leftover holes that are too small to use","No holes at all, so it never needs compaction","Holes only at the start of memory"],"correct":1,"explanation":"Best fit picks the tightest hole, so the leftover is as small as possible — often a sliver nobody can ever use. Worst fit tries to avoid that by leaving the biggest leftover, but it eats the large holes that big requests need."},{"id":"operating-systems/memory-allocation#2","route":"/operating-systems/memory-allocation","section":"operating-systems","subject":"cs-core","title":"Memory Allocation Visualizer – First, Best, Worst and Next Fit","question":"What must be true for the OS to compact memory?","options":["Processes must be stopped forever","Addresses must be bound at compile time","Processes must be relocatable at run time, because their blocks move","Every hole must be the same size"],"correct":2,"explanation":"Compaction physically moves blocks, so every moved process must have its base address updated — which needs run-time address binding (a relocation or base register). It is also expensive: every moved byte is copied."},{"id":"operating-systems/page-replacement#0","route":"/operating-systems/page-replacement","section":"operating-systems","subject":"cs-core","title":"Page Replacement Visualizer – FIFO, LRU and Optimal","question":"Which of these policies can produce MORE page faults when it is given MORE frames?","options":["LRU","Optimal","FIFO","None of them — more memory never hurts"],"correct":2,"explanation":"Belady's anomaly. LRU and Optimal are stack algorithms: the pages held with f frames are always a subset of those held with f + 1, so adding a frame can only remove faults. FIFO has no such property — on 1,2,3,4,1,2,5,1,2,3,4,5 it faults 9 times with 3 frames and 10 times with 4."},{"id":"operating-systems/page-replacement#1","route":"/operating-systems/page-replacement","section":"operating-systems","subject":"cs-core","title":"Page Replacement Visualizer – FIFO, LRU and Optimal","question":"Why does no real kernel use the Optimal policy?","options":["It is too slow to compute on every fault","It needs to know which pages will be referenced in the future","It suffers from Belady's anomaly","It needs more frames than LRU to work"],"correct":1,"explanation":"Optimal evicts the page whose next use is farthest away, which requires the future reference string. It is used offline as the yardstick: no policy can fault less on the same string."},{"id":"operating-systems/page-replacement#2","route":"/operating-systems/page-replacement","section":"operating-systems","subject":"cs-core","title":"Page Replacement Visualizer – FIFO, LRU and Optimal","question":"Exact LRU needs a timestamp or list update on every memory access. What do kernels use instead?","options":["FIFO, because Belady's anomaly is rare","Random replacement","Approximations such as the clock (second-chance) algorithm driven by a hardware reference bit","Optimal, computed from profiling data"],"correct":2,"explanation":"The MMU sets a reference bit when a page is touched; the clock hand sweeps the frames, clearing bits and evicting the first page whose bit is already clear. That approximates \"not used recently\" at almost no cost per access."},{"id":"operating-systems/producer-consumer#0","route":"/operating-systems/producer-consumer","section":"operating-systems","subject":"cs-core","title":"Producer-Consumer Visualizer – Bounded Buffer with Semaphores","question":"For a buffer of N slots, what do the semaphores empty and full start at?","options":["empty = 0, full = N","empty = N, full = 0","empty = 1, full = 1","Both start at N"],"correct":1,"explanation":"empty counts free slots and full counts filled ones. At the start every slot is free, so empty = N and full = 0. Each put moves one unit from empty to full; each take moves it back."},{"id":"operating-systems/producer-consumer#1","route":"/operating-systems/producer-consumer","section":"operating-systems","subject":"cs-core","title":"Producer-Consumer Visualizer – Bounded Buffer with Semaphores","question":"A consumer calls wait(full) while full = 0. What happens?","options":["full becomes −1 and the consumer reads garbage","The consumer spins in a loop, checking full over and over","The consumer sleeps on full's wait queue until a producer calls signal(full)","The call fails and the consumer must retry later"],"correct":2,"explanation":"A blocking semaphore puts the caller to sleep instead of letting it spin. The next signal(full) hands the item straight to the sleeping consumer and wakes it — no CPU is wasted while the buffer is empty."},{"id":"operating-systems/producer-consumer#2","route":"/operating-systems/producer-consumer","section":"operating-systems","subject":"cs-core","title":"Producer-Consumer Visualizer – Bounded Buffer with Semaphores","question":"A producer calls wait(mutex) before wait(empty), and the buffer is full. What goes wrong?","options":["Nothing — the order of the two waits does not matter","An item is overwritten","Deadlock: the producer sleeps holding the mutex, so no consumer can get in to free a slot","The consumer takes the same item twice"],"correct":2,"explanation":"The producer sleeps on empty while still holding the mutex. Every consumer then blocks on wait(mutex), so nobody ever signals empty. Always wait on the counting semaphore first and take the mutex last."},{"id":"operating-systems/race-conditions#0","route":"/operating-systems/race-conditions","section":"operating-systems","subject":"cs-core","title":"Race Conditions Visualizer – counter++, Interleavings and Mutexes","question":"Two threads each run counter++ once on a shared counter that starts at 0, with no lock. What can the final value be?","options":["Always 2","1 or 2","0, 1 or 2","Anything from 0 to 2, plus garbage"],"correct":1,"explanation":"Each increment is load, add, store. If one thread loads before the other stores, both write the same value and one increment is lost, giving 1. Of the 20 possible interleavings, only the 2 that run one thread entirely before the other give 2."},{"id":"operating-systems/race-conditions#1","route":"/operating-systems/race-conditions","section":"operating-systems","subject":"cs-core","title":"Race Conditions Visualizer – counter++, Interleavings and Mutexes","question":"Now each thread runs counter++ 100 times, still with no lock. What is the smallest final value that is possible?","options":["100","101","2","1"],"correct":2,"explanation":"Surprisingly, 2. T1 loads 0 and stalls; T2 does 99 increments; T1 stores 1, wiping them out; T2 loads 1 and stalls; T1 finishes its other 99; T2 stores 2. Unsynchronised code is not \"slightly off\" — it can be arbitrarily wrong."},{"id":"operating-systems/race-conditions#2","route":"/operating-systems/race-conditions","section":"operating-systems","subject":"cs-core","title":"Race Conditions Visualizer – counter++, Interleavings and Mutexes","question":"What does wrapping counter++ in lock() / unlock() actually guarantee?","options":["T1 always runs before T2","The load, add and store of one thread never interleave with another thread's","The threads run in parallel on different cores","counter is cached in a register for speed"],"correct":1,"explanation":"Mutual exclusion: at most one thread is inside the critical section, so each read-modify-write completes before another starts. It says nothing about which thread goes first — only that they do not overlap."},{"id":"operating-systems/round-robin-scheduling#0","route":"/operating-systems/round-robin-scheduling","section":"operating-systems","subject":"cs-core","title":"Round Robin Scheduling Visualizer – Time Quantum and Context Switches","question":"What does Round Robin become if the time quantum is larger than every CPU burst?","options":["Shortest Job First","First-Come, First-Served","Priority scheduling","It stops preempting and deadlocks"],"correct":1,"explanation":"If no process ever uses up its quantum, nothing is ever preempted: each runs to completion in the order it reached the queue. That is exactly FCFS."},{"id":"operating-systems/round-robin-scheduling#1","route":"/operating-systems/round-robin-scheduling","section":"operating-systems","subject":"cs-core","title":"Round Robin Scheduling Visualizer – Time Quantum and Context Switches","question":"Shrinking the quantum from 4 to 1 on the same workload mostly…","options":["Lowers response time but adds context switches","Lowers both response time and context switches","Raises response time and removes context switches","Has no effect, because total CPU work is unchanged"],"correct":0,"explanation":"A small quantum lets every waiting process get its first slice sooner, so response time drops. The price is a switch at almost every tick, and each switch costs real time saving and loading registers and refilling caches."},{"id":"operating-systems/round-robin-scheduling#2","route":"/operating-systems/round-robin-scheduling","section":"operating-systems","subject":"cs-core","title":"Round Robin Scheduling Visualizer – Time Quantum and Context Switches","question":"A common rule of thumb for choosing the quantum is that it should be…","options":["Exactly one clock tick","Equal to the longest burst in the system","Longer than about 80% of CPU bursts, and much longer than a context switch","Shorter than a context switch, so switching dominates"],"correct":2,"explanation":"If most bursts finish within one quantum, short interactive jobs complete without being preempted, while long CPU-bound jobs still share fairly. And the quantum must dwarf the switch cost, or the CPU spends its time switching rather than working."},{"id":"recursion/factorial#0","route":"/recursion/factorial","section":"recursion","subject":"dsa","title":"Factorial Recursion Visualizer – Recursive Call Stack Animation","question":"What is the base case of factorial recursion?","options":["factorial(0) = 0","factorial(1) = 1 (recursion stops here)","factorial(n) = n","factorial(2) = 2"],"correct":1,"explanation":"factorial(1) = 1 is the base case. Without it the function would call itself forever. factorial(0) = 1 also works as a base case."},{"id":"recursion/factorial#1","route":"/recursion/factorial","section":"recursion","subject":"dsa","title":"Factorial Recursion Visualizer – Recursive Call Stack Animation","question":"How many recursive calls does factorial(5) make?","options":["4 calls","5 calls","10 calls","25 calls"],"correct":1,"explanation":"factorial(5) → factorial(4) → factorial(3) → factorial(2) → factorial(1) — exactly 5 calls, one per integer from n down to 1."},{"id":"recursion/factorial#2","route":"/recursion/factorial","section":"recursion","subject":"dsa","title":"Factorial Recursion Visualizer – Recursive Call Stack Animation","question":"When are the multiplication results computed?","options":["During the forward (calling) phase","During the backward (returning) phase","Simultaneously with each call","Only at the very end"],"correct":1,"explanation":"Multiplications happen on the way back up. Each call waits for factorial(n-1) to return before computing n × result."},{"id":"recursion/fibonacci-sequence#0","route":"/recursion/fibonacci-sequence","section":"recursion","subject":"dsa","title":"Fibonacci Sequence Recursion Visualizer – Recursive Tree Animation","question":"Why is naive Fibonacci O(2^n) time complexity?","options":["It uses nested loops internally","Each call spawns two more calls, creating an exponential tree of redundant computations","It allocates a new array for each call","The Fibonacci numbers grow exponentially"],"correct":1,"explanation":"fib(n) calls fib(n-1) and fib(n-2). Each of those spawns two more calls. The call tree doubles at each level, making total calls roughly 2^n."},{"id":"recursion/fibonacci-sequence#1","route":"/recursion/fibonacci-sequence","section":"recursion","subject":"dsa","title":"Fibonacci Sequence Recursion Visualizer – Recursive Tree Animation","question":"What does memoization cache in the Fibonacci algorithm?","options":["The entire call stack at each step","Previously computed fib(k) values so they never get recomputed","Only the final answer","The path taken through the call tree"],"correct":1,"explanation":"Memoization stores fib(0), fib(1), fib(2)... as they're computed. Any future call for a cached value returns instantly — turning O(2^n) into O(n)."},{"id":"recursion/fibonacci-sequence#2","route":"/recursion/fibonacci-sequence","section":"recursion","subject":"dsa","title":"Fibonacci Sequence Recursion Visualizer – Recursive Tree Animation","question":"How many unique calls does memoized fib(n) make?","options":["2^n calls — same as naive","n+1 calls — one per unique value 0 through n","log(n) calls","n² calls"],"correct":1,"explanation":"Memoized fib computes each value fib(0) through fib(n) exactly once — n+1 unique calls — regardless of how many times each would be needed naively."},{"id":"recursion/maze-solver#0","route":"/recursion/maze-solver","section":"recursion","subject":"dsa","title":"Maze Solver Visualizer – Recursive Backtracking Animation","question":"What does the maze solver do when it hits a dead end?","options":["It restarts from the beginning","It marks the cell as a wall and tries a different route","It unmarks the cell as visited and removes it from the path (backtrack)","It signals that the maze has no solution"],"correct":2,"explanation":"Backtracking sets visited[row][col] = false and pops the cell from path. This allows the algorithm to try different directions when revisiting the parent cell."},{"id":"recursion/maze-solver#1","route":"/recursion/maze-solver","section":"recursion","subject":"dsa","title":"Maze Solver Visualizer – Recursive Backtracking Animation","question":"Why is a 'visited' array necessary in recursive maze solving?","options":["To count the total number of steps taken","To prevent infinite loops — without it we could revisit cells endlessly","To store the final solution path","To mark walls in the maze"],"correct":1,"explanation":"Without tracking visited cells, the recursive solver could bounce back and forth between adjacent cells forever. The visited array ensures each cell is explored at most once."},{"id":"recursion/maze-solver#2","route":"/recursion/maze-solver","section":"recursion","subject":"dsa","title":"Maze Solver Visualizer – Recursive Backtracking Animation","question":"In what order does the default maze solver try directions?","options":["Up, left, right, down","Random order each time","Toward the goal first","Right, down, left, up"],"correct":3,"explanation":"The implementation tries directions in order: right (0,+1), down (+1,0), left (0,-1), up (-1,0). This determines the specific path found, though any valid path exists if the maze is solvable."},{"id":"recursion/n-queens#0","route":"/recursion/n-queens","section":"recursion","subject":"dsa","title":"N-Queens Problem Visualizer – Backtracking Animation","question":"What does backtracking do in N-Queens when a queen can't be placed?","options":["It restarts the entire algorithm from scratch","It places a queen anyway and marks conflicts","It removes the most recently placed queen and tries the next column","It swaps two queens to resolve the conflict"],"correct":2,"explanation":"Backtracking removes the last placed queen (board[row] = -1) and tries the next column. If no column works in that row, it backtracks further to the previous row."},{"id":"recursion/n-queens#1","route":"/recursion/n-queens","section":"recursion","subject":"dsa","title":"N-Queens Problem Visualizer – Backtracking Animation","question":"How many solutions does the 8-Queens problem have?","options":["8 solutions","24 solutions","64 solutions","92 solutions"],"correct":3,"explanation":"The 8-Queens problem has exactly 92 distinct solutions. The 4×4 board has 2 solutions, 5×5 has 10, 6×6 has 4, 7×7 has 40."},{"id":"recursion/n-queens#2","route":"/recursion/n-queens","section":"recursion","subject":"dsa","title":"N-Queens Problem Visualizer – Backtracking Animation","question":"Why do we check only columns and diagonals (not rows) for queen attacks?","options":["Queens cannot attack in rows","We place exactly one queen per row by design — row conflicts are impossible","Row checking would make the algorithm too slow","Diagonals cover row attacks implicitly"],"correct":1,"explanation":"The algorithm places queens row by row — one per row. Since only one queen ever occupies each row, row conflicts are structurally impossible. We only need to check columns and diagonals."},{"id":"recursion/permutations#0","route":"/recursion/permutations","section":"recursion","subject":"dsa","title":"Permutations Visualizer – Swap-Based Recursion Tree","question":"How many permutations does an array of n distinct elements have?","options":["2^n","n²","n!","n·(n-1)"],"correct":2,"explanation":"n! (n factorial). For position 0 there are n choices, for position 1 there are n-1 remaining choices, and so on: n × (n-1) × … × 1 = n!. For [1,2,3]: 3! = 6 permutations."},{"id":"recursion/permutations#1","route":"/recursion/permutations","section":"recursion","subject":"dsa","title":"Permutations Visualizer – Swap-Based Recursion Tree","question":"In swap-based backtracking, why do we swap back after recursing?","options":["To find duplicates in the array","To restore the array to its original order before trying the next choice","To sort the array at each level","Because the swap was incorrect"],"correct":1,"explanation":"We swap back (backtrack) to restore the array to the state before the choice was made. This lets the next loop iteration try a different element in the current position without interference from earlier choices."},{"id":"recursion/permutations#2","route":"/recursion/permutations","section":"recursion","subject":"dsa","title":"Permutations Visualizer – Swap-Based Recursion Tree","question":"At recursion depth d (0-indexed), how many elements are still 'free' to be placed?","options":["d elements","n - d elements","n elements","d + 1 elements"],"correct":1,"explanation":"At depth d, positions 0..d-1 are already fixed (locked in by previous swaps). Only positions d..n-1 remain free. So there are n - d elements still available, matching the number of recursive calls made at that level."},{"id":"recursion/string-reversal#0","route":"/recursion/string-reversal","section":"recursion","subject":"dsa","title":"String Reversal Recursion Visualizer – Recursive Stack Animation","question":"How does recursive string reversal build its result?","options":["It reverses characters during the forward (calling) phase","reverse(rest) + first_char — result builds on the unwind phase","It swaps adjacent characters repeatedly","It uses an extra array to store characters"],"correct":1,"explanation":"The reversed result is built on the way back: reverse(s[1:]) returns first, then s[0] is appended. The result is constructed bottom-up as the stack unwinds."},{"id":"recursion/string-reversal#1","route":"/recursion/string-reversal","section":"recursion","subject":"dsa","title":"String Reversal Recursion Visualizer – Recursive Stack Animation","question":"When does the recursion stop (base case)?","options":["When the string has been fully reversed","When the call stack overflows","When the string is empty or has 1 character","When all characters have been visited once"],"correct":2,"explanation":"A string of length 0 or 1 is its own reverse — that's the base case. Every recursive call passes a shorter substring until this is reached."},{"id":"recursion/string-reversal#2","route":"/recursion/string-reversal","section":"recursion","subject":"dsa","title":"String Reversal Recursion Visualizer – Recursive Stack Animation","question":"For a 5-character string, how deep does the call stack go?","options":["4 levels deep","5 levels deep (one per character)","10 levels deep","25 levels deep"],"correct":1,"explanation":"Each character creates one stack frame: reverse(HELLO) → reverse(ELLO) → reverse(LLO) → reverse(LO) → reverse(O). That is 5 levels — one per character."},{"id":"recursion/subsets-power-set#0","route":"/recursion/subsets-power-set","section":"recursion","subject":"dsa","title":"Subsets (Power Set) Visualizer – Binary Decision Tree","question":"How many subsets does a set of n elements have?","options":["n subsets","n² subsets","2^n subsets","n! subsets"],"correct":2,"explanation":"Every element independently contributes a binary choice: include or exclude. With n independent binary choices, there are 2^n total subsets. For 3 elements: 2³ = 8 subsets."},{"id":"recursion/subsets-power-set#1","route":"/recursion/subsets-power-set","section":"recursion","subject":"dsa","title":"Subsets (Power Set) Visualizer – Binary Decision Tree","question":"In the binary decision tree, what does each level represent?","options":["A comparison between two elements","An include/exclude decision for one element","A complete subset being built","A backtrack step removing an element"],"correct":1,"explanation":"Each level in the binary decision tree corresponds to one element. At level k we decide whether to include or exclude the k-th element. The left branch = exclude, right branch = include."},{"id":"recursion/subsets-power-set#2","route":"/recursion/subsets-power-set","section":"recursion","subject":"dsa","title":"Subsets (Power Set) Visualizer – Binary Decision Tree","question":"What is the time complexity of generating all subsets?","options":["O(n log n)","O(n²)","O(2^n)","O(n · 2^n)"],"correct":3,"explanation":"There are 2^n subsets, and we spend O(n) work per subset (copying it into the result). So the overall time complexity is O(n · 2^n). Generating each subset takes O(n) time."},{"id":"recursion/sudoku-solver#0","route":"/recursion/sudoku-solver","section":"recursion","subject":"dsa","title":"Sudoku Solver Visualizer – Backtracking Grid","question":"In Sudoku backtracking, what three regions must a placed digit NOT repeat in?","options":["Its row, its column, and its 3×3 box","Its row, its diagonal, and its 3×3 box","Its column, its diagonal, and its row","Its 3×3 box, the center row, and the center column"],"correct":0,"explanation":"A valid Sudoku digit must be unique within its row (9 cells), its column (9 cells), and its 3×3 sub-grid (9 cells). The diagonal has no special constraint in standard Sudoku."},{"id":"recursion/sudoku-solver#1","route":"/recursion/sudoku-solver","section":"recursion","subject":"dsa","title":"Sudoku Solver Visualizer – Backtracking Grid","question":"When the backtracking solver tries digit 1–9 for a cell and none are valid, what happens?","options":["It marks the cell as unsolvable and moves on","It picks the digit that conflicts the least","It returns false, causing the caller to undo its last placement","It restarts the entire solve from scratch"],"correct":2,"explanation":"If no digit (1–9) is valid for the current cell, the function returns false. The calling frame then removes the digit it last placed, restores the cell to 0, and tries the next candidate — classic backtracking."},{"id":"recursion/sudoku-solver#2","route":"/recursion/sudoku-solver","section":"recursion","subject":"dsa","title":"Sudoku Solver Visualizer – Backtracking Grid","question":"Why does the recursive solver skip cells where grid[row][col] ≠ 0?","options":["Those cells were already solved in a previous run","Skipping pre-filled cells makes the algorithm faster by luck","Those are the given (clue) cells that cannot be changed","Zero means the cell is invalid and must be avoided"],"correct":2,"explanation":"Non-zero cells are the puzzle's given clues — they are fixed constants provided by the puzzle. The solver only needs to fill empty cells (value 0). Skipping non-zero cells prevents overwriting the clues."},{"id":"recursion/tower-of-hanoi#0","route":"/recursion/tower-of-hanoi","section":"recursion","subject":"dsa","title":"Tower of Hanoi Visualizer – Recursive Disk Move Animation","question":"What are the 3 recursive steps of Tower of Hanoi (n disks, A→C using B)?","options":["Move all disks to B, then move all to C","Move 1 disk then repeat n times","Move n-1 disks A→B, move largest A→C, move n-1 disks B→C","Move disks one at a time in order from A to C"],"correct":2,"explanation":"The elegant recursion: (1) move n-1 disks out of the way to auxiliary, (2) move the largest disk to destination, (3) move the n-1 disks from auxiliary to destination."},{"id":"recursion/tower-of-hanoi#1","route":"/recursion/tower-of-hanoi","section":"recursion","subject":"dsa","title":"Tower of Hanoi Visualizer – Recursive Disk Move Animation","question":"How many moves are needed to solve the n-disk Tower of Hanoi optimally?","options":["n moves","n² moves","2^n - 1 moves","n! moves"],"correct":2,"explanation":"The minimum is always 2^n - 1. For 3 disks: 7 moves. For 4 disks: 15. For 64 disks: 18.4 quintillion — it would take 584 billion years at one move per second!"},{"id":"recursion/tower-of-hanoi#2","route":"/recursion/tower-of-hanoi","section":"recursion","subject":"dsa","title":"Tower of Hanoi Visualizer – Recursive Disk Move Animation","question":"What is the recursion depth for the n-disk Tower of Hanoi?","options":["2^n - 1 levels deep","n levels deep","n² levels deep","log(n) levels deep"],"correct":1,"explanation":"The recursion depth is exactly n — one level per disk. Space complexity is O(n) because the call stack never exceeds n frames at once."},{"id":"searching/binary-search#0","route":"/searching/binary-search","section":"searching","subject":"dsa","title":"Binary Search Visualizer – O(log n) Search Animation","question":"What precondition is required for binary search to work correctly?","options":["The array must have an even number of elements","The array must be sorted","The array must contain unique elements","The array must be stored in a hash table"],"correct":1,"explanation":"Binary search relies on the sorted order to decide which half to keep. If the array is unsorted, comparing with the middle element gives no information about where the target is — the algorithm would be incorrect."},{"id":"searching/binary-search#1","route":"/searching/binary-search","section":"searching","subject":"dsa","title":"Binary Search Visualizer – O(log n) Search Animation","question":"How does binary search reduce the search space on each step?","options":["It eliminates one element at a time","It eliminates all elements smaller than the target","It eliminates roughly half the remaining elements","It sorts the remaining elements before the next step"],"correct":2,"explanation":"Each comparison with the midpoint eliminates either the left half or the right half of the current search range. After k steps, at most n / 2^k elements remain — this is why the time complexity is O(log n)."},{"id":"searching/binary-search#2","route":"/searching/binary-search","section":"searching","subject":"dsa","title":"Binary Search Visualizer – O(log n) Search Animation","question":"What is the time complexity of binary search?","options":["O(n)","O(n log n)","O(log n)","O(1)"],"correct":2,"explanation":"Binary search halves the search space each step. Starting with n elements, after log₂n halvings only 1 remains. Total comparisons: O(log n). It's O(1) best case (target is the first midpoint checked)."},{"id":"searching/block-search#0","route":"/searching/block-search","section":"searching","subject":"dsa","title":"Block Search Visualizer – Block-Based Search Animation","question":"What is the optimal block size used in block search?","options":["n/2","log n","sqrt(n)","n/3"],"correct":2,"explanation":"Block size sqrt(n) minimizes total comparisons. The block endpoint scan takes at most sqrt(n) steps, and the linear scan within the block takes at most sqrt(n) steps — total O(sqrt(n))."},{"id":"searching/block-search#1","route":"/searching/block-search","section":"searching","subject":"dsa","title":"Block Search Visualizer – Block-Based Search Animation","question":"What are the two phases of block search?","options":["Sort phase, then search phase","Block endpoint scan, then linear search within the found block","Exponential scan, then binary search","Hashing phase, then collision resolution"],"correct":1,"explanation":"Phase 1: scan block endpoints (arr[sqrt(n)-1], arr[2*sqrt(n)-1], ...) to find which block contains the target. Phase 2: linear scan within that block to find the exact position."},{"id":"searching/block-search#2","route":"/searching/block-search","section":"searching","subject":"dsa","title":"Block Search Visualizer – Block-Based Search Animation","question":"What is another common name for block search?","options":["Binary search","Jump search","Heap search","Interpolation search"],"correct":1,"explanation":"Block search is also called jump search because it 'jumps' ahead by block-sized steps. Both names refer to the same algorithm: fixed-size block endpoint scanning followed by linear search."},{"id":"searching/exponential-search#0","route":"/searching/exponential-search","section":"searching","subject":"dsa","title":"Exponential Search Visualizer – Unbounded Array Search","question":"What does the first phase (exponential scan) of exponential search accomplish?","options":["It finds the target directly","It establishes a range [bound/2, bound] that contains the target","It sorts the array","It counts the elements"],"correct":1,"explanation":"The exponential phase doubles the bound (1, 2, 4, 8, 16...) until arr[bound] >= target. This identifies a range [bound/2, bound] where the target must be, without knowing the array size upfront."},{"id":"searching/exponential-search#1","route":"/searching/exponential-search","section":"searching","subject":"dsa","title":"Exponential Search Visualizer – Unbounded Array Search","question":"After finding the range, exponential search applies which algorithm?","options":["Linear search","Jump search","Binary search","Interpolation search"],"correct":2,"explanation":"Binary search is applied on the identified range [bound/2, min(bound, n-1)]. This gives O(log n) total time since the exponential phase also takes O(log n) doublings."},{"id":"searching/exponential-search#2","route":"/searching/exponential-search","section":"searching","subject":"dsa","title":"Exponential Search Visualizer – Unbounded Array Search","question":"Why is exponential search especially useful for unbounded or infinite arrays?","options":["It never accesses out-of-bounds indices","It finds a finite range before searching, so array size is not needed upfront","It works without sorting","It uses O(n) extra space for bookkeeping"],"correct":1,"explanation":"Exponential search only needs to find a bound — it works even if you don't know how large the array is. Once the bound exceeds the target, binary search is applied within a known range."},{"id":"searching/fibonacci-search#0","route":"/searching/fibonacci-search","section":"searching","subject":"dsa","title":"Fibonacci Search Visualizer – Fibonacci-Based Search Animation","question":"What is the key advantage of Fibonacci search over binary search in terms of operations used?","options":["It finds the target in fewer comparisons","It uses addition/subtraction instead of division to compute the probe index","It works on unsorted arrays","It uses less memory"],"correct":1,"explanation":"Fibonacci search computes the probe index using offset + fibM2 (addition only). Binary search uses (left+right)//2 (division). On older hardware without a hardware divider, avoiding division gave a real performance benefit."},{"id":"searching/fibonacci-search#1","route":"/searching/fibonacci-search","section":"searching","subject":"dsa","title":"Fibonacci Search Visualizer – Fibonacci-Based Search Animation","question":"What is the time complexity of Fibonacci search?","options":["O(1)","O(log n)","O(sqrt(n))","O(n)"],"correct":1,"explanation":"Fibonacci search is O(log n) — the Fibonacci numbers grow exponentially, so the algorithm eliminates a constant fraction of the remaining search space each step, just like binary search."},{"id":"searching/fibonacci-search#2","route":"/searching/fibonacci-search","section":"searching","subject":"dsa","title":"Fibonacci Search Visualizer – Fibonacci-Based Search Animation","question":"After each comparison in Fibonacci search, the eliminated portion is approximately what fraction of the remaining space?","options":["1/2","1/3","1/phi^2 approx 38% or 62%","1/4"],"correct":2,"explanation":"Because fibM2/fibM = 1/phi^2 = 0.382 and fibM1/fibM = 1/phi = 0.618, Fibonacci search eliminates roughly 38% or 62% of the remaining range per step (depending on comparison result), compared to binary search's exact 50%."},{"id":"searching/interpolation-search#0","route":"/searching/interpolation-search","section":"searching","subject":"dsa","title":"Interpolation Search Visualizer – Probe Position Animation","question":"What type of data gives interpolation search its best-case O(log log n) performance?","options":["Any sorted array","Uniformly distributed sorted data","Arrays with all distinct elements","Arrays sorted in reverse order"],"correct":1,"explanation":"When values are uniformly distributed (evenly spaced), the probe formula accurately estimates the target's position. The estimated position is close to actual, so the range shrinks doubly logarithmically — O(log log n). Non-uniform data degrades performance to O(n) in the worst case."},{"id":"searching/interpolation-search#1","route":"/searching/interpolation-search","section":"searching","subject":"dsa","title":"Interpolation Search Visualizer – Probe Position Animation","question":"What is the worst-case time complexity of interpolation search?","options":["O(log n)","O(log log n)","O(√n)","O(n)"],"correct":3,"explanation":"If data is highly non-uniform (e.g., exponentially distributed), the probe formula gives terrible estimates and the search degrades to O(n) — similar to linear search. This is why interpolation search is only preferred when data is known to be uniformly distributed."},{"id":"searching/interpolation-search#2","route":"/searching/interpolation-search","section":"searching","subject":"dsa","title":"Interpolation Search Visualizer – Probe Position Animation","question":"The probe position formula pos = low + (target - arr[low]) × (high - low) / (arr[high] - arr[low]) works like:","options":["The mid formula in binary search","Telephone directory lookup — guess position by value proportion","A random hash function","The jump size formula in jump search"],"correct":1,"explanation":"The formula is linear interpolation: it estimates where the target lies between arr[low] and arr[high] proportionally by value. If target is 70% of the way from arr[low] to arr[high] by value, the probe is at 70% of the index range. This is exactly how you'd search a phone book by last name."},{"id":"searching/jump-search#0","route":"/searching/jump-search","section":"searching","subject":"dsa","title":"Jump Search Visualizer – Block Step Search Animation","question":"What is the optimal block/jump size for jump search on an array of size n?","options":["n / 2","log n","√n","n / 3"],"correct":2,"explanation":"Block size √n minimises total comparisons. Phase 1 takes at most √n jumps; phase 2 takes at most √n steps. Total: O(√n). Mathematically, minimising n/k + k (block scan + linear scan) gives k = √n as the optimal point."},{"id":"searching/jump-search#1","route":"/searching/jump-search","section":"searching","subject":"dsa","title":"Jump Search Visualizer – Block Step Search Animation","question":"After finding the right block in phase 1, what technique does phase 2 use?","options":["Another jump search","Binary search","Linear search","Interpolation"],"correct":2,"explanation":"Phase 2 uses linear search within the identified block. Since the block has at most √n elements, the linear scan is O(√n). Combined with O(√n) block scan, total complexity is O(√n)."},{"id":"searching/jump-search#2","route":"/searching/jump-search","section":"searching","subject":"dsa","title":"Jump Search Visualizer – Block Step Search Animation","question":"Jump search requires the input array to be:","options":["Unsorted","Sorted","Sorted with no duplicates","Stored as a linked list"],"correct":1,"explanation":"Jump search requires a sorted array. It compares the target with block endpoints (arr[step-1], arr[2*step-1],...) to decide which block to search. Without sorted order, endpoint comparisons give no information about where the target lies."},{"id":"searching/linear-search#0","route":"/searching/linear-search","section":"searching","subject":"dsa","title":"Linear Search Visualizer – Sequential Search Animation","question":"What is the time complexity of linear search in the worst case (target not present)?","options":["O(1)","O(log n)","O(n)","O(n²)"],"correct":2,"explanation":"Linear search must check every element when the target is absent, making n comparisons. Worst case is O(n). Best case is O(1) when the target is the first element."},{"id":"searching/linear-search#1","route":"/searching/linear-search","section":"searching","subject":"dsa","title":"Linear Search Visualizer – Sequential Search Animation","question":"What key advantage does linear search have over binary search?","options":["It is always faster","It requires O(n) extra space","It works on unsorted arrays","It uses divide and conquer"],"correct":2,"explanation":"Linear search makes no assumption about element ordering — it works on any array (sorted or not), any data structure with sequential access (linked lists), and can find all occurrences in a single pass."},{"id":"searching/linear-search#2","route":"/searching/linear-search","section":"searching","subject":"dsa","title":"Linear Search Visualizer – Sequential Search Animation","question":"In a linear search that finds all occurrences (not just the first), how many comparisons are made for an array of n elements?","options":["Exactly 1","At most log n","Exactly n","It depends on the target"],"correct":2,"explanation":"To guarantee finding all occurrences, the full array must be scanned from start to end. Exactly n comparisons are always made regardless of the target's presence — making average and worst case both O(n)."},{"id":"searching/ternary-search#0","route":"/searching/ternary-search","section":"searching","subject":"dsa","title":"Ternary Search Visualizer – Three-Way Divide Search Animation","question":"Ternary search divides the search space into how many parts each iteration?","options":["2","3","4","log n"],"correct":1,"explanation":"Ternary search uses two midpoints (mid1 and mid2) to divide the range [left, right] into three equal thirds. Depending on the comparisons, one third is eliminated each iteration."},{"id":"searching/ternary-search#1","route":"/searching/ternary-search","section":"searching","subject":"dsa","title":"Ternary Search Visualizer – Three-Way Divide Search Animation","question":"How many element comparisons does ternary search make per iteration?","options":["1","2","3","log n"],"correct":1,"explanation":"Ternary search compares the target against arr[mid1] AND arr[mid2] each iteration — 2 comparisons per step. Binary search makes only 1 comparison per step."},{"id":"searching/ternary-search#2","route":"/searching/ternary-search","section":"searching","subject":"dsa","title":"Ternary Search Visualizer – Three-Way Divide Search Animation","question":"Despite dividing into 3 parts per step, ternary search is not faster than binary search. Why?","options":["Arrays must be much larger for it to matter","2 comparisons x log3(n) steps is approximately 1.26 x log2(n), worse than 1 x log2(n) for binary","Ternary search has more memory overhead","Ternary search cannot find elements at odd indices"],"correct":1,"explanation":"Total comparisons: ternary = 2 x log3(n) = 2 x 0.631 x log2(n) = 1.26 x log2(n), binary = 1 x log2(n). Ternary search actually makes MORE total comparisons despite halving fewer times. Binary search wins in practice."},{"id":"sorting/bubble-sort#0","route":"/sorting/bubble-sort","section":"sorting","subject":"dsa","title":"Bubble Sort Visualizer – Step-by-Step Animation","question":"What is Bubble Sort's time complexity in the worst case?","options":["O(n)","O(n log n)","O(n²)","O(log n)"],"correct":2,"explanation":"Bubble Sort compares every pair of adjacent elements in each pass. With n-1 passes and up to n-1 comparisons per pass, worst case is O(n²)."},{"id":"sorting/bubble-sort#1","route":"/sorting/bubble-sort","section":"sorting","subject":"dsa","title":"Bubble Sort Visualizer – Step-by-Step Animation","question":"When does Bubble Sort achieve its best case O(n) performance?","options":["When the array is reverse sorted","When the array is already sorted","When the array has all equal elements","When n is very small"],"correct":1,"explanation":"With the swapped-flag optimization, if no swaps occur in the first pass the algorithm terminates early — only one pass needed for an already-sorted array."},{"id":"sorting/bubble-sort#2","route":"/sorting/bubble-sort","section":"sorting","subject":"dsa","title":"Bubble Sort Visualizer – Step-by-Step Animation","question":"Is Bubble Sort a stable sorting algorithm?","options":["No, equal elements can swap positions","Yes, equal elements maintain their relative order","It depends on the implementation","Only for numeric data"],"correct":1,"explanation":"Bubble Sort only swaps when arr[j] > arr[j+1], so equal elements are never swapped, preserving their relative order — making it stable."},{"id":"sorting/bucket-sort#0","route":"/sorting/bucket-sort","section":"sorting","subject":"dsa","title":"Bucket Sort Visualizer – Distribution Sort Animation","question":"When does Bucket Sort achieve its best O(n + k) performance?","options":["When the array is already sorted","When data is uniformly distributed across the value range","When all elements are the same","When there are many duplicate values"],"correct":1,"explanation":"Bucket Sort performs best when input is uniformly distributed — each bucket receives roughly the same number of elements, making the per-bucket sorting trivially fast."},{"id":"sorting/bucket-sort#1","route":"/sorting/bucket-sort","section":"sorting","subject":"dsa","title":"Bucket Sort Visualizer – Distribution Sort Animation","question":"What sorting algorithm is typically used to sort elements within individual buckets?","options":["Merge Sort","Quick Sort","Insertion Sort","Heap Sort"],"correct":2,"explanation":"Insertion Sort is commonly used for individual buckets because buckets typically contain few elements, and Insertion Sort is efficient for small arrays."},{"id":"sorting/bucket-sort#2","route":"/sorting/bucket-sort","section":"sorting","subject":"dsa","title":"Bucket Sort Visualizer – Distribution Sort Animation","question":"What is Bucket Sort's worst case time complexity?","options":["O(n log n)","O(n + k)","O(n²)","O(k²)"],"correct":2,"explanation":"In the worst case, all elements fall into the same bucket. Sorting that single bucket with Insertion Sort takes O(n²), making the overall worst case O(n²)."},{"id":"sorting/heap-sort#0","route":"/sorting/heap-sort","section":"sorting","subject":"dsa","title":"Heap Sort Visualizer – Binary Heap Sort Animation","question":"What data structure does Heap Sort use internally?","options":["Binary Search Tree","Binary Max Heap","Hash Table","Linked List"],"correct":1,"explanation":"Heap Sort uses a binary max heap where the largest element is always at the root. This property is used to repeatedly extract the maximum and build the sorted array."},{"id":"sorting/heap-sort#1","route":"/sorting/heap-sort","section":"sorting","subject":"dsa","title":"Heap Sort Visualizer – Binary Heap Sort Animation","question":"What is Heap Sort's space complexity?","options":["O(n)","O(log n)","O(n log n)","O(1)"],"correct":3,"explanation":"Heap Sort is in-place — it builds the heap within the original array and doesn't require auxiliary space proportional to the input size, giving O(1) space complexity."},{"id":"sorting/heap-sort#2","route":"/sorting/heap-sort","section":"sorting","subject":"dsa","title":"Heap Sort Visualizer – Binary Heap Sort Animation","question":"What are the two main phases of Heap Sort?","options":["Compare and Swap","Divide and Merge","Build Max Heap and Extract Elements","Partition and Recurse"],"correct":2,"explanation":"Phase 1: Build a max heap from the input array. Phase 2: Repeatedly extract the maximum (root) and place it at the end, reducing the heap size each time."},{"id":"sorting/insertion-sort#0","route":"/sorting/insertion-sort","section":"sorting","subject":"dsa","title":"Insertion Sort Visualizer – Step-by-Step Animation","question":"What makes Insertion Sort 'adaptive'?","options":["It changes its algorithm based on input size","It performs fewer operations when input is nearly sorted","It adapts to available memory","It chooses different pivots"],"correct":1,"explanation":"Insertion Sort is adaptive because it detects when elements are already in order. For a nearly-sorted array it runs close to O(n), making it one of the fastest algorithms for that case."},{"id":"sorting/insertion-sort#1","route":"/sorting/insertion-sort","section":"sorting","subject":"dsa","title":"Insertion Sort Visualizer – Step-by-Step Animation","question":"What is Insertion Sort's best case time complexity?","options":["O(n²)","O(n log n)","O(n)","O(1)"],"correct":2,"explanation":"When the array is already sorted, each element only requires one comparison to confirm it's in the right place. This results in O(n) — linear time."},{"id":"sorting/insertion-sort#2","route":"/sorting/insertion-sort","section":"sorting","subject":"dsa","title":"Insertion Sort Visualizer – Step-by-Step Animation","question":"Which real-world sorting scenario is most similar to Insertion Sort?","options":["Organizing files by date","Sorting playing cards in your hand","Counting distinct items","Finding the median"],"correct":1,"explanation":"Insertion Sort mimics how humans naturally sort playing cards: you pick up each card and insert it into the correct position among the already-sorted cards in your hand."},{"id":"sorting/merge-sort#0","route":"/sorting/merge-sort","section":"sorting","subject":"dsa","title":"Merge Sort Visualizer – Divide & Conquer Animation","question":"What is Merge Sort's space complexity?","options":["O(1)","O(log n)","O(n)","O(n log n)"],"correct":2,"explanation":"Merge Sort requires O(n) auxiliary space to hold the temporary subarrays during the merge step, making it not in-place unlike Heap or Quick Sort."},{"id":"sorting/merge-sort#1","route":"/sorting/merge-sort","section":"sorting","subject":"dsa","title":"Merge Sort Visualizer – Divide & Conquer Animation","question":"What algorithmic paradigm does Merge Sort use?","options":["Greedy","Dynamic Programming","Divide and Conquer","Backtracking"],"correct":2,"explanation":"Merge Sort uses divide-and-conquer: divide the array in half, recursively sort each half, then merge the two sorted halves back together."},{"id":"sorting/merge-sort#2","route":"/sorting/merge-sort","section":"sorting","subject":"dsa","title":"Merge Sort Visualizer – Divide & Conquer Animation","question":"Is Merge Sort stable?","options":["No","Yes, always","Only for small inputs","Only with extra memory"],"correct":1,"explanation":"Merge Sort is stable because the merge step preserves the relative order of equal elements — when two elements are equal it takes from the left subarray first."},{"id":"sorting/quick-sort#0","route":"/sorting/quick-sort","section":"sorting","subject":"dsa","title":"Quick Sort Visualizer – Pivot & Partition Animation","question":"What is Quick Sort's average case time complexity?","options":["O(n)","O(n²)","O(n log n)","O(log n)"],"correct":2,"explanation":"On average, Quick Sort's partitioning splits the array into two roughly equal halves each time, resulting in O(n log n) comparisons."},{"id":"sorting/quick-sort#1","route":"/sorting/quick-sort","section":"sorting","subject":"dsa","title":"Quick Sort Visualizer – Pivot & Partition Animation","question":"When does Quick Sort degrade to O(n²)?","options":["When data is uniformly distributed","When the pivot is always the median","When the pivot is always the smallest or largest element","When the array has duplicates"],"correct":2,"explanation":"If the pivot is always the minimum or maximum element (e.g., already sorted array with last-element pivot), partitioning creates one subarray of size n-1 and one empty — leading to O(n²)."},{"id":"sorting/quick-sort#2","route":"/sorting/quick-sort","section":"sorting","subject":"dsa","title":"Quick Sort Visualizer – Pivot & Partition Animation","question":"Is Quick Sort a stable sorting algorithm?","options":["Yes, always","No, equal elements can change relative order","Only with random pivot selection","Only in the average case"],"correct":1,"explanation":"Quick Sort is not stable. During partitioning, equal elements can be moved past each other, changing their relative order."},{"id":"sorting/radix-sort#0","route":"/sorting/radix-sort","section":"sorting","subject":"dsa","title":"Radix Sort Visualizer – Digit-by-Digit Sort Animation","question":"Is Radix Sort a comparison-based sorting algorithm?","options":["Yes, it compares digits","No, it distributes elements by digit value","It depends on the implementation","Yes, it compares full numbers"],"correct":1,"explanation":"Radix Sort is non-comparison based. Instead of comparing elements, it distributes them into buckets based on individual digit values, allowing it to break the O(n log n) barrier."},{"id":"sorting/radix-sort#1","route":"/sorting/radix-sort","section":"sorting","subject":"dsa","title":"Radix Sort Visualizer – Digit-by-Digit Sort Animation","question":"What does 'd' represent in Radix Sort's O(d×(n+k)) complexity?","options":["The depth of recursion","The number of digits in the maximum value","The number of distinct elements","The data type size"],"correct":1,"explanation":"In Radix Sort, 'd' is the number of digits (passes needed), 'n' is the number of elements, and 'k' is the base (10 for decimal). Each pass processes one digit position."},{"id":"sorting/radix-sort#2","route":"/sorting/radix-sort","section":"sorting","subject":"dsa","title":"Radix Sort Visualizer – Digit-by-Digit Sort Animation","question":"In LSD (Least Significant Digit) Radix Sort, which digit is processed first?","options":["Most significant (leftmost)","Least significant (rightmost)","Middle digit","Random digit"],"correct":1,"explanation":"LSD Radix Sort starts from the rightmost (least significant) digit and works left. This ensures stability is preserved and the final pass produces a correctly sorted array."},{"id":"sorting/selection-sort#0","route":"/sorting/selection-sort","section":"sorting","subject":"dsa","title":"Selection Sort Visualizer – Step-by-Step Animation","question":"How many swaps does Selection Sort perform in the worst case?","options":["O(n²)","O(n log n)","O(n)","O(1)"],"correct":2,"explanation":"Selection Sort performs at most n-1 swaps (one per pass), regardless of input. This makes it efficient when write operations are costly."},{"id":"sorting/selection-sort#1","route":"/sorting/selection-sort","section":"sorting","subject":"dsa","title":"Selection Sort Visualizer – Step-by-Step Animation","question":"Is Selection Sort a stable sorting algorithm?","options":["Yes, always stable","No, it can change the relative order of equal elements","Only with additional memory","It depends on the data type"],"correct":1,"explanation":"Selection Sort is not stable. When swapping the minimum to its position, equal elements can change their relative order."},{"id":"sorting/selection-sort#2","route":"/sorting/selection-sort","section":"sorting","subject":"dsa","title":"Selection Sort Visualizer – Step-by-Step Animation","question":"What is the time complexity of Selection Sort in all cases?","options":["O(n) best, O(n²) worst","O(n log n) in all cases","O(n²) in all cases","O(n) average, O(n²) worst"],"correct":2,"explanation":"Selection Sort always scans the entire unsorted portion to find the minimum — regardless of input order — so it's O(n²) in best, average, and worst cases."},{"id":"string-algorithms/kmp-string-matching#0","route":"/string-algorithms/kmp-string-matching","section":"string-algorithms","subject":"dsa","title":"KMP String Matching – String Algorithms Visualizer","question":"What does the failure function (LPS array) store at position i?","options":["The index where the next mismatch occurs","The length of the longest proper prefix of pattern[0..i] that is also a suffix","The number of characters matched so far","The position in the text where the pattern was last found"],"correct":1,"explanation":"LPS stands for Longest Proper Prefix which is also Suffix. LPS[i] tells us how far we can shift the pattern on a mismatch at position i+1 — we jump j to LPS[j-1] instead of restarting from 0."},{"id":"string-algorithms/kmp-string-matching#1","route":"/string-algorithms/kmp-string-matching","section":"string-algorithms","subject":"dsa","title":"KMP String Matching – String Algorithms Visualizer","question":"When a mismatch occurs at pattern[j] during matching, what does KMP do next?","options":["Increments the text pointer i and restarts j at 0","Decrements i by j positions and sets j = 0","Sets j = LPS[j−1] without moving i (or sets j=0 and increments i if j was already 0)","Shifts the pattern by one position regardless of LPS"],"correct":2,"explanation":"On a mismatch, KMP never goes backwards in the text. If j > 0, it sets j = LPS[j−1], effectively sliding the pattern to the right so the already-matched prefix lines up. Only if j = 0 does it increment i. This guarantees O(n+m) total work."},{"id":"string-algorithms/kmp-string-matching#2","route":"/string-algorithms/kmp-string-matching","section":"string-algorithms","subject":"dsa","title":"KMP String Matching – String Algorithms Visualizer","question":"Why is KMP O(n + m) instead of O(n × m)?","options":["It uses hashing to skip comparisons","The text pointer i never moves backward, so each character is compared at most twice (once in LPS build, once in matching)","It divides the text into blocks of size m","It only compares characters when the first characters match"],"correct":1,"explanation":"The key insight is that i only moves forward. Even though j can jump backward (via LPS), i never does. This bounds the total number of comparisons: O(m) for the LPS build and O(n) for the matching scan — giving O(n + m) overall."},{"id":"string-algorithms/rabin-karp#0","route":"/string-algorithms/rabin-karp","section":"string-algorithms","subject":"dsa","title":"Rabin-Karp Rolling Hash – String Algorithms Visualizer","question":"What is the purpose of the 'rolling hash' in Rabin-Karp?","options":["To sort the text before searching","To update the hash of a sliding window in O(1) by removing the old character and adding the new one","To compute all possible substrings and store them","To encrypt the text for security"],"correct":1,"explanation":"A rolling hash lets us slide the window by one position in O(1): subtract the contribution of the character leaving the window and add the contribution of the new character entering. Without rolling, computing each window's hash from scratch would take O(m) per position, giving O(n×m) overall."},{"id":"string-algorithms/rabin-karp#1","route":"/string-algorithms/rabin-karp","section":"string-algorithms","subject":"dsa","title":"Rabin-Karp Rolling Hash – String Algorithms Visualizer","question":"What is a hash collision in Rabin-Karp, and how is it handled?","options":["When the pattern hash equals the window hash — always means a match","When the hash overflows a 32-bit integer","When two different strings produce the same hash value — triggers a character-by-character verification","When the pattern length exceeds the text length"],"correct":2,"explanation":"A hash function may map different strings to the same value. When the window hash equals the pattern hash, Rabin-Karp verifies character by character to confirm or reject the match. This is called a 'spurious hit'. With a good hash, collisions are rare and the average complexity stays O(n+m)."},{"id":"string-algorithms/rabin-karp#2","route":"/string-algorithms/rabin-karp","section":"string-algorithms","subject":"dsa","title":"Rabin-Karp Rolling Hash – String Algorithms Visualizer","question":"What is the average and worst-case time complexity of Rabin-Karp?","options":["O(n+m) average, O(n×m) worst case","O(n log n) average, O(n log n) worst case","O(n+m) both average and worst case","O(n) average, O(n²) worst case"],"correct":0,"explanation":"On average, Rabin-Karp is O(n+m) because hash collisions are rare. In the worst case (e.g., a string of all identical characters), every window might collide and require full verification, giving O(n×m). KMP guarantees O(n+m) worst case, making it preferable when worst-case matters."},{"id":"string-algorithms/z-algorithm#0","route":"/string-algorithms/z-algorithm","section":"string-algorithms","subject":"dsa","title":"Z-Algorithm – String Algorithms Visualizer","question":"What does Z[i] represent in the Z-array?","options":["The index of the next character to compare","The length of the longest substring starting at position i that matches a prefix of the full string","The number of mismatches at position i","The distance from position i to the next occurrence of the first character"],"correct":1,"explanation":"Z[i] is the length of the longest substring starting at index i that is also a prefix of the entire string. For pattern matching, we build the combined string S = pattern + '$' + text, then any position in the text part where Z[i] equals the pattern length is a match."},{"id":"string-algorithms/z-algorithm#1","route":"/string-algorithms/z-algorithm","section":"string-algorithms","subject":"dsa","title":"Z-Algorithm – String Algorithms Visualizer","question":"What is the Z-box [l, r] used for?","options":["To store the positions where the pattern was found","To mark the rightmost Z-interval found so far, allowing reuse of previously computed Z values instead of comparing from scratch","To represent the left and right boundaries of the pattern","To store the indices of characters that failed to match"],"correct":1,"explanation":"The Z-box [l, r] records the rightmost matching interval computed so far. When computing Z[i] for a new i inside [l, r], we can reuse Z[i-l] as a starting lower bound because S[i..r] already matches S[0..r-l]. This avoids redundant comparisons and keeps the algorithm O(n)."},{"id":"string-algorithms/z-algorithm#2","route":"/string-algorithms/z-algorithm","section":"string-algorithms","subject":"dsa","title":"Z-Algorithm – String Algorithms Visualizer","question":"Why do we insert '$' (or any character not in the alphabet) between the pattern and text?","options":["To count the total length of the combined string","To prevent a Z-value from spanning the pattern–text boundary, ensuring Z values in the text part cannot exceed the pattern length","To make the hash computation easier","To mark the end of the text for the algorithm"],"correct":1,"explanation":"The separator '$' is a character guaranteed not to appear in either the pattern or text. This ensures Z[i] for positions in the text half can never extend back across the '$' into the pattern, so Z values naturally cap at the pattern length. Without it, a prefix match could falsely extend into the separator."},{"id":"trees/avl-tree#0","route":"/trees/avl-tree","section":"trees","subject":"dsa","title":"AVL Tree Visualizer","question":"What balance factor makes an AVL node \"unbalanced\"?","options":["> 0","> 1 or < -1","= 1","≠ 0"],"correct":1,"explanation":"AVL allows balance factors of -1, 0, or +1. If |bf| > 1, a rotation is needed."},{"id":"trees/avl-tree#1","route":"/trees/avl-tree","section":"trees","subject":"dsa","title":"AVL Tree Visualizer","question":"How many rotations does an LR (Left-Right) case require?","options":["1","2","3","0"],"correct":1,"explanation":"LR requires a left rotation on the left child, then a right rotation on the unbalanced node — two single rotations."},{"id":"trees/avl-tree#2","route":"/trees/avl-tree","section":"trees","subject":"dsa","title":"AVL Tree Visualizer","question":"What is the guaranteed height of an AVL tree with n nodes?","options":["O(n)","O(n²)","O(log n)","O(n log n)"],"correct":2,"explanation":"AVL rotations keep the tree balanced, guaranteeing height O(log n) and thus O(log n) search/insert/delete."},{"id":"trees/binary-search-tree#0","route":"/trees/binary-search-tree","section":"trees","subject":"dsa","title":"Binary Search Tree Visualizer","question":"What is the average-case time complexity of BST search?","options":["O(1)","O(log n)","O(n)","O(n log n)"],"correct":1,"explanation":"In a balanced BST, each step halves the remaining search space → O(log n). A degenerate (sorted-insertion) tree degrades to O(n)."},{"id":"trees/binary-search-tree#1","route":"/trees/binary-search-tree","section":"trees","subject":"dsa","title":"Binary Search Tree Visualizer","question":"You insert values [1, 2, 3, 4, 5] into a BST. What is the resulting shape?","options":["A balanced complete tree","A right-skewed linked list","A left-skewed linked list","A random shape"],"correct":1,"explanation":"Inserting already-sorted values always follows the right child, producing a right-skewed degenerate tree — the BST worst case."},{"id":"trees/binary-search-tree#2","route":"/trees/binary-search-tree","section":"trees","subject":"dsa","title":"Binary Search Tree Visualizer","question":"Where is the minimum element in a BST always located?","options":["The root","A random leaf","The leftmost node","The rightmost node"],"correct":2,"explanation":"Every left child is smaller than its parent. Following left pointers to the end always yields the minimum."},{"id":"trees/binary-tree-traversals#0","route":"/trees/binary-tree-traversals","section":"trees","subject":"dsa","title":"Binary Tree Traversals Visualizer","question":"Inorder traversal of a BST produces nodes in what order?","options":["Random","Level by level","Ascending sorted order","Reverse sorted"],"correct":2,"explanation":"BST property guarantees left < root < right at every node, so inorder (L→Root→R) produces sorted ascending output."},{"id":"trees/binary-tree-traversals#1","route":"/trees/binary-tree-traversals","section":"trees","subject":"dsa","title":"Binary Tree Traversals Visualizer","question":"Which traversal visits the root node FIRST?","options":["Inorder","Preorder","Postorder","Level-order"],"correct":1,"explanation":"Preorder: Root → Left → Right. The root is processed before any of its children."},{"id":"trees/binary-tree-traversals#2","route":"/trees/binary-tree-traversals","section":"trees","subject":"dsa","title":"Binary Tree Traversals Visualizer","question":"Level-order traversal uses which auxiliary data structure?","options":["Stack","Queue","Array","Hash map"],"correct":1,"explanation":"BFS / Level-order uses a Queue (FIFO). A stack would give DFS behaviour instead."},{"id":"trees/segment-tree#0","route":"/trees/segment-tree","section":"trees","subject":"dsa","title":"Segment Tree Visualizer","question":"What is the time complexity of a range-sum query on a segment tree?","options":["O(1)","O(n)","O(log n)","O(n log n)"],"correct":2,"explanation":"At each level the query visits at most 2 nodes, and there are O(log n) levels → O(log n) total."},{"id":"trees/segment-tree#1","route":"/trees/segment-tree","section":"trees","subject":"dsa","title":"Segment Tree Visualizer","question":"How many nodes does a segment tree need for an n-element array?","options":["n","2n","Up to 4n","n²"],"correct":2,"explanation":"The tree needs at most 4n space in the array representation. A perfect binary tree with n leaves needs 2n-1 nodes, but segment trees need extra for safety."},{"id":"trees/segment-tree#2","route":"/trees/segment-tree","section":"trees","subject":"dsa","title":"Segment Tree Visualizer","question":"What is the time complexity of a point update?","options":["O(1)","O(log n)","O(n)","O(n log n)"],"correct":1,"explanation":"A point update follows the path from leaf to root, updating O(log n) ancestors."},{"id":"trees/trie#0","route":"/trees/trie","section":"trees","subject":"dsa","title":"Trie Visualizer","question":"What is the time complexity of inserting a word of length L into a Trie?","options":["O(1)","O(L)","O(n)","O(L log n)"],"correct":1,"explanation":"Each character is processed exactly once, creating or traversing one node per character → O(L)."},{"id":"trees/trie#1","route":"/trees/trie","section":"trees","subject":"dsa","title":"Trie Visualizer","question":"What makes a Trie better than a hash map for prefix search?","options":["O(1) lookup","Supports prefix queries natively","Less memory usage","Faster hash computation"],"correct":1,"explanation":"Tries store words as shared prefix paths, enabling all words with a given prefix to be found by traversing to the prefix node and listing descendants."},{"id":"trees/trie#2","route":"/trees/trie","section":"trees","subject":"dsa","title":"Trie Visualizer","question":"Which application is a Trie BEST suited for?","options":["Range sum queries","Shortest path in a graph","Autocomplete / spell check","Sorting integers"],"correct":2,"explanation":"Tries are ideal for prefix-based operations: autocomplete engines use tries to find all words starting with a typed prefix in O(prefix length) time."},{"id":"two-pointers-and-sliding-window/3sum#0","route":"/two-pointers-and-sliding-window/3sum","section":"two-pointers-and-sliding-window","subject":"dsa","title":"3Sum Visualizer","question":"Why must the array be sorted before applying the two-pointer technique in 3Sum?","options":["Sorting makes duplicate removal easier by grouping equal values together","Sorting allows skipping the pivot entirely","Both A and the fact that sorted order lets us make a definitive decision (move left or right) at each step based on the current sum","Sorting is only needed to print the triplets in order"],"correct":2,"explanation":"Sorting serves two purposes: (1) it groups duplicates so we can skip them with a simple neighbour-check, and (2) it gives the two-pointer technique its decision rule — if the sum is too small, moving left rightward increases it; if too large, moving right leftward decreases it. Without sorting neither property holds."},{"id":"two-pointers-and-sliding-window/3sum#1","route":"/two-pointers-and-sliding-window/3sum","section":"two-pointers-and-sliding-window","subject":"dsa","title":"3Sum Visualizer","question":"What is the overall time complexity of the 3Sum algorithm?","options":["O(n) — one pass with two pointers","O(n log n) — dominated by sorting","O(n²) — outer pivot loop × inner two-pointer sweep","O(n³) — three nested loops"],"correct":2,"explanation":"Sorting costs O(n log n). The outer loop runs O(n) times; for each pivot the two-pointer sweep runs O(n). Total: O(n²). This is a significant improvement over the brute-force O(n³) approach of trying every triplet."},{"id":"two-pointers-and-sliding-window/3sum#2","route":"/two-pointers-and-sliding-window/3sum","section":"two-pointers-and-sliding-window","subject":"dsa","title":"3Sum Visualizer","question":"Why do we skip a pivot when nums[i] == nums[i-1]?","options":["To avoid an index-out-of-bounds error","Because a repeated pivot would generate the same set of triplets already found in the previous iteration","Because equal pivots always produce a sum greater than zero","To improve average-case performance only — correctness is unaffected"],"correct":1,"explanation":"If the current pivot equals the previous one, the remaining sub-array to its right is identical. Any triplet the current pivot could form was already found (or rejected) when the previous identical pivot ran. Skipping prevents duplicate triplets in the output."},{"id":"two-pointers-and-sliding-window/container-with-most-water#0","route":"/two-pointers-and-sliding-window/container-with-most-water","section":"two-pointers-and-sliding-window","subject":"dsa","title":"Container With Most Water Visualizer","question":"Why do we always move the pointer with the shorter bar inward?","options":["Moving the shorter bar inward gives a chance to find a taller bar that compensates for the reduced width, whereas keeping the shorter bar can never produce a larger area","The shorter bar is always at the left side of the array","Moving the taller bar would skip valid solutions","Both pointers always move simultaneously"],"correct":0,"explanation":"Area = width × min(h[L], h[R]). If we move the taller bar, width decreases while height is still bounded by the same shorter bar — area can only decrease. Moving the shorter bar reduces width but opens the possibility of finding a taller boundary that more than compensates. This greedy choice provably never skips the optimal pair."},{"id":"two-pointers-and-sliding-window/container-with-most-water#1","route":"/two-pointers-and-sliding-window/container-with-most-water","section":"two-pointers-and-sliding-window","subject":"dsa","title":"Container With Most Water Visualizer","question":"What is the time complexity of the two-pointer approach?","options":["O(n²) — we check every pair","O(n log n) — similar to sorting","O(n) — each pointer moves at most n times total","O(1) — constant time"],"correct":2,"explanation":"Left starts at 0 and only moves right; right starts at n−1 and only moves left. Together they make at most n−1 moves, so the algorithm runs in O(n) — far better than the O(n²) brute-force of checking every pair."},{"id":"two-pointers-and-sliding-window/container-with-most-water#2","route":"/two-pointers-and-sliding-window/container-with-most-water","section":"two-pointers-and-sliding-window","subject":"dsa","title":"Container With Most Water Visualizer","question":"Can the algorithm ever miss the optimal pair of bars?","options":["Yes, if both optimal bars are in the middle of the array","No — when a pointer moves past a bar, every pair involving that bar and a remaining bar has already been proven suboptimal","Yes, for arrays with all equal heights","Only when the optimal pair is adjacent"],"correct":1,"explanation":"The invariant is: no skipped pair can beat the current maximum. When we move a pointer past a bar, we know that pairing that bar with any remaining bar produces less width and no greater height than what we've already considered. The algorithm visits every candidate that could be optimal."},{"id":"two-pointers-and-sliding-window/longest-substring-without-repeating-characters#0","route":"/two-pointers-and-sliding-window/longest-substring-without-repeating-characters","section":"two-pointers-and-sliding-window","subject":"dsa","title":"Longest Substring Without Repeating Characters Visualizer","question":"Why do we check `char_map[s[right]] >= left` instead of just checking `s[right] in char_map`?","options":["To avoid an index out of bounds error","Because characters can appear multiple times; we only care if the previous occurrence is INSIDE the current window (>= left), not somewhere we already shrunk past","To make the algorithm work on Unicode strings","Because the hash map stores indices starting from 1, not 0"],"correct":1,"explanation":"The character map remembers the last-seen index of every character, even those the left pointer has already passed. If the previous occurrence is to the LEFT of our current left pointer, it is outside the window and harmless — we can safely extend. Only when the previous occurrence is still inside the window (index >= left) must we advance the left pointer."},{"id":"two-pointers-and-sliding-window/longest-substring-without-repeating-characters#1","route":"/two-pointers-and-sliding-window/longest-substring-without-repeating-characters","section":"two-pointers-and-sliding-window","subject":"dsa","title":"Longest Substring Without Repeating Characters Visualizer","question":"What data structure tracks character positions in this algorithm?","options":["A sorted array of (char, index) pairs","A stack","A hash map (dictionary) mapping each character to its most recent index","A linked list"],"correct":2,"explanation":"A hash map (Python dict / JavaScript object) provides O(1) average-case lookup and update. We store each character as a key and its most recent position as the value. This lets us instantly find whether a character is in the window and where to move the left pointer."},{"id":"two-pointers-and-sliding-window/longest-substring-without-repeating-characters#2","route":"/two-pointers-and-sliding-window/longest-substring-without-repeating-characters","section":"two-pointers-and-sliding-window","subject":"dsa","title":"Longest Substring Without Repeating Characters Visualizer","question":"What is the time complexity of the longest substring without repeating characters algorithm?","options":["O(n²) — nested loops over characters","O(n log n) — sorting involved","O(n) — each character is processed at most twice","O(n * |alphabet|) — depends on character set size"],"correct":2,"explanation":"The right pointer visits each character exactly once as it moves left to right. The left pointer only moves right, so it also visits each position at most once. Total operations are O(2n) = O(n). Hash map lookups are O(1) average, so overall time complexity is O(n)."},{"id":"two-pointers-and-sliding-window/maximum-sum-subarray#0","route":"/two-pointers-and-sliding-window/maximum-sum-subarray","section":"two-pointers-and-sliding-window","subject":"dsa","title":"Maximum Sum Subarray Visualizer – Fixed Sliding Window","question":"Why is the sliding window approach O(n) instead of O(n*k)?","options":["Because we use a hash map to cache sums","Because we only compute the first window's sum directly; every subsequent sum reuses the previous one by removing one element and adding one","Because the array is sorted so we can skip elements","Because we only look at elements at even indices"],"correct":1,"explanation":"The brute-force approach recomputes the sum from scratch for every window — O(k) per window, O(n*k) total. The sliding window avoids this: each step subtracts the element leaving the window and adds the element entering it. Each element is touched exactly twice (once added, once removed), giving O(n) overall."},{"id":"two-pointers-and-sliding-window/maximum-sum-subarray#1","route":"/two-pointers-and-sliding-window/maximum-sum-subarray","section":"two-pointers-and-sliding-window","subject":"dsa","title":"Maximum Sum Subarray Visualizer – Fixed Sliding Window","question":"What is the key operation when the window slides one position to the right?","options":["Re-sort the window elements","Compute the sum of all k elements from scratch","Subtract the leftmost element of the old window and add the new rightmost element","Binary search for the maximum element in the window"],"correct":2,"explanation":"When the window shifts by one position: window_sum = window_sum - arr[i-1] + arr[i+k-1]. We subtract the element that just left the left edge and add the element that just entered the right edge. This constant-time update is the core insight of the sliding window pattern."},{"id":"two-pointers-and-sliding-window/maximum-sum-subarray#2","route":"/two-pointers-and-sliding-window/maximum-sum-subarray","section":"two-pointers-and-sliding-window","subject":"dsa","title":"Maximum Sum Subarray Visualizer – Fixed Sliding Window","question":"What is the space complexity of the sliding window maximum sum algorithm?","options":["O(k) — we store the current window","O(n) — we store all window sums","O(1) — we only track a few variables","O(log n) — recursion depth"],"correct":2,"explanation":"We only need a constant number of variables: window_sum, max_sum, max_start, and a loop counter. No additional array or data structure is needed regardless of n or k. Space complexity is O(1)."},{"id":"two-pointers-and-sliding-window/minimum-window-substring#0","route":"/two-pointers-and-sliding-window/minimum-window-substring","section":"two-pointers-and-sliding-window","subject":"dsa","title":"Minimum Window Substring Visualizer","question":"Why can we check window validity in O(1) instead of re-scanning the window each time?","options":["Because the window is always sorted","We maintain a 'formed' counter that tracks how many distinct characters from t are satisfied — incrementing/decrementing it with each pointer move keeps it accurate in constant time","Because we only need to check the character at the right pointer","Because we use binary search on the frequency map"],"correct":1,"explanation":"We precompute how many unique characters in t are needed ('required'). The 'formed' counter increments when a character's window count exactly meets its target, and decrements when it falls below. When formed == required the window is valid — no scanning needed. Each pointer move updates at most one character's count and possibly formed by 1."},{"id":"two-pointers-and-sliding-window/minimum-window-substring#1","route":"/two-pointers-and-sliding-window/minimum-window-substring","section":"two-pointers-and-sliding-window","subject":"dsa","title":"Minimum Window Substring Visualizer","question":"What is the time complexity of the sliding window approach?","options":["O(n·m) — for each position we scan t","O(n + m) — each character in s and t is processed a constant number of times","O(n²) — the left pointer may scan the whole string for each right step","O(m²) — dominated by the frequency map"],"correct":1,"explanation":"The right pointer advances through s exactly once (O(n)). The left pointer also advances through s at most once in total (O(n)). Building and querying the frequency map takes O(m) for the pattern. Total: O(n + m). No position is visited more than twice."},{"id":"two-pointers-and-sliding-window/minimum-window-substring#2","route":"/two-pointers-and-sliding-window/minimum-window-substring","section":"two-pointers-and-sliding-window","subject":"dsa","title":"Minimum Window Substring Visualizer","question":"When should we advance the left pointer?","options":["After every step of the right pointer","Only when the window becomes longer than the current minimum","Whenever the window is valid — we shrink from the left to find the tightest window while validity holds","When the right pointer's character is already in the window"],"correct":2,"explanation":"Once the window satisfies all character requirements (formed == required), we record it as a candidate minimum, then advance the left pointer one step to try shrinking it. We keep shrinking as long as the window remains valid, since a shorter valid window is always better. The moment validity breaks we resume expanding from the right."},{"id":"two-pointers-and-sliding-window/two-sum-ii#0","route":"/two-pointers-and-sliding-window/two-sum-ii","section":"two-pointers-and-sliding-window","subject":"dsa","title":"Two Sum II Visualizer – Two Pointer Technique","question":"Why does this two-pointer approach work on a sorted array but not on an unsorted one?","options":["Because sorting makes elements unique so no duplicates are counted","Because sorting guarantees that moving the left pointer right increases the sum and moving the right pointer left decreases it","Because sorting allows us to use binary search to find the answer faster","Because unsorted arrays have no two elements that sum to the target"],"correct":1,"explanation":"The two-pointer method relies on sorted order to make a definitive decision at each step. If the current sum is too small, moving left rightward always increases it; if too large, moving right leftward always decreases it. Without sorting there is no such guarantee, so you cannot eliminate half the possibilities at each step."},{"id":"two-pointers-and-sliding-window/two-sum-ii#1","route":"/two-pointers-and-sliding-window/two-sum-ii","section":"two-pointers-and-sliding-window","subject":"dsa","title":"Two Sum II Visualizer – Two Pointer Technique","question":"What is the space complexity of the two-pointer approach to Two Sum II?","options":["O(n) — we store a copy of the array","O(log n) — recursion stack","O(1) — only two pointer variables are used","O(n²) — we compare all pairs"],"correct":2,"explanation":"We use only two integer pointer variables (left and right) regardless of input size. No extra arrays or hash maps are needed because the sorted order gives us all the information we need. Space complexity is O(1)."},{"id":"two-pointers-and-sliding-window/two-sum-ii#2","route":"/two-pointers-and-sliding-window/two-sum-ii","section":"two-pointers-and-sliding-window","subject":"dsa","title":"Two Sum II Visualizer – Two Pointer Technique","question":"What happens when the current sum is less than the target?","options":["Move the right pointer one step to the left","Move the left pointer one step to the right","Move both pointers inward simultaneously","Return an empty result — no pair exists"],"correct":1,"explanation":"When sum < target we need a larger sum. Because the array is sorted, the smallest way to increase the sum is to move the left pointer rightward to a larger value. Moving the right pointer leftward would decrease the sum, which is the wrong direction."},{"id":"two-pointers-and-sliding-window/valid-palindrome#0","route":"/two-pointers-and-sliding-window/valid-palindrome","section":"two-pointers-and-sliding-window","subject":"dsa","title":"Valid Palindrome Visualizer – Two Pointer Technique","question":"Why do we skip non-alphanumeric characters when checking for a palindrome?","options":["Because non-alphanumeric characters slow down the algorithm","To match real-world definitions: 'A man, a plan, a canal: Panama' should be a valid palindrome despite spaces and punctuation","Because the algorithm cannot compare punctuation characters","To reduce the string length so it runs in O(log n) time"],"correct":1,"explanation":"The real-world definition of a palindrome ignores spaces, punctuation, and case. Stripping non-alphanumeric characters lets the algorithm match natural language phrases like 'Was it a car or a cat I saw' while still correctly rejecting strings like 'hello'."},{"id":"two-pointers-and-sliding-window/valid-palindrome#1","route":"/two-pointers-and-sliding-window/valid-palindrome","section":"two-pointers-and-sliding-window","subject":"dsa","title":"Valid Palindrome Visualizer – Two Pointer Technique","question":"What is the time complexity of the two-pointer palindrome check?","options":["O(n²) — we compare every pair of characters","O(n log n) — similar to sorting","O(n) — each character is visited at most once","O(1) — constant time with the right hash"],"correct":2,"explanation":"Each character is visited at most once: the left pointer moves right and the right pointer moves left until they meet or cross. Total work is proportional to the length of the cleaned string — O(n)."},{"id":"two-pointers-and-sliding-window/valid-palindrome#2","route":"/two-pointers-and-sliding-window/valid-palindrome","section":"two-pointers-and-sliding-window","subject":"dsa","title":"Valid Palindrome Visualizer – Two Pointer Technique","question":"When can we conclude the string IS a palindrome?","options":["When we find the first matching pair","When the left pointer passes the middle of the string","When the left pointer meets or passes the right pointer without finding a mismatch","When all characters are the same"],"correct":2,"explanation":"We can only declare the string a palindrome after checking ALL symmetric pairs. If the left pointer reaches or crosses the right pointer without encountering a mismatch, every pair has been confirmed equal and the string is a palindrome."},{"id":"under-the-hood/async-await-and-event-loop#0","route":"/under-the-hood/async-await-and-event-loop","section":"under-the-hood","subject":"cs-core","title":"Async/Await and the Event Loop","question":"What is the output order of: console.log(1); setTimeout(()=>console.log(4),0); Promise.resolve().then(()=>console.log(3)); console.log(2);","options":["1, 2, 3, 4","1, 3, 2, 4","1, 2, 4, 3","1, 4, 2, 3"],"correct":0,"explanation":"Synchronous code (1, 2) runs first. Then ALL microtasks (Promise → 3) drain before any macrotask (setTimeout → 4). Final order: 1, 2, 3, 4."},{"id":"under-the-hood/async-await-and-event-loop#1","route":"/under-the-hood/async-await-and-event-loop","section":"under-the-hood","subject":"cs-core","title":"Async/Await and the Event Loop","question":"In Python, what does calling my_coroutine() (an async def function) actually do?","options":["Returns a coroutine object without running any code","Starts the coroutine immediately on a new thread","Runs the coroutine synchronously and blocks","Schedules the coroutine on the event loop"],"correct":0,"explanation":"Calling an async def function creates a coroutine object but does NOT execute it. You need asyncio.run(), await, or asyncio.create_task() to actually run it."},{"id":"under-the-hood/async-await-and-event-loop#2","route":"/under-the-hood/async-await-and-event-loop","section":"under-the-hood","subject":"cs-core","title":"Async/Await and the Event Loop","question":"Async/await uses ___ while threading uses ___","options":["Cooperative multitasking on one thread / Preemptive multitasking on multiple threads","Preemptive multitasking on one thread / Cooperative multitasking on multiple threads","Multiple processes / Multiple threads","Shared memory / Message passing"],"correct":0,"explanation":"Async is cooperative — tasks voluntarily yield at await points, all on one thread. Threading is preemptive — the OS can interrupt threads at any time across multiple threads."},{"id":"under-the-hood/classes-objects-and-memory#0","route":"/under-the-hood/classes-objects-and-memory","section":"under-the-hood","subject":"cs-core","title":"Classes, Objects and Memory","question":"Where do an instance's methods physically live?","options":["Copied into each instance's __dict__","On the class object — one copy, shared by all instances","In a global method table keyed by object id","Inline in the machine code of each call site"],"correct":1,"explanation":"Methods are defined once on the class object. Instances hold only their own data (__dict__) plus a __class__ pointer. p.move() is found by following that pointer to the class — which is why patching a method affects every instance instantly."},{"id":"under-the-hood/classes-objects-and-memory#1","route":"/under-the-hood/classes-objects-and-memory","section":"under-the-hood","subject":"cs-core","title":"Classes, Objects and Memory","question":"When you access p.x, what does Python check first?","options":["The class attributes","The base classes (MRO)","The instance's own __dict__","A global variable named x"],"correct":2,"explanation":"Attribute lookup checks the instance __dict__ first, so per-object data shadows class attributes. Only on a miss does it follow __class__ to the class and then up the base classes."},{"id":"under-the-hood/classes-objects-and-memory#2","route":"/under-the-hood/classes-objects-and-memory","section":"under-the-hood","subject":"cs-core","title":"Classes, Objects and Memory","question":"What is self, really?","options":["A special keyword the interpreter reserves","A copy of the class","Just the instance the method was looked up on, passed as the first argument","A pointer to the method's bytecode"],"correct":2,"explanation":"p.move(3,4) is sugar for Point.move(p, 3, 4). The method is an ordinary function on the class; Python passes the instance as the first argument, conventionally named self. That is how one shared method knows which object's data to use."},{"id":"under-the-hood/composition-vs-inheritance#0","route":"/under-the-hood/composition-vs-inheritance","section":"under-the-hood","subject":"cs-core","title":"Composition vs Inheritance","question":"Which relationship is composition designed to model?","options":["\"is-a\" — a subtype of another class","\"has-a\" — an object built from other objects it holds and delegates to","\"calls\" — one function invoking another","\"is-equal-to\" — value equality"],"correct":1,"explanation":"Composition models has-a: an object holds other objects as fields and reuses their behavior by delegating to them (Car has-a Engine). Inheritance models is-a — a subtype relationship. Choosing the honest relationship keeps designs clean."},{"id":"under-the-hood/composition-vs-inheritance#1","route":"/under-the-hood/composition-vs-inheritance","section":"under-the-hood","subject":"cs-core","title":"Composition vs Inheritance","question":"What is the \"fragile base class problem\"?","options":["Base classes use too much memory","A change to a base class can silently break its subclasses that depend on its internals","You cannot create instances of a base class","Base classes run slower than subclasses"],"correct":1,"explanation":"Subclasses are tightly coupled to their base's internals, so editing the base can ripple down and break subclasses you never touched. Deeper hierarchies make this worse — a key reason to prefer looser composition."},{"id":"under-the-hood/composition-vs-inheritance#2","route":"/under-the-hood/composition-vs-inheritance","section":"under-the-hood","subject":"cs-core","title":"Composition vs Inheritance","question":"Why can composition swap a behavior at runtime when inheritance cannot?","options":["Composition disables type checking","A composed component is just a held object behind an interface, so it can be reassigned; a base class is fixed at compile time","Inheritance is slower","Composed objects live on the stack"],"correct":1,"explanation":"A composed part is a field the object delegates to, so you can assign a different implementation of the same interface at runtime (the Strategy pattern). A class's base is welded in at definition time and cannot change while the program runs."},{"id":"under-the-hood/cpp-execution-pipeline#0","route":"/under-the-hood/cpp-execution-pipeline","section":"under-the-hood","subject":"cs-core","title":"C++ Execution Pipeline","question":"You get \"undefined reference to area(double)\". Which stage failed?","options":["Preprocessor","Compiler","Linker","Loader"],"correct":2,"explanation":"The compiler is happy as long as area is declared — it leaves the call as a placeholder. The error appears at link time, when the linker cannot find a definition for the symbol in any object file or library."},{"id":"under-the-hood/cpp-execution-pipeline#1","route":"/under-the-hood/cpp-execution-pipeline","section":"under-the-hood","subject":"cs-core","title":"C++ Execution Pipeline","question":"What does the C++ preprocessor actually do with #include and #define?","options":["Type-checks the included code","Pure text substitution — paste files in, replace macros","Compiles headers to machine code","Allocates memory for globals"],"correct":1,"explanation":"The preprocessor is a blunt text engine. #include pastes a file in verbatim; #define is a textual find-and-replace. It does no type checking and does not understand C++ — that is the compiler's job on the resulting translation unit."},{"id":"under-the-hood/cpp-execution-pipeline#2","route":"/under-the-hood/cpp-execution-pipeline","section":"under-the-hood","subject":"cs-core","title":"C++ Execution Pipeline","question":"Why does compiled C++ typically run much faster than CPython?","options":["C++ has shorter variable names","Translation and optimization happen once ahead of time; the CPU runs native code directly, with no per-op interpreter","Python cannot use the CPU cache","C++ skips the operating system"],"correct":1,"explanation":"C++ does all parsing, optimization, and codegen at build time, producing native machine code the CPU executes directly. CPython interprets bytecode op-by-op at runtime, paying dispatch and dynamic-typing overhead on every operation."},{"id":"under-the-hood/cpu-cache-hierarchy#0","route":"/under-the-hood/cpu-cache-hierarchy","section":"under-the-hood","subject":"cs-core","title":"CPU Cache Hierarchy","question":"When the CPU reads one uncached byte, how much does the hardware actually fetch?","options":["Exactly that one byte","The entire 64-byte cache line containing it","The whole 4 KB memory page","All of L1 is refilled"],"correct":1,"explanation":"Caches operate on fixed-size cache lines (typically 64 bytes). Touching one byte pulls its whole line into cache. This is why sequential access is fast — the neighbors come along for free — and why stride-heavy access wastes most of each line."},{"id":"under-the-hood/cpu-cache-hierarchy#1","route":"/under-the-hood/cpu-cache-hierarchy","section":"under-the-hood","subject":"cs-core","title":"CPU Cache Hierarchy","question":"Why does iterating a 2D array column-major (in a row-major language) often run far slower than row-major, despite identical Big-O?","options":["Column-major does more arithmetic","It uses more registers","Each step strides a full row ahead, landing in a new cache line every time → a miss on nearly every access","The compiler refuses to optimize it"],"correct":2,"explanation":"Row-major storage makes a row contiguous. Walking down a column jumps by a full row (a large stride) each step, so almost every access falls in a different cache line and misses. Row-major traversal reuses each loaded line across the whole row. Same operations, very different cache behavior."},{"id":"under-the-hood/cpu-cache-hierarchy#2","route":"/under-the-hood/cpu-cache-hierarchy","section":"under-the-hood","subject":"cs-core","title":"CPU Cache Hierarchy","question":"Roughly how much slower is a main-RAM access than an L1 cache hit?","options":["About the same","Around 2×","Around 50×","Around 10,000×"],"correct":2,"explanation":"An L1 hit is ~4 cycles; a RAM access is ~200 cycles — on the order of 50× slower. (Disk is another ~1000×+ beyond RAM.) That gap is why keeping the working set in cache, via locality, dominates real-world performance."},{"id":"under-the-hood/floating-point-and-ieee-754#0","route":"/under-the-hood/floating-point-and-ieee-754","section":"under-the-hood","subject":"cs-core","title":"Floating Point and IEEE 754","question":"Why can a double not store 0.1 exactly?","options":["Because 64 bits is not enough storage for that many digits","Because a fraction terminates in binary only when its denominator is a power of 2 — and 1/10 is not, so its expansion repeats forever","Because the exponent field is too small","Because rounding is applied to every literal on principle"],"correct":1,"explanation":"It is not a capacity problem — no number of bits would help. In base 2 a fraction has a finite representation only if its denominator divides a power of 2. Ten does not, so 0.1 is 0.0(0011) repeating in binary, exactly as 1/3 is 0.333… in decimal. The 52-bit mantissa must cut that infinite pattern off and round."},{"id":"under-the-hood/floating-point-and-ieee-754#1","route":"/under-the-hood/floating-point-and-ieee-754","section":"under-the-hood","subject":"cs-core","title":"Floating Point and IEEE 754","question":"Why does 2**53 === 2**53 + 1 evaluate to true?","options":["Because JavaScript treats large numbers as strings","Because the addition overflows to infinity","Because past 2⁵³ the gap between consecutive doubles exceeds 1, so 2⁵³ + 1 is not representable and rounds back down","Because === ignores the last mantissa bit"],"correct":2,"explanation":"Doubles are not evenly spaced. One ULP is 2⁻⁵² near 1, but the gap doubles with each doubling of magnitude, reaching exactly 1.0 at 2⁵² and exceeding 1 beyond 2⁵³. So 2⁵³ + 1 has no encoding and rounds to 2⁵³. This is why Number.MAX_SAFE_INTEGER is 2⁵³ − 1, why 64-bit database IDs corrupt when parsed as JSON numbers, and why BigInt exists."},{"id":"under-the-hood/floating-point-and-ieee-754#2","route":"/under-the-hood/floating-point-and-ieee-754","section":"under-the-hood","subject":"cs-core","title":"Floating Point and IEEE 754","question":"What is the correct way to compare two computed floating-point values?","options":["Use === and it will be fine after rounding both","Compare with a fixed tolerance such as 1e-9","Compare the absolute difference against Number.EPSILON scaled by the magnitude of the values","Convert both to strings and compare those"],"correct":2,"explanation":"Because the gap between neighbouring doubles grows with magnitude, tolerance must scale too. Math.abs(a-b) <= Number.EPSILON * Math.max(Math.abs(a), Math.abs(b)) adapts automatically. A fixed 1e-9 is far too strict near 1e16 and needlessly loose near zero. For money, do not use floats at all — use integer minor units or a decimal type."},{"id":"under-the-hood/garbage-collection#0","route":"/under-the-hood/garbage-collection","section":"under-the-hood","subject":"cs-core","title":"Garbage Collection","question":"Why can reference counting alone never reclaim a reference cycle?","options":["Cycles use too much memory to scan","Objects in the cycle keep each other's count above zero, even when unreachable","Reference counts cannot exceed 1","The garbage collector ignores cyclic objects on purpose"],"correct":1,"explanation":"In a cycle, each object holds a reference to the next, so every count stays ≥ 1 even after the program drops all external references. The count never reaches 0, so a pure refcounting collector never frees them. Tracing by reachability is what catches this."},{"id":"under-the-hood/garbage-collection#1","route":"/under-the-hood/garbage-collection","section":"under-the-hood","subject":"cs-core","title":"Garbage Collection","question":"In mark-and-sweep, what defines an object as \"garbage\"?","options":["Its reference count is exactly zero","It has not been used recently","It is unreachable from any root (stack, globals, registers)","It is larger than the young generation"],"correct":2,"explanation":"Tracing collectors define garbage as unreachable from the roots. The mark phase traces all reachable objects from the roots; the sweep phase frees everything left unmarked — regardless of reference counts."},{"id":"under-the-hood/garbage-collection#2","route":"/under-the-hood/garbage-collection","section":"under-the-hood","subject":"cs-core","title":"Garbage Collection","question":"What assumption makes generational GC efficient?","options":["Objects never reference each other","Most objects die young, so the small young generation can be collected often and cheaply","Memory is infinite","Old objects are always collected first"],"correct":1,"explanation":"The weak generational hypothesis: most objects die young. So the collector scans the small young generation frequently (fast minor GCs) and only rarely does an expensive full collection of long-lived old objects."},{"id":"under-the-hood/how-a-database-query-executes#0","route":"/under-the-hood/how-a-database-query-executes","section":"under-the-hood","subject":"cs-core","title":"How a Database Query Executes","question":"A query has an index on the filtered column, yet the optimizer uses a full table scan. Why might that be correct?","options":["Indexes only work on integer columns","The filter matches a large fraction of rows, so scattered index lookups would cost more than one sequential scan","The index was disabled by the parser","Full scans are always faster than index scans"],"correct":1,"explanation":"Cost-based optimizers weigh selectivity. If a predicate matches most of the table, doing thousands of random index lookups (and row fetches) costs more than a single sequential read. The optimizer correctly prefers the scan — having an index does not force its use."},{"id":"under-the-hood/how-a-database-query-executes#1","route":"/under-the-hood/how-a-database-query-executes","section":"under-the-hood","subject":"cs-core","title":"How a Database Query Executes","question":"What does the cost-based optimizer primarily use to estimate how many rows a filter will match?","options":["The order of columns in the SELECT clause","The length of the SQL string","Statistics about the data — row counts and value histograms","The number of indexes on the table"],"correct":2,"explanation":"The optimizer relies on collected statistics — table row counts and per-column histograms — to estimate selectivity. Stale statistics lead to bad estimates and bad plans, which is why databases periodically run ANALYZE / update statistics."},{"id":"under-the-hood/how-a-database-query-executes#2","route":"/under-the-hood/how-a-database-query-executes","section":"under-the-hood","subject":"cs-core","title":"How a Database Query Executes","question":"Why does an index scan on a B+tree find matching rows in roughly O(log n) instead of O(n)?","options":["It loads the whole table into RAM first","The B+tree is sorted and shallow, so a few comparisons descend straight to the matching leaf","It skips the WHERE clause","Indexes store the answer to every possible query"],"correct":1,"explanation":"A B+tree keeps keys sorted and is wide and shallow (even billions of keys are only a few levels deep). Each step down eliminates a large fraction of the tree, so locating a key takes a handful of page reads — O(log n) — instead of scanning every row."},{"id":"under-the-hood/how-a-file-system-works#0","route":"/under-the-hood/how-a-file-system-works","section":"under-the-hood","subject":"cs-core","title":"How a File System Works","question":"Where is a file's name actually stored?","options":["In the inode, alongside size and permissions","In the superblock","In the directory that contains it, as a name → inode number entry","In the first bytes of the file's data block"],"correct":2,"explanation":"The inode holds everything about a file except its name — permissions, owner, size, timestamps, block pointers. The name lives in a directory, which is itself just a file whose data is a table of name → inode pairs. This separation is why two names can point at one file, why renaming moves no data, and why the syscall to delete a name is called unlink()."},{"id":"under-the-hood/how-a-file-system-works#1","route":"/under-the-hood/how-a-file-system-works","section":"under-the-hood","subject":"cs-core","title":"How a File System Works","question":"Why can data be lost after write() has already returned successfully?","options":["write() only validates arguments and queues nothing","The bytes are in a dirty page in RAM; the kernel flushes them later, so a crash before writeback loses them unless you fsync()","The filesystem journal discards recent writes on reboot","Because the block was never allocated"],"correct":1,"explanation":"write() copies your bytes into the page cache, marks the page dirty, and returns — the disk has not been touched yet. Writeback happens in the background on the kernel's schedule. Only fsync() blocks until the device confirms durability, which is why databases fsync on commit and why power loss can lose data a program was told it had written."},{"id":"under-the-hood/how-a-file-system-works#2","route":"/under-the-hood/how-a-file-system-works","section":"under-the-hood","subject":"cs-core","title":"How a File System Works","question":"What does an inode's link count track, and when are its blocks freed?","options":["The number of open file descriptors; freed when all are closed","The number of blocks in the file; freed when it reaches zero","The number of hard links (directory entries) pointing at it — freed only when the count hits zero AND no process still has it open","The number of symlinks pointing at it"],"correct":2,"explanation":"The link count counts directory entries referring to that inode. unlink() removes one name and decrements it; the inode and its blocks return to the free pool only at zero — and even then the kernel waits until no process holds the file open. That is why deleting a large log file does not reclaim space until the process writing it restarts."},{"id":"under-the-hood/how-a-rest-api-works#0","route":"/under-the-hood/how-a-rest-api-works","section":"under-the-hood","subject":"cs-core","title":"How a REST API Works","question":"Which HTTP verb should create a brand-new resource in a collection?","options":["GET","POST","PUT","DELETE"],"correct":1,"explanation":"POST to a collection (e.g. POST /users) creates a new resource. It is not idempotent — sending it twice creates two resources. GET reads, PUT replaces an existing resource, DELETE removes one."},{"id":"under-the-hood/how-a-rest-api-works#1","route":"/under-the-hood/how-a-rest-api-works","section":"under-the-hood","subject":"cs-core","title":"How a REST API Works","question":"A request fails with 401 Unauthorized. Whose problem is it, and why?","options":["The server crashed — it is a server-side bug","The client — authentication failed (missing or invalid token)","The network dropped the connection","The resource was permanently moved"],"correct":1,"explanation":"401 is in the 4xx family — client errors. It means the request was not authenticated: no token, an expired token, or an invalid one. Fixing the Authorization header fixes it. (5xx codes are the server's fault.)"},{"id":"under-the-hood/how-a-rest-api-works#2","route":"/under-the-hood/how-a-rest-api-works","section":"under-the-hood","subject":"cs-core","title":"How a REST API Works","question":"What does it mean that REST is \"stateless\"?","options":["The server never stores any data anywhere","Each request must carry everything the server needs; the server keeps no memory between requests","The client cannot send data, only receive it","Responses are never cached"],"correct":1,"explanation":"Stateless means the server holds no session memory between requests — each request is self-contained (e.g. it carries its own auth token). Data still lives in the database; it is the per-client conversation state that the server does not keep. This is what lets any server handle any request."},{"id":"under-the-hood/how-containers-work#0","route":"/under-the-hood/how-containers-work","section":"under-the-hood","subject":"cs-core","title":"How Containers Work","question":"You run an Alpine-based image on an Ubuntu host. What does `uname -r` report inside the container?","options":["Alpine's kernel version — the image ships its own kernel","The Ubuntu host's kernel version, because an image contains only userland and there is one shared kernel","An error, since containers have no kernel","A virtualized kernel version chosen by the runtime"],"correct":1,"explanation":"A container image is userland only — libraries, binaries, config. It never contains a kernel. /etc/os-release genuinely says Alpine because those are Alpine's files, but uname reports the host kernel because that is the only kernel running. This is also why you cannot run a Windows container on a Linux host: Docker Desktop on macOS/Windows quietly runs a Linux VM."},{"id":"under-the-hood/how-containers-work#1","route":"/under-the-hood/how-containers-work","section":"under-the-hood","subject":"cs-core","title":"How Containers Work","question":"What is the difference between what namespaces do and what cgroups do?","options":["Namespaces are for networking, cgroups are for storage","They are two names for the same kernel feature","Namespaces restrict what a process can see (PIDs, mounts, network, hostname, UIDs); cgroups cap what it can consume (memory, CPU, PIDs, I/O)","Namespaces are enforced by Docker, cgroups by the kernel"],"correct":2,"explanation":"They are complementary and both kernel features. Namespaces partition visibility — a PID namespace gives a fresh process-ID number line, a mount namespace a private filesystem tree. cgroups enforce resource budgets. A container with namespaces but no cgroups is isolated but can still exhaust the host's RAM."},{"id":"under-the-hood/how-containers-work#2","route":"/under-the-hood/how-containers-work","section":"under-the-hood","subject":"cs-core","title":"How Containers Work","question":"Why does putting `COPY . .` before `RUN npm install` in a Dockerfile make builds slow?","options":["COPY is inherently a slow instruction","npm requires the source to be present before installing","A layer is cached only if its instruction and all layers beneath it are unchanged — so any source edit invalidates the COPY layer and forces the install below it to rerun","Docker rebuilds every layer on every build regardless of order"],"correct":2,"explanation":"Layers are content-addressed and cached in order. COPY . . changes whenever any source file changes, which invalidates it and every layer above it — including the dependency install. Copying package.json first, running install, then copying the source means dependencies are reinstalled only when the manifest actually changes."},{"id":"under-the-hood/how-git-works-internally#0","route":"/under-the-hood/how-git-works-internally","section":"under-the-hood","subject":"cs-core","title":"How Git Works Internally","question":"What is a Git branch, physically?","options":["A full copy of the repository at a point in time","A small file containing one commit SHA — a movable pointer into the DAG","A compressed diff of all changes since main","A list of every file that changed on the branch"],"correct":1,"explanation":"A branch is just a ~41-byte ref file holding a commit id. Creating one is O(1) regardless of repo size, which is why Git branching is so cheap. Committing writes a new object and moves that pointer forward."},{"id":"under-the-hood/how-git-works-internally#1","route":"/under-the-hood/how-git-works-internally","section":"under-the-hood","subject":"cs-core","title":"How Git Works Internally","question":"Why do two files with identical content share a single blob object?","options":["Git compresses duplicate filenames","Objects are addressed by the SHA-1 of their content, so identical content yields the same id","Blobs store filenames, so duplicates merge","Git only allows one copy of any file"],"correct":1,"explanation":"Git is content-addressed: an object's key is the hash of its bytes. Identical content hashes to the same id, so it is stored once and referenced everywhere. Filenames live in tree objects, not blobs — which is also why renames are cheap."},{"id":"under-the-hood/how-git-works-internally#2","route":"/under-the-hood/how-git-works-internally","section":"under-the-hood","subject":"cs-core","title":"How Git Works Internally","question":"How does rebase differ from merge at the object level?","options":["Rebase deletes the repository and re-clones it","Rebase creates a two-parent merge commit; merge does not","Rebase replays commits onto a new base, creating new commit ids (rewriting history); merge adds a merge commit and leaves ids unchanged","They are identical; only the command name differs"],"correct":2,"explanation":"Merge creates a new merge commit with two parents and preserves the original commits and their ids. Rebase re-applies your commits onto a new base — since a commit id is derived from its content (including its parent), the replayed commits get new ids, rewriting history. Never rebase commits others have pulled."},{"id":"under-the-hood/how-the-browser-renders-a-page#0","route":"/under-the-hood/how-the-browser-renders-a-page","section":"under-the-hood","subject":"cs-core","title":"How the Browser Renders a Page","question":"Which pair of CSS properties can be animated without triggering layout or paint?","options":["width and height","top and left","transform and opacity","margin and padding"],"correct":2,"explanation":"transform and opacity on a promoted compositor layer are handled entirely by the compositor — the GPU re-blends textures that already exist. Everything else in that list changes geometry (forcing layout, then paint, then composite) which is why \"left\"-based animations stutter where transform-based ones stay smooth."},{"id":"under-the-hood/how-the-browser-renders-a-page#1","route":"/under-the-hood/how-the-browser-renders-a-page","section":"under-the-hood","subject":"cs-core","title":"How the Browser Renders a Page","question":"How does display: none differ from visibility: hidden in the rendering pipeline?","options":["They are identical; only the spelling differs","display: none is excluded from the render tree and takes zero space; visibility: hidden stays, is laid out, and still occupies space","visibility: hidden removes the node from the DOM","display: none is painted but with zero opacity"],"correct":1,"explanation":"display: none keeps the node in the DOM (JavaScript can still reach it) but drops it and its subtree from the render tree entirely — no layout, no paint, no space. visibility: hidden stays in the render tree, gets a real box during layout, still pushes siblings around, and is simply skipped at paint time."},{"id":"under-the-hood/how-the-browser-renders-a-page#2","route":"/under-the-hood/how-the-browser-renders-a-page","section":"under-the-hood","subject":"cs-core","title":"How the Browser Renders a Page","question":"What causes \"layout thrashing\"?","options":["Using too many CSS classes on one element","Loading stylesheets after scripts","Reading a geometry property like offsetHeight and writing a style repeatedly in the same loop, forcing a synchronous reflow each iteration","Having a DOM tree deeper than ten levels"],"correct":2,"explanation":"The browser batches DOM writes and reflows once per frame, but reading a geometry value forces it to flush pending changes immediately for an accurate answer. Interleaving reads and writes in a loop defeats the batching completely — one forced reflow per iteration. Batch all reads first, then all writes, and you pay for a single reflow."},{"id":"under-the-hood/how-the-internet-routes-a-packet#0","route":"/under-the-hood/how-the-internet-routes-a-packet","section":"under-the-hood","subject":"cs-core","title":"How the Internet Routes a Packet","question":"A packet leaves your laptop for a server on the internet. What are the destination IP and destination MAC set to?","options":["Both are the server — MAC is resolved by ARP across the internet","Destination IP is the server; destination MAC is your default gateway, because MAC addresses only have meaning on the local link","Both are the gateway, and the router rewrites the IP later","The MAC is left empty until the packet reaches the ISP"],"correct":1,"explanation":"Layer 2 addressing is hop-scoped and layer 3 is end-to-end. Your laptop ARPs for the gateway's MAC — ARP is a local broadcast and cannot reach across routers. Every hop rewrites both MAC addresses for its own link while the destination IP stays untouched the entire way."},{"id":"under-the-hood/how-the-internet-routes-a-packet#1","route":"/under-the-hood/how-the-internet-routes-a-packet","section":"under-the-hood","subject":"cs-core","title":"How the Internet Routes a Packet","question":"A routing table contains 0.0.0.0/0, 93.0.0.0/8, 93.184.0.0/16 and 93.184.216.0/24. Which is used for 93.184.216.34?","options":["The default route, since it always matches","93.0.0.0/8, because shorter prefixes are cheaper to look up","93.184.216.0/24 — all four match, and the longest (most specific) prefix wins","Whichever appears first in the table"],"correct":2,"explanation":"All four entries match this address; matching is not exclusive. Longest prefix match resolves it: a /24 describes a smaller, more specific slice of address space than a /16 or /8, so it is preferred. The default route /0 matches everything and is the fallback of last resort."},{"id":"under-the-hood/how-the-internet-routes-a-packet#2","route":"/under-the-hood/how-the-internet-routes-a-packet","section":"under-the-hood","subject":"cs-core","title":"How the Internet Routes a Packet","question":"How does traceroute discover the routers along a path?","options":["It asks each router for its neighbour list","It reads the path recorded in the IP header","It sends packets with TTL=1, 2, 3… — each router that decrements TTL to zero discards the packet and returns an ICMP Time Exceeded message revealing its own address","It queries BGP for the full AS path"],"correct":2,"explanation":"The IP header records no path, and routers keep no such list for callers. Traceroute exploits TTL: a packet with TTL=1 dies at the first router, which reports back with ICMP Time Exceeded containing its own source address. Incrementing the TTL walks the path one hop at a time. Hops showing * * * are routers configured not to send ICMP."},{"id":"under-the-hood/https-and-tls#0","route":"/under-the-hood/https-and-tls","section":"under-the-hood","subject":"cs-core","title":"HTTPS and TLS","question":"In Diffie-Hellman, why can an eavesdropper who sees the common value and both public mixes still not compute the shared secret?","options":["The mixes are encrypted with a password","Reversing the mix (recovering a private secret from a public mix) is computationally infeasible","The eavesdropper is blocked by the firewall","The shared secret is sent separately over the wire"],"correct":1,"explanation":"DH relies on a one-way operation: mixing is easy, un-mixing is not. Eve sees the common value and both public mixes, but recovering either private secret from them is infeasible — so she cannot derive the shared secret, which itself is never transmitted."},{"id":"under-the-hood/https-and-tls#1","route":"/under-the-hood/https-and-tls","section":"under-the-hood","subject":"cs-core","title":"HTTPS and TLS","question":"What problem do TLS certificates solve that key exchange alone does not?","options":["They make encryption faster","They compress the data","They authenticate identity — proving the public key belongs to the real server, stopping man-in-the-middle attacks","They store the session keys on disk"],"correct":2,"explanation":"Key exchange establishes a shared secret with *someone*, but not *who*. A certificate, signed by a CA and validated up a chain to a trusted root, binds the server's identity to its key — preventing an attacker from silently sitting in the middle."},{"id":"under-the-hood/https-and-tls#2","route":"/under-the-hood/https-and-tls","section":"under-the-hood","subject":"cs-core","title":"HTTPS and TLS","question":"How does TLS 1.3 complete its handshake in a single round trip?","options":["It skips certificate verification","It uses no encryption during the handshake","The client sends its key share in the very first message, so keys are ready after one there-and-back","It reuses the same key for every connection"],"correct":2,"explanation":"TLS 1.3 puts the client's Diffie-Hellman key share in the ClientHello. The server replies with its share, certificate, and Finished in one flight, so both sides can derive keys after a single round trip — versus two in TLS 1.2."},{"id":"under-the-hood/inheritance-and-mro#0","route":"/under-the-hood/inheritance-and-mro","section":"under-the-hood","subject":"cs-core","title":"Inheritance and MRO","question":"For class D(B, C) where B(A) and C(A), what is D's MRO?","options":["[D, A, B, C, object]","[D, B, A, C, A, object]","[D, B, C, A, object]","[D, C, B, A, object]"],"correct":2,"explanation":"C3 linearization gives [D, B, C, A, object]: the class first, then its parents in declaration order (B before C), then their shared ancestor A once, then object. A appears a single time — so its __init__ runs once."},{"id":"under-the-hood/inheritance-and-mro#1","route":"/under-the-hood/inheritance-and-mro","section":"under-the-hood","subject":"cs-core","title":"Inheritance and MRO","question":"Both C and A define greet(). With MRO [D, B, C, A, object], which runs for d.greet()?","options":["A.greet — it is the original","C.greet — C precedes A in the MRO","Both run, A then C","It raises an ambiguity error"],"correct":1,"explanation":"Lookup scans the MRO front to back and stops at the first match. C comes before A, so C.greet() runs and the search stops. Order in the MRO, not depth in the tree, decides the winner."},{"id":"under-the-hood/inheritance-and-mro#2","route":"/under-the-hood/inheritance-and-mro","section":"under-the-hood","subject":"cs-core","title":"Inheritance and MRO","question":"What does super() actually refer to inside a method?","options":["The class's directly declared base class, always","The next class after the current one in the object's MRO","The root of the hierarchy (object)","A copy of the parent instance"],"correct":1,"explanation":"super() delegates to the next class in the current instance's MRO — not a fixed parent. This is what makes cooperative multiple inheritance work: each class's super() call chains to the next entry, visiting the whole diamond once in MRO order."},{"id":"under-the-hood/jit-compilation#0","route":"/under-the-hood/jit-compilation","section":"under-the-hood","subject":"cs-core","title":"JIT Compilation","question":"What information does a JIT have that an ahead-of-time compiler fundamentally cannot?","options":["The CPU model it is running on","The actual types, branch outcomes and call targets the code produced on real input","The total size of the source file","Which functions the programmer marked as hot"],"correct":1,"explanation":"Because it compiles while the program runs, a JIT can observe what actually happened — this element access has been a small integer 40,000 times, this branch is never taken, this call always lands on the same function. An AOT compiler must emit code that handles everything it cannot rule out statically. That observed profile is what makes speculative optimization possible."},{"id":"under-the-hood/jit-compilation#1","route":"/under-the-hood/jit-compilation","section":"under-the-hood","subject":"cs-core","title":"JIT Compilation","question":"Why do engines use multiple compilation tiers instead of always producing the best code?","options":["Because the optimizing compiler cannot handle all bytecode","To reduce memory usage of the compiler","Because optimizing is expensive — spending milliseconds of CPU on a function that runs briefly is a net loss, so cheap code is used until a counter proves the function is worth more","Because the interpreter cannot collect type feedback at higher tiers"],"correct":2,"explanation":"Optimization costs real CPU time, taken from the running program. Tiering is bet sizing: interpret first (free), compile generic baseline code once a function is warm (cheap), and only invoke the expensive optimizing compiler when the counter shows the function is genuinely hot enough to repay it."},{"id":"under-the-hood/jit-compilation#2","route":"/under-the-hood/jit-compilation","section":"under-the-hood","subject":"cs-core","title":"JIT Compilation","question":"A hot function that was monomorphic starts receiving a second argument type. What happens?","options":["The optimized code silently handles it, since machine code is type-agnostic","The program throws a type error","The guard fails, the engine deoptimizes back to the interpreter by reconstructing a frame, re-profiles, and may recompile with weaker assumptions","The engine permanently disables the JIT for the whole program"],"correct":2,"explanation":"The optimized code was compiled assuming a specific shape, protected by a cheap guard. When the guard fails the engine must rebuild the interpreter frame that would have existed at that bytecode offset — using recorded deoptimization metadata — and resume there. The function re-profiles and may be recompiled less aggressively. Repeated cycles of this are the \"deopt loop\" performance pathology."},{"id":"under-the-hood/multithreading#0","route":"/under-the-hood/multithreading","section":"under-the-hood","subject":"cs-core","title":"Multithreading","question":"Two threads each run counter++ 1 000 times. Without synchronization, what is the most likely final value?","options":["Somewhere between 1 000 and 2 000 — non-deterministic","Exactly 2 000 — the result is always correct","Always 1 000 — one thread's work is always lost","It depends on the programming language"],"correct":0,"explanation":"counter++ is not atomic — it compiles to READ / ADD / WRITE. Context switches between these steps cause lost updates. The result is non-deterministic, typically between 1 000 and 2 000, varying every run."},{"id":"under-the-hood/multithreading#1","route":"/under-the-hood/multithreading","section":"under-the-hood","subject":"cs-core","title":"Multithreading","question":"Which of the four Coffman conditions must be broken to prevent deadlock?","options":["Break circular wait — acquire all locks in a consistent global order","Break mutual exclusion — allow multiple threads per lock","Break hold-and-wait — threads must acquire all locks at startup","Any one of the four conditions is sufficient"],"correct":3,"explanation":"Breaking ANY one of the four conditions prevents deadlock. In practice: breaking circular wait (lock ordering) is simplest. Breaking hold-and-wait (acquire all at once) is sometimes used in databases. Breaking mutual exclusion is only possible for read-only resources."},{"id":"under-the-hood/multithreading#2","route":"/under-the-hood/multithreading","section":"under-the-hood","subject":"cs-core","title":"Multithreading","question":"Thread 1: lock(A) → lock(B). Thread 2: lock(B) → lock(A). What is the risk?","options":["Deadlock — if each thread acquires its first lock simultaneously","Race condition — both threads can enter the critical section at once","Starvation — Thread 2 will never get CPU time","No risk — mutexes prevent all concurrency bugs automatically"],"correct":0,"explanation":"Different lock-acquisition orders create a circular dependency. If T1 holds A and T2 holds B simultaneously, each waits for the other's lock forever — textbook deadlock. Fix: both threads must acquire A before B."},{"id":"under-the-hood/polymorphism-and-virtual-dispatch#0","route":"/under-the-hood/polymorphism-and-virtual-dispatch","section":"under-the-hood","subject":"cs-core","title":"Polymorphism and Virtual Dispatch","question":"What is stored in a vtable?","options":["The values of the object's data members","One function pointer per virtual method of the class","A copy of every object of that class","The class's inheritance tree"],"correct":1,"explanation":"A vtable is a per-class array of function pointers — one slot per virtual method, pointing at that class's implementation. All objects of the class share the single vtable; overriding changes which function a slot points to."},{"id":"under-the-hood/polymorphism-and-virtual-dispatch#1","route":"/under-the-hood/polymorphism-and-virtual-dispatch","section":"under-the-hood","subject":"cs-core","title":"Polymorphism and Virtual Dispatch","question":"During s->draw() on a virtual method, what is fixed at compile time vs decided at runtime?","options":["Both are fixed at compile time","The slot index is fixed at compile time; the vtable (via the object's vptr) is chosen at runtime","Both are chosen at runtime","The function address is fixed; only the arguments vary"],"correct":1,"explanation":"The compiler knows draw() is, say, slot [0] — that index is fixed. What varies at runtime is which vtable the object's vptr points to, so the same slot resolves to Circle::draw or Square::draw depending on the actual object."},{"id":"under-the-hood/polymorphism-and-virtual-dispatch#2","route":"/under-the-hood/polymorphism-and-virtual-dispatch","section":"under-the-hood","subject":"cs-core","title":"Polymorphism and Virtual Dispatch","question":"Why is a virtual call more expensive than a non-virtual one?","options":["It copies the whole object first","It adds two dependent memory loads (vptr, then vtable slot) plus an indirect call, and usually blocks inlining","It recompiles the function each time","It locks a mutex"],"correct":1,"explanation":"A non-virtual call is a direct, inlinable jump. A virtual call must load the vptr from the object, load the function pointer from the vtable, then call indirectly — a few cycles, and the indirection typically prevents inlining. That overhead is why virtual is opt-in in C++."},{"id":"under-the-hood/processes-vs-threads#0","route":"/under-the-hood/processes-vs-threads","section":"under-the-hood","subject":"cs-core","title":"Processes vs Threads","question":"Two threads in the same process — what do they share, and what stays private?","options":["They share everything, including the stack","They share code, data, and heap; each has its own stack and registers","They share only the stack","Nothing is shared — threads are fully isolated"],"correct":1,"explanation":"Threads live in one address space, so code, global data, and the heap are shared (one copy, visible to all). Each thread has its own stack (call frames + locals) plus its own registers and program counter. Shared heap is exactly why threads need locks."},{"id":"under-the-hood/processes-vs-threads#1","route":"/under-the-hood/processes-vs-threads","section":"under-the-hood","subject":"cs-core","title":"Processes vs Threads","question":"What does copy-on-write achieve after fork()?","options":["It encrypts the child's memory","It eagerly copies the whole address space for safety","Parent and child share physical pages until one writes, then only that page is copied","It prevents the child from ever writing memory"],"correct":2,"explanation":"Copy-on-write shares the parent's pages with the child as read-only. Only when one side writes a page does the kernel duplicate that single page. Unmodified pages stay shared, making fork() fast and memory-efficient."},{"id":"under-the-hood/processes-vs-threads#2","route":"/under-the-hood/processes-vs-threads","section":"under-the-hood","subject":"cs-core","title":"Processes vs Threads","question":"Why is switching between two processes more expensive than between two threads of one process?","options":["Processes have smaller stacks","A process switch must also swap the page table and flush the TLB; threads share the address space so it stays warm","Threads cannot be switched at all","Processes do not use registers"],"correct":1,"explanation":"Both switches save/restore registers. But a process switch also changes the active address space — swapping the page table and flushing the TLB — so address translations must be rebuilt cold. Threads of the same process share the address space, so that cost is avoided."},{"id":"under-the-hood/python-execution-pipeline#0","route":"/under-the-hood/python-execution-pipeline","section":"under-the-hood","subject":"cs-core","title":"Python Execution Pipeline","question":"What is Python's intermediate representation between source code and the interpreter?","options":["Machine code (x86-64 assembly)","LLVM IR (like Clang/Swift use)","Bytecode — stored in .pyc files in __pycache__","An interpreted S-expression tree"],"correct":2,"explanation":"Python compiles source to bytecode (.pyc), which the CPython virtual machine then interprets. This is why Python starts faster than a fully compiled language (no linker) but runs slower (still interpreted). Use `import dis; dis.dis(fn)` to see the bytecode."},{"id":"under-the-hood/python-execution-pipeline#1","route":"/under-the-hood/python-execution-pipeline","section":"under-the-hood","subject":"cs-core","title":"Python Execution Pipeline","question":"Why does `a = 3; b = 3; a is b` return True in CPython, but `a = 300; b = 300; a is b` returns False?","options":["Python optimizes repeated literals at compile time","CPython pre-allocates (\"interns\") integers from -5 to 256 as singletons","The `is` operator compares values, not identity, for small numbers","3 is a one-digit number; 300 requires two digits internally"],"correct":1,"explanation":"CPython keeps a global array of 262 pre-allocated PyLongObject singletons for integers -5 to 256. Every `x = 3` just returns a pointer to the same cached object — no allocation. 300 > 256, so each assignment creates a new PyLongObject on the heap. Never use `is` to compare numbers; always use `==`."},{"id":"under-the-hood/python-execution-pipeline#2","route":"/under-the-hood/python-execution-pipeline","section":"under-the-hood","subject":"cs-core","title":"Python Execution Pipeline","question":"What does the GIL prevent, and what does it NOT prevent?","options":["Prevents all concurrency; Python has no threading whatsoever","Prevents true CPU parallelism in threads; does NOT prevent I/O concurrency","Prevents race conditions; does NOT prevent deadlocks","Prevents circular reference memory leaks; does NOT affect thread speed"],"correct":1,"explanation":"The GIL ensures only one thread executes bytecode at a time, preventing true CPU parallelism for CPU-bound tasks. However, threads DO release the GIL during I/O operations (network, disk, sleep), so I/O-bound programs benefit from threading. For CPU-bound parallel work, use `multiprocessing` or C extensions that release the GIL (like NumPy)."},{"id":"under-the-hood/python-memory-model#0","route":"/under-the-hood/python-memory-model","section":"under-the-hood","subject":"cs-core","title":"Python Memory Model","question":"a = [1,2,3]; b = a; b.append(4). What does print(a) output?","options":["[1, 2, 3, 4]","[1, 2, 3]","Error — b is immutable","Depends on Python version"],"correct":0,"explanation":"b = a copies the reference, not the list. Both a and b point to the same list object. b.append(4) mutates that shared object, so a also sees the change. Use a[:] or list(a) for a shallow copy."},{"id":"under-the-hood/python-memory-model#1","route":"/under-the-hood/python-memory-model","section":"under-the-hood","subject":"cs-core","title":"Python Memory Model","question":"Why is `x = 256; y = 256; x is y` True, but `x = 1000; y = 1000; x is y` False?","options":["CPython caches integers -5 to 256; 1000 is outside this range so two objects are created","Python uses \"is\" for integers up to 256 and \"==\" for larger values","Integers over 256 are stored as floats","This only happens in CPython, not in PyPy"],"correct":0,"explanation":"The small int cache pre-allocates -5..256 at interpreter startup. Any assignment within that range returns the same cached object. 1000 is outside the cache so each assignment allocates a new PyLong — different addresses, different identity."},{"id":"under-the-hood/python-memory-model#2","route":"/under-the-hood/python-memory-model","section":"under-the-hood","subject":"cs-core","title":"Python Memory Model","question":"A closure captures the variable count via nonlocal. What happens to the cell object after make_counter() returns?","options":["It stays alive on the heap because the inner function holds a reference to it","It is garbage collected immediately when make_counter's frame is destroyed","It is copied into the inner function's locals","It raises a NameError if accessed after make_counter returns"],"correct":0,"explanation":"The cell object is heap-allocated and its refcount is held by the closure (the returned inner function). When make_counter's frame is freed, the cell's refcount stays above zero because the closure still references it — so it lives as long as the closure lives."},{"id":"under-the-hood/system-calls-and-kernel-mode#0","route":"/under-the-hood/system-calls-and-kernel-mode","section":"under-the-hood","subject":"cs-core","title":"System Calls and Kernel Mode","question":"Why does the syscall instruction jump to an address the kernel registered, instead of one the caller supplies?","options":["It is faster to use a fixed address","Because letting user code choose the destination would let it enter the kernel past the validation and dispatch logic","Registers cannot hold a jump target","The kernel address is not known at compile time"],"correct":1,"explanation":"The instruction raises privilege from ring 3 to ring 0, so the destination has to be trustworthy. It comes from the LSTAR register, which only ring 0 can write and the kernel sets at boot. User code controls when it enters the kernel, never where — otherwise a program could jump straight past argument checking into privileged code."},{"id":"under-the-hood/system-calls-and-kernel-mode#1","route":"/under-the-hood/system-calls-and-kernel-mode","section":"under-the-hood","subject":"cs-core","title":"System Calls and Kernel Mode","question":"What is the difference between a mode switch and a context switch?","options":["They are two names for the same thing","A mode switch changes privilege level within the same process; a context switch swaps to a different process, with new page tables and cold caches","A context switch is cheaper because it stays in the kernel","A mode switch only happens on interrupts"],"correct":1,"explanation":"A syscall performs a mode switch: same process, same address space, privilege level 3 → 0 and back. A context switch replaces the running process entirely — different page tables, a TLB flush, and a cold cache for the incoming process. That is why a context switch costs microseconds while a syscall costs tens to hundreds of nanoseconds."},{"id":"under-the-hood/system-calls-and-kernel-mode#2","route":"/under-the-hood/system-calls-and-kernel-mode","section":"under-the-hood","subject":"cs-core","title":"System Calls and Kernel Mode","question":"Why must the kernel use copy_from_user() rather than dereferencing a user-supplied pointer directly?","options":["To convert between endiannesses","Because user pointers use virtual addresses and the kernel uses physical ones","Because the pointer is fully attacker-controlled — it must be checked to actually belong to the calling process, not to kernel memory","Because user memory is always read-only from ring 0"],"correct":2,"explanation":"Running in ring 0, the kernel can dereference anything — including kernel memory. A process could pass a kernel address as its \"buffer\" and trick the kernel into reading or writing it. copy_from_user() validates that the range really belongs to the calling process's address space and handles faults safely. Every argument crossing the boundary is treated as hostile."},{"id":"under-the-hood/unicode-and-utf-8#0","route":"/under-the-hood/unicode-and-utf-8","section":"under-the-hood","subject":"cs-core","title":"Unicode and UTF-8","question":"What makes UTF-8 \"self-synchronizing\"?","options":["Every character is exactly the same number of bytes","Continuation bytes always start with 10, so scanning back to the first byte that does not gives you a character boundary","A byte order mark at the start of every file","Each character ends with a null terminator"],"correct":1,"explanation":"Lead bytes start 0, 110, 1110 or 11110; continuation bytes always start 10. So from any position in the stream you can find the next character boundary by skipping bytes that begin with 10. Corruption or truncation costs one character rather than desynchronizing the whole remaining stream — exactly what you want in a network protocol or log file."},{"id":"under-the-hood/unicode-and-utf-8#1","route":"/under-the-hood/unicode-and-utf-8","section":"under-the-hood","subject":"cs-core","title":"Unicode and UTF-8","question":"In JavaScript, why does the family emoji 👨‍👩‍👧 report a .length of 8?","options":["It is a bug in the JavaScript engine","The string contains eight separate emoji characters","It is three emoji joined by two zero-width joiners — five code points, which take eight UTF-16 units because the three people emoji are each surrogate pairs",".length counts bytes, and the emoji is eight bytes"],"correct":2,"explanation":"It is one grapheme cluster built from five code points: man, ZWJ, woman, ZWJ, girl. Each person emoji is above U+FFFF so it needs a surrogate pair (2 units each = 6), plus 1 unit for each of the two ZWJs, giving 8. It is also 18 bytes in UTF-8. Four different correct counts for four different questions."},{"id":"under-the-hood/unicode-and-utf-8#2","route":"/under-the-hood/unicode-and-utf-8","section":"under-the-hood","subject":"cs-core","title":"Unicode and UTF-8","question":"Two strings render identically on screen but === returns false. What is the most likely cause and fix?","options":["One has trailing whitespace; trim both","They use different Unicode normalization forms (e.g. é as one code point vs e + combining accent); normalize both to NFC before comparing","One is UTF-8 and the other UTF-16; convert one","JavaScript cannot compare non-ASCII strings"],"correct":1,"explanation":"The same visible character often has both a precomposed form (U+00E9) and a decomposed one (e + U+0301). They render identically but are different byte sequences, so equality fails. Calling .normalize(\"NFC\") on both before comparing, hashing, or storing as a key fixes it. This is a common source of duplicate rows and failed name matches across operating systems."},{"id":"under-the-hood/virtual-memory-and-paging#0","route":"/under-the-hood/virtual-memory-and-paging","section":"under-the-hood","subject":"cs-core","title":"Virtual Memory and Paging","question":"What does the TLB do, and why does it matter?","options":["It stores files on disk for swapping","It caches recent VPN→frame translations so most accesses skip the page table (≈1 cycle)","It splits the virtual address into VPN and offset","It assigns each process its own address space"],"correct":1,"explanation":"The Translation Lookaside Buffer is a small, very fast hardware cache of recent page translations. On a hit (the common case, thanks to locality) it resolves a VPN to a frame in about one cycle, avoiding a slow page-table walk in RAM."},{"id":"under-the-hood/virtual-memory-and-paging#1","route":"/under-the-hood/virtual-memory-and-paging","section":"under-the-hood","subject":"cs-core","title":"Virtual Memory and Paging","question":"A page-table entry is marked \"not present\" when the CPU accesses it. What happens?","options":["The program crashes immediately","The offset is used directly as the physical address","A page fault traps into the OS, which loads the page from disk into a free frame and retries the instruction","The TLB is flushed and the access is skipped"],"correct":2,"explanation":"A not-present entry triggers a page fault — a trap into the OS. The handler brings the page in from disk (swap) into a physical frame, updates the page table to present, and re-runs the faulting instruction. This is demand paging."},{"id":"under-the-hood/virtual-memory-and-paging#2","route":"/under-the-hood/virtual-memory-and-paging","section":"under-the-hood","subject":"cs-core","title":"Virtual Memory and Paging","question":"How does paging give two processes the same virtual address without conflict?","options":["Each process runs on a different CPU core","Virtual addresses are randomized per process","Each process has its own page table, so identical VPNs map to different physical frames","The offset bits differ between processes"],"correct":2,"explanation":"Every process has a private page table. The same virtual address translates through different mappings to different physical frames, so processes are isolated — one cannot even name another's memory. Permission bits per entry add protection on top."},{"id":"under-the-hood/what-happens-when-you-search-a-url#0","route":"/under-the-hood/what-happens-when-you-search-a-url","section":"under-the-hood","subject":"cs-core","title":"What Happens When You Search a URL","question":"What is the correct order of DNS resolution for a completely uncached domain?","options":["Browser cache → OS cache → TLD nameserver → Root nameserver","Browser cache → OS cache → Recursive resolver → Root → TLD → Authoritative","Root nameserver → TLD nameserver → Authoritative → Browser","ISP resolver → Root nameserver → Authoritative → OS cache"],"correct":1,"explanation":"DNS resolution always checks local caches first (browser, then OS), then delegates to a recursive resolver which queries Root → TLD → Authoritative in that order."},{"id":"under-the-hood/what-happens-when-you-search-a-url#1","route":"/under-the-hood/what-happens-when-you-search-a-url","section":"under-the-hood","subject":"cs-core","title":"What Happens When You Search a URL","question":"What does the TCP three-way handshake accomplish before HTTP data is sent?","options":["It establishes the TLS encryption keys for HTTPS","It determines which HTTP version to use (1.1 vs 2)","It proves bidirectional connectivity and synchronizes sequence numbers","It verifies the server's SSL certificate"],"correct":2,"explanation":"The three-way handshake (SYN → SYN-ACK → ACK) proves both client→server and server→client communication works, and synchronizes sequence numbers for reliable ordered delivery. TLS (encryption) happens afterward."},{"id":"under-the-hood/what-happens-when-you-search-a-url#2","route":"/under-the-hood/what-happens-when-you-search-a-url","section":"under-the-hood","subject":"cs-core","title":"What Happens When You Search a URL","question":"Which type of HTML resource blocks the browser's HTML parser while it downloads and executes?","options":["<link rel=\"stylesheet\"> CSS files","<img> image tags","<script> tags without async or defer","<video> elements"],"correct":2,"explanation":"A <script> without async or defer forces the HTML parser to stop completely until the script downloads and executes. This is why scripts are often placed at the bottom of <body> or given the defer attribute. CSS blocks rendering but not parsing; images and video are non-blocking."},{"id":"union-find/path-compression#0","route":"/union-find/path-compression","section":"union-find","subject":"dsa","title":"Path Compression","question":"What does path compression do to the parent pointers after find(x)?","options":["Deletes intermediate nodes","Makes all nodes on the path point directly to the root","Reverses the path direction","Copies the root node for every member"],"correct":1,"explanation":"Path compression re-points every node visited during find(x) directly to the root, flattening the tree for all future operations through those nodes."},{"id":"union-find/path-compression#1","route":"/union-find/path-compression","section":"union-find","subject":"dsa","title":"Path Compression","question":"What is the amortized cost per operation with path compression alone (without union by rank)?","options":["O(1)","O(log n)","O(log* n)","O(α(n))"],"correct":2,"explanation":"Path compression alone gives O(log* n) amortized (iterated logarithm). Combined with union by rank it improves to O(α(n)) — the inverse Ackermann function."},{"id":"union-find/path-compression#2","route":"/union-find/path-compression","section":"union-find","subject":"dsa","title":"Path Compression","question":"After a find(x) with a path of length 5, how many additional steps does the same find(x) cost?","options":["5","4","1 (just returns parent[x])","0 (already cached)"],"correct":2,"explanation":"After compression, parent[x] = root directly. A second find(x) follows exactly one pointer — O(1) — regardless of the original chain length."},{"id":"union-find/quick-find#0","route":"/union-find/quick-find","section":"union-find","subject":"dsa","title":"Quick Find","question":"What is the time complexity of find() in Quick Find?","options":["O(n)","O(log n)","O(1)","O(n²)"],"correct":2,"explanation":"find(x) simply returns id[x] — a direct array lookup, O(1)."},{"id":"union-find/quick-find#1","route":"/union-find/quick-find","section":"union-find","subject":"dsa","title":"Quick Find","question":"Why is union() O(n) in Quick Find?","options":["It must traverse a tree to the root","It scans the entire array to relabel all elements in one component","It allocates a new array each time","It calls find() n times"],"correct":1,"explanation":"union(p, q) iterates over every element and relabels those with id[p] to id[q] — unavoidably O(n)."},{"id":"union-find/quick-find#2","route":"/union-find/quick-find","section":"union-find","subject":"dsa","title":"Quick Find","question":"How many components are there after n union() calls on n elements (assuming all different pairs)?","options":["n","1","n/2","Depends on which pairs"],"correct":1,"explanation":"If the union operations form a spanning tree (connect everything), exactly 1 component remains. The answer depends on which pairs are unioned."},{"id":"union-find/quick-union#0","route":"/union-find/quick-union","section":"union-find","subject":"dsa","title":"Quick Union","question":"What is the worst-case time for find() in Quick Union?","options":["O(1)","O(log n)","O(n)","O(n²)"],"correct":2,"explanation":"In the worst case, repeated unions create a \"tall\" linear chain. find() must follow n parent pointers, giving O(n)."},{"id":"union-find/quick-union#1","route":"/union-find/quick-union","section":"union-find","subject":"dsa","title":"Quick Union","question":"After union(p, q), which root becomes the child?","options":["p's root","q's root","The one with more elements","It alternates each call"],"correct":0,"explanation":"Quick Union sets parent[root(p)] = root(q), making p's root a child of q's root."},{"id":"union-find/quick-union#2","route":"/union-find/quick-union","section":"union-find","subject":"dsa","title":"Quick Union","question":"What makes Quick Union potentially worse than Quick Find in practice?","options":["It uses more memory","find() can be O(n) on degenerate tall trees, making union() also O(n)","It cannot handle disconnected components","union() is O(n²)"],"correct":1,"explanation":"Quick Union's union() calls find() twice. If trees become tall chains (O(n) each), the amortized cost per operation degrades, erasing the advantage over Quick Find."},{"id":"union-find/union-by-rank#0","route":"/union-find/union-by-rank","section":"union-find","subject":"dsa","title":"Union by Rank","question":"When does union by rank increment a root's rank?","options":["Every union operation","When the two roots have equal rank","When the attached tree is taller","Never — rank is read-only"],"correct":1,"explanation":"Rank only increments when two trees of equal rank merge. The winner gets rank+1. Otherwise the loser is attached under the winner and no ranks change."},{"id":"union-find/union-by-rank#1","route":"/union-find/union-by-rank","section":"union-find","subject":"dsa","title":"Union by Rank","question":"What is the maximum tree height with union by rank on n elements?","options":["n","n/2","log₂(n)","√n"],"correct":2,"explanation":"Union by rank guarantees tree height ≤ log₂(n). A tree of rank r has at least 2^r nodes, so rank ≤ log₂(n) — bounding the find() chain length."},{"id":"union-find/union-by-rank#2","route":"/union-find/union-by-rank","section":"union-find","subject":"dsa","title":"Union by Rank","question":"Why is union by rank + path compression better than either alone?","options":["It uses less space","Rank prevents deep trees; compression flattens them further — giving O(α(n)) amortized per op","It allows undoing unions","It avoids the need for the parent array"],"correct":1,"explanation":"Union by rank bounds height at O(log n); path compression flattens each found path to 1. Together the amortized cost is O(α(n)) — inverse Ackermann, effectively constant."}];
